// Column B draft for reading aloud, 24 Oct–26 Dec 2026.
// Each line is [russian, dutch, note]. The note is empty unless JPS and the French diverge, or the Hebrew is obscure.
// This is not a published translation.

export type PassageTranslationLang = 'ru' | 'nl' | 'en' | 'fr';

export type DraftLine = { ru: string; nl: string; note: string };

const LINES: Record<string, readonly [string, string, string]> = {"genesis-14-1":["В дни Амрафеля, царя Шинъара, Арьоха, царя Элласара, Кедорлаомера, царя Эйлама, и Тидаля, царя Гоим,","In de dagen van Amrafel, koning van Sinear, Arjoch, koning van Ellasar, Kedorlaomer, koning van Elam, en Tidal, koning van Gojim,",""],"genesis-14-2":["они пошли войной на Беру, царя Сдома, на Биршу, царя Аморы, на Шинава, царя Адмы, на Шемевера, царя Цевоима, и на царя Белы, то есть Цоара.","voerden zij oorlog met Bera, koning van Sedom, met Birsja, koning van Amora, met Sjinaav, koning van Adma, met Sjemever, koning van Tsevoïm, en met de koning van Bela, dat is Tsoar.",""],"genesis-14-3":["Все они сошлись в долине Сиддим — это Солёное море.","Zij allen kwamen samen in het dal Siddim — dat is de Zoutzee.",""],"genesis-14-4":["Двенадцать лет они служили Кедорлаомеру, а на тринадцатый год восстали.","Twaalf jaar dienden zij Kedorlaomer, en in het dertiende jaar kwamen zij in opstand.",""],"genesis-14-5":["В четырнадцатый год пришёл Кедорлаомер и цари, которые были с ним, и разбили рефаим в Аштерот-Карнаиме, зузим в Хаме и эмим в Шаве-Кирьятаиме,","In het veertiende jaar kwam Kedorlaomer met de koningen die bij hem waren, en zij versloegen de Refaïm in Asjterot-Karnajim, de Zoeziem in Ham en de Emim in Sjavé-Kirjataïm,",""],"genesis-14-6":["и хори в их горах Сеира, до Эль-Парана, что у пустыни.","en de Chori op hun berg Seïr, tot El-Paran, dat aan de woestijn ligt.","JPS: место El-paran; фр.: plaine de Pharan. По-еврейски אֵיל פָּארָן — местность Эль-Паран."],"genesis-14-7":["Они повернули, пришли в Эйн-Мишпат, то есть в Кадеш, и разбили всю землю амалекитян, а также эмори, которые жили в Хацацон-Тамаре.","Zij keerden om, kwamen bij Ein-Misjpat, dat is Kadesj, en versloegen heel het land van de Amalekieten en ook de Emori die in Chatsatson-Tamar woonden.",""],"genesis-14-8":["Вышли царь Сдома, царь Аморы, царь Адмы, царь Цевоима и царь Белы, то есть Цоара, и выстроились против них для войны в долине Сиддим:","Toen trokken de koning van Sedom, de koning van Amora, de koning van Adma, de koning van Tsevoïm en de koning van Bela, dat is Tsoar, uit en stelden zich tegen hen op voor de strijd in het dal Siddim:",""],"genesis-14-9":["против Кедорлаомера, царя Эйлама, Тидаля, царя Гоим, Амрафеля, царя Шинъара, и Арьоха, царя Элласара — четверо царей против пятерых.","tegen Kedorlaomer, koning van Elam, Tidal, koning van Gojim, Amrafel, koning van Sinear, en Arjoch, koning van Ellasar — vier koningen tegen de vijf.",""],"genesis-14-10":["Долина Сиддим была в смоляных ямах. Цари Сдома и Аморы побежали и упали туда, а уцелевшие бежали в горы.","Het dal Siddim zat vol pekputten. De koningen van Sedom en Amora vluchtten en vielen daarin, en wie overbleven vluchtten naar het gebergte.",""],"genesis-14-11":["Они забрали всё имущество Сдома и Аморы и весь их хлеб и ушли.","Zij namen alle have van Sedom en Amora en al hun voedsel en trokken weg.",""],"genesis-14-12":["Забрали и Лота, сына брата Аврама, вместе с его имуществом, и ушли. А Лот жил в Сдоме.","Zij namen ook Lot mee, de zoon van de broer van Avram, met zijn have, en trokken weg. Lot woonde in Sedom.",""],"genesis-14-13":["Пришёл спасшийся и рассказал Авраму, еврею. Тот жил у теребинтов Мамре-эмори, брата Эшколя и брата Анера, и они были в брите с Аврамом.","Een vluchteling kwam en vertelde het aan Avram, de Hebreeër. Die woonde bij de terebinten van Mamre, de Emori, broer van Esjkol en broer van Aner, en zij stonden met Avram in een briet.","JPS: terebinths; фр.: plaines. По-еврейски אֵלֹנֵי מַמְרֵא — теребинты Мамре."],"genesis-14-14":["Аврам услышал, что его брат взят в плен, вооружил своих выученных людей, рождённых в его доме, — триста восемнадцать — и преследовал до Дана.","Toen Avram hoorde dat zijn broer gevangen was weggevoerd, rustte hij zijn geoefende mannen uit, geboren in zijn huis, driehonderdachttien, en achtervolgde hen tot Dan.","JPS: his brother; фр.: son parent. По-еврейски אָחִיו — его брат; в 14:12 Лот назван сыном брата Аврама."],"genesis-14-15":["Ночью он разделил своих людей и напал на них, он и его слуги, разбил их и преследовал до Ховы, что слева от Дамаска.","Hij verdeelde zijn mannen en overviel hen in de nacht, hij en zijn dienaren, versloeg hen en achtervolgde hen tot Chova, links van Dammesek.",""],"genesis-14-16":["Он вернул всё имущество. Вернул и Лота, своего брата, и его имущество, а также женщин и народ.","Hij bracht alle have terug. Ook Lot, zijn broer, en zijn have bracht hij terug, en ook de vrouwen en het volk.",""],"genesis-14-17":["Царь Сдома вышел ему навстречу, когда Аврам возвращался после победы над Кедорлаомером и царями, которые были с ним, в долину Шаве, то есть в долину царя.","De koning van Sedom ging hem tegemoet, toen hij terugkwam van de overwinning op Kedorlaomer en de koningen die bij hem waren, in het dal Sjavé, dat is het Koningsdal.",""],"genesis-14-18":["Малки-Цедек, царь Шалема, вынес хлеб и вино. Он был священником Бога Всевышнего.","Malki-Tsedek, koning van Sjalem, bracht brood en wijn naar buiten. Hij was priester van God de Allerhoogste.",""],"genesis-14-19":["Он благословил его и сказал: «Благословен Аврам Богом Всевышним, Творцом неба и земли.","Hij zegende hem en zei: «Gezegend is Avram door God de Allerhoogste, Maker van hemel en aarde.",""],"genesis-14-20":["И благословен Бог Всевышний, который отдал твоих врагов в твою руку». И он дал ему десятую часть от всего.","En gezegend is God de Allerhoogste, die je vijanden in je hand heeft gegeven.» En hij gaf hem een tiende van alles.","Подлежащее וַיִּתֶּן־לוֹ не названо. Фр. прямо говорит, что десятину дал Аврам; обычное чтение то же."],"genesis-14-21":["Царь Сдома сказал Авраму: «Отдай мне людей, а имущество возьми себе».","De koning van Sedom zei tegen Avram: «Geef mij de mensen, de have mag jij houden.»",""],"genesis-14-22":["Аврам сказал царю Сдома: «Я поднял руку к Господу, Богу Всевышнему, Творцу неба и земли:","Avram zei tegen de koning van Sedom: «Ik heb mijn hand opgeheven naar de Eeuwige, God de Allerhoogste, Maker van hemel en aarde:",""],"genesis-14-23":["ни нитки, ни ремешка от сандалии — ничего из твоего я не возьму, чтобы ты не сказал: „это я обогатил Аврама“.","geen draad en geen riem van een sandaal, niets van wat van jou is zal ik nemen, zodat jij niet zegt: „ik heb Avram rijk gemaakt“.",""],"genesis-14-24":["Только то, что съели эти юноши, и долю людей, которые ходили со мной, — Анера, Эшколя и Мамре, — пусть они возьмут свою долю».","Alleen wat de jongemannen al hebben gegeten, en het deel van de mannen die met mij meegingen — Aner, Esjkol en Mamre — laten zij hun deel nemen.»",""],"genesis-15-1":["После этих событий было слово Господа к Авраму в видении: «Не бойся, Аврам. Я — щит тебе. Награда твоя очень велика».","Na deze dingen kwam het woord van de Eeuwige tot Avram in een visioen: «Wees niet bang, Avram. Ik ben een schild voor je. Je loon zal zeer groot zijn.»",""],"genesis-15-2":["Аврам сказал: «Господь Бог, что Ты дашь мне? Я ухожу бездетным, а распорядитель моего дома — Элиэзер из Дамаска».","Avram zei: «Eeuwige, God, wat wilt U mij geven? Ik ga kinderloos heen, en de beheerder van mijn huis is Eliëzer uit Dammesek.»","בֶּן־מֶשֶׁק בֵּיתִי тёмное место. JPS: possessor of my house; фр. добавляет fils adoptif. Переведено как распорядитель дома, без «приёмный сын»."],"genesis-15-3":["Аврам сказал: «Ты не дал мне потомства, и вот домочадец наследует мне».","Avram zei: «U hebt mij geen nageslacht gegeven, en zie, iemand uit mijn huis zal mij erven.»",""],"genesis-15-4":["И было слово Господа к нему: «Не он наследует тебе, а тот, кто выйдет из твоего чрева, — он наследует тебе».","Toen kwam het woord van de Eeuwige tot hem: «Niet deze zal jou erven, maar wie uit jouw lichaam voortkomt, die zal jou erven.»",""],"genesis-15-5":["Он вывел его наружу и сказал: «Посмотри на небо и сосчитай звёзды, если сможешь их сосчитать». И сказал ему: «Таким будет твоё потомство».","Hij leidde hem naar buiten en zei: «Kijk naar de hemel en tel de sterren, als je ze tellen kunt.» En Hij zei tegen hem: «Zo zal jouw nageslacht zijn.»",""],"genesis-15-6":["Он поверил Господу, и Он счёл это ему праведностью.","Hij vertrouwde op de Eeuwige, en Die rekende het hem als gerechtigheid.","JPS: righteousness; фр.: mérite. По-еврейски צְדָקָה — праведность, не христианское «вменение»."],"genesis-15-7":["И сказал ему: «Я — Господь, который вывел тебя из Ур-Касдим, чтобы отдать тебе эту землю в наследие».","En Hij zei tegen hem: «Ik ben de Eeuwige, die je uit Ur-Kasdim heeft geleid om je dit land in bezit te geven.»",""],"genesis-15-8":["Он сказал: «Господь Бог, по чему я узнаю, что я наследую её?»","Hij zei: «Eeuwige, God, waaraan zal ik weten dat ik het in bezit zal nemen?»",""],"genesis-15-9":["Он сказал ему: «Возьми Мне трёхлетнюю телицу, трёхлетнюю козу, трёхлетнего барана, горлицу и молодого голубя».","Hij zei tegen hem: «Neem voor Mij een driejarige vaars, een driejarige geit, een driejarige ram, een tortel en een jonge duif.»",""],"genesis-15-10":["Он взял всё это, рассёк их пополам и положил половину каждого напротив другой, а птиц не рассёк.","Hij nam dit alles, deelde ze middendoor en legde elke helft tegenover de andere. De vogels deelde hij niet.",""],"genesis-15-11":["Хищные птицы спустились на туши, и Аврам отогнал их.","Roofvogels daalden neer op de kadavers, en Avram joeg ze weg.",""],"genesis-15-12":["Солнце уже садилось, и крепкий сон напал на Аврама, и вот — ужас, великая тьма нападает на него.","De zon stond op het punt onder te gaan, en een diepe slaap viel op Avram, en zie: angst, een grote duisternis, viel op hem.",""],"genesis-15-13":["И сказал Авраму: «Знай твёрдо: твоё потомство будет пришельцем в чужой земле. Им будут служить, и те будут угнетать их четыреста лет.","En Hij zei tegen Avram: «Weet het zeker: jouw nageslacht zal vreemdeling zijn in een land dat niet van hen is. Men zal hen laten dienen en hen vierhonderd jaar verdrukken.",""],"genesis-15-14":["Но и тот народ, которому они будут служить, Я осужу, а потом они выйдут с большим имуществом.","Maar ook het volk dat zij zullen dienen, zal Ik vonnissen, en daarna zullen zij wegtrekken met veel have.",""],"genesis-15-15":["А ты отойдёшь к своим отцам в мире и будешь погребён в доброй старости.","Jij zult in vrede tot je vaderen gaan. Je zult begraven worden in een goede ouderdom.",""],"genesis-15-16":["Четвёртое поколение вернётся сюда, потому что вина эмори до сих пор не полна».","Het vierde geslacht zal hier terugkomen, want de schuld van de Emori is tot nu toe niet vol.»",""],"genesis-15-17":["Солнце зашло, и была тьма. И вот дымящаяся печь и огненный факел прошли между этими частями.","De zon was ondergegaan en het was duister. En zie, een rokende oven en een vlammende fakkel gingen tussen deze stukken door.","JPS: smoking furnace and flaming torch; фр.: tourbillon de fumée et sillon de feu. По-еврейски תַּנּוּר עָשָׁן וְלַפִּיד אֵשׁ — дымящаяся печь и огненный факел."],"genesis-15-18":["В тот день Господь заключил с Аврамом брит и сказал: «Твоему потомству Я отдал эту землю, от реки Египта до великой реки, реки Перат:","Op die dag sloot de Eeuwige een briet met Avram en zei: «Aan jouw nageslacht heb Ik dit land gegeven, van de rivier van Egypte tot de grote rivier, de rivier Perat:",""],"genesis-15-19":["кени, книззи и кадмони,","de Keni, de Kenizzi en de Kadmoni,",""],"genesis-15-20":["хеттов, перизеев и рефаим,","de Chitti, de Perizzi en de Refaïm,",""],"genesis-15-21":["эмори, кнаани, гиргаши и евусеев».","de Emori, de Kenaäniet, de Girgasji en de Jevusiet.»",""],"joshua-24-1":["Йехошуа собрал все колена Исраэля в Шехем. Он призвал старейшин Исраэля, его глав, его судей и его надзирателей, и они встали перед Богом.","Jehosjoea riep alle stammen van Israël bijeen in Sjechem. Hij riep de oudsten van Israël, zijn hoofden, zijn rechters en zijn opzieners, en zij stelden zich op voor God.",""],"joshua-24-2":["Йехошуа сказал всему народу: «Так сказал Господь, Бог Исраэля: „За Рекой издавна жили ваши отцы — Терах, отец Авраама и отец Нахора, — и служили другим богам.","Jehosjoea zei tegen heel het volk: «Zo zegt de Eeuwige, de God van Israël: „Aan de overkant van de Rivier woonden jullie vaderen van oudsher — Terach, de vader van Abraham en de vader van Nachor — en zij dienden andere goden.",""],"joshua-24-3":["Я взял вашего отца Авраама из-за Реки, водил его по всей земле Кнаан, умножил его потомство и дал ему Ицхака.","Ik nam jullie vader Abraham van de overkant van de Rivier, liet hem door heel het land Kenaän gaan, maakte zijn nageslacht talrijk en gaf hem Jitschak.",""],"joshua-24-4":["Ицхаку Я дал Яакова и Эсава. Эсаву Я дал гору Сеир, чтобы владеть ею, а Яаков и его сыновья спустились в Египет.","Aan Jitschak gaf Ik Jaäkov en Esav. Aan Esav gaf Ik het Seïr-gebergte om het in bezit te nemen, en Jaäkov en zijn kinderen daalden af naar Egypte.",""],"joshua-24-5":["Я послал Моше и Аарона и поразил Египет тем, что сделал в нём, а потом вывел вас.","Ik zond Mosje en Aharon en trof Egypte met wat Ik in zijn midden deed, en daarna leidde Ik jullie uit.",""],"joshua-24-6":["Я вывел ваших отцов из Египта, и вы пришли к морю, а египтяне погнались за вашими отцами на колесницах и на конях до Тростникового моря.","Ik leidde jullie vaderen uit Egypte, en jullie kwamen bij de zee. De Egyptenaren achtervolgden jullie vaderen met wagens en ruiters tot aan de Rietzee.","JPS: Red Sea; фр.: mer des Joncs. По-еврейски יַם־סוּף — Тростниковое море."],"joshua-24-7":["Они воззвали к Господу, и Он положил тьму между вами и египтянами, навёл на них море, и оно покрыло их. Ваши глаза видели, что Я сделал в Египте. Потом вы жили в пустыне много дней.","Zij riepen tot de Eeuwige. Hij zette duisternis tussen jullie en de Egyptenaren, bracht de zee over hen, en die bedekte hen. Jullie ogen hebben gezien wat Ik in Egypte heb gedaan. Daarna woonden jullie vele dagen in de woestijn.",""],"joshua-24-8":["Я привёл вас в землю эмори, которые жили по ту сторону Ярдена. Они воевали с вами. Я отдал их в вашу руку, вы взяли их землю, и Я истребил их перед вами.","Ik bracht jullie naar het land van de Emori, die aan de overkant van de Jarden woonden. Zij streden tegen jullie. Ik gaf hen in jullie hand, jullie namen hun land in, en Ik vaagde hen weg voor jullie uit.",""],"joshua-24-9":["Поднялся Балак, сын Циппора, царь Моава, и воевал против Исраэля. Он послал и призвал Билама, сына Беора, чтобы проклясть вас.","Toen stond Balak op, de zoon van Tsippor, koning van Moav, en streed tegen Israël. Hij liet Bilam, de zoon van Beor, roepen om jullie te vervloeken.","Во французском источнике опечатка fis вместо fils. По-еврейски בֶּן — сын."],"joshua-24-10":["Но Я не захотел слушать Билама, и он ещё благословил вас, и Я избавил вас от его руки.","Maar Ik wilde niet naar Bilam luisteren. Hij zegende jullie juist, en Ik redde jullie uit zijn hand.",""],"joshua-24-11":["Вы перешли Ярден и пришли к Йерихо. Против вас воевали хозяева Йерихо — эмори, перизеи, кнаани, хетты, гиргаши, хивви и евусеи, — и Я отдал их в вашу руку.","Jullie trokken de Jarden over en kwamen bij Jericho. De heren van Jericho streden tegen jullie: de Emori, de Perizzi, de Kenaäniet, de Chitti, de Girgasji, de Chivvi en de Jevusiet. Ik gaf hen in jullie hand.",""],"joshua-24-12":["Я послал перед вами шершней, и они прогнали их от вас — двух царей эмори, — не твоим мечом и не твоим луком.","Ik zond horzels voor jullie uit, en die dreven hen voor jullie weg, de twee koningen van de Emori, niet door jouw zwaard en niet door jouw boog.",""],"joshua-24-13":["Я дал вам землю, над которой ты не трудился, и города, которых вы не строили и в которых вы живёте. Вы едите от виноградников и олив, которых не сажали“.","Ik gaf jullie een land waar jij niet voor hebt gezwoegd, en steden die jullie niet hebben gebouwd en waar jullie wonen. Jullie eten van wijngaarden en olijfbomen die jullie niet hebben geplant.“",""],"joshua-24-14":["Теперь бойтесь Господа и служите Ему искренне и верно. Уберите богов, которым служили ваши отцы за Рекой и в Египте, и служите Господу.","Nu dan: vrees de Eeuwige en dien Hem oprecht en trouw. Doe de goden weg die jullie vaderen dienden aan de overkant van de Rivier en in Egypte, en dien de Eeuwige.",""],"joshua-24-15":["Если вам тягостно служить Господу, выберите сегодня, кому будете служить: богам, которым служили ваши отцы за Рекой, или богам эмори, в чьей земле вы живёте. А я и мой дом будем служить Господу».","Als het jullie slecht lijkt de Eeuwige te dienen, kies dan vandaag wie jullie willen dienen: de goden die jullie vaderen aan de overkant van de Rivier dienden, of de goden van de Emori in wier land jullie wonen. Maar ik en mijn huis, wij zullen de Eeuwige dienen.»",""],"joshua-24-16":["Народ ответил: «Этого не будет, чтобы мы оставили Господа и служили другим богам.","Het volk antwoordde: «Dat nooit, dat wij de Eeuwige zouden verlaten om andere goden te dienen.",""],"joshua-24-17":["Ведь Господь, наш Бог, — это Он вывел нас и наших отцов из земли Египта, из дома рабства. Он сделал у нас на глазах эти великие знамения и хранил нас на всём пути, которым мы шли, и среди всех народов, через которых мы проходили.","Want de Eeuwige, onze God, Hij is het die ons en onze vaderen uit het land Egypte heeft geleid, uit het slavenhuis. Hij heeft deze grote tekenen voor onze ogen gedaan en ons behoed op heel de weg die wij gingen, te midden van alle volken waar wij doorheen trokken.",""],"joshua-24-18":["Господь прогнал от нас все народы и эмори, жителя этой земли. Мы тоже будем служить Господу, потому что Он — наш Бог».","De Eeuwige dreef alle volken voor ons weg, en de Emori die het land bewoonde. Ook wij zullen de Eeuwige dienen, want Hij is onze God.»",""],"joshua-24-19":["Йехошуа сказал народу: «Вы не сможете служить Господу, потому что Он — святой Бог, Он — ревнивый Бог. Он не простит вашего преступления и ваших грехов.","Jehosjoea zei tegen het volk: «Jullie kunnen de Eeuwige niet dienen, want Hij is een heilige God, Hij is een jaloerse God. Hij zal jullie overtreding en jullie zonden niet vergeven.","Фр. добавляет aisément («нелегко»). В еврейском этого слова нет."],"joshua-24-20":["Если вы оставите Господа и будете служить чужим богам, Он обратится, сделает вам зло и истребит вас после того, как делал вам добро».","Als jullie de Eeuwige verlaten en vreemde goden dienen, zal Hij Zich keren, jullie kwaad doen en jullie vernietigen, nadat Hij jullie goed heeft gedaan.»",""],"joshua-24-21":["Народ сказал Йехошуа: «Нет! Мы будем служить Господу».","Het volk zei tegen Jehosjoea: «Nee! De Eeuwige zullen wij dienen.»",""],"joshua-24-22":["Йехошуа сказал народу: «Вы свидетели против самих себя, что выбрали себе Господа, чтобы служить Ему». Они сказали: «Свидетели».","Jehosjoea zei tegen het volk: «Jullie zijn getuigen tegen jezelf, dat jullie voor de Eeuwige hebben gekozen om Hem te dienen.» Zij zeiden: «Wij zijn getuigen.»",""],"joshua-24-23":["«Теперь уберите чужих богов, которые среди вас, и обратите сердце к Господу, Богу Исраэля».","«Doe nu de vreemde goden weg die bij jullie zijn, en richt jullie hart op de Eeuwige, de God van Israël.»",""],"joshua-24-24":["Народ сказал Йехошуа: «Господу, нашему Богу, мы будем служить, и Его голос будем слушать».","Het volk zei tegen Jehosjoea: «De Eeuwige, onze God, zullen wij dienen, en naar Zijn stem zullen wij luisteren.»",""],"joshua-24-25":["В тот день Йехошуа заключил с народом брит и установил ему закон и право в Шехеме.","Op die dag sloot Jehosjoea een briet met het volk en stelde voor hen een wet en een recht vast in Sjechem.",""],"joshua-24-26":["Йехошуа записал эти слова в книгу Торы Бога, взял большой камень и поставил его там, под дубом, что у святилища Господа.","Jehosjoea schreef deze woorden in het boek van de Tora van God. Hij nam een grote steen en zette die daar neer, onder de eik bij het heiligdom van de Eeuwige.",""],"genesis-19-30":["Лот поднялся из Цоара и поселился на горе, и две его дочери с ним, потому что он боялся жить в Цоаре. Он поселился в пещере, он и две его дочери.","Lot trok op uit Tsoar en ging op de berg wonen, en zijn twee dochters met hem, want hij was bang om in Tsoar te wonen. Hij ging in een grot wonen, hij en zijn twee dochters.",""],"genesis-19-31":["Старшая сказала младшей: «Наш отец стар, и нет на земле мужчины, который вошёл бы к нам, как это бывает на всей земле.","De oudste zei tegen de jongste: «Onze vader is oud, en er is geen man op de aarde die tot ons zou komen, zoals het gaat op heel de aarde.",""],"genesis-19-32":["Идём, напоим нашего отца вином и ляжем с ним, и сохраним потомство от нашего отца».","Kom, laten we onze vader wijn te drinken geven en bij hem gaan liggen, en laten we nageslacht van onze vader in leven houden.»",""],"genesis-19-33":["Они напоили своего отца вином в ту ночь. Старшая вошла и легла со своим отцом. Он не знал, когда она легла и когда встала.","Zij gaven hun vader die nacht wijn te drinken. De oudste kwam binnen en ging bij haar vader liggen. Hij wist het niet toen zij ging liggen en toen zij opstond.","JPS: knew not when she lay down; фр.: ne la reconnut point. По-еврейски לֹא־יָדַע בְּשִׁכְבָהּ — не знал, когда она легла."],"genesis-19-34":["На другой день старшая сказала младшей: «Вот, вчера ночью я легла со своим отцом. Напоим его вином и в эту ночь тоже. Войди и ляг с ним, и сохраним потомство от нашего отца».","De volgende dag zei de oudste tegen de jongste: «Kijk, vannacht heb ik bij mijn vader gelegen. Laten we hem ook deze nacht wijn te drinken geven. Ga naar binnen en ga bij hem liggen, en laten we nageslacht van onze vader in leven houden.»",""],"genesis-19-35":["В ту ночь они тоже напоили своего отца вином. Младшая встала и легла с ним. Он не знал, когда она легла и когда встала.","Ook die nacht gaven zij hun vader wijn te drinken. De jongste stond op en ging bij hem liggen. Hij wist het niet toen zij ging liggen en toen zij opstond.","JPS: knew not when; фр.: ne la reconnut point. По-еврейски לֹא־יָדַע בְּשִׁכְבָהּ וּבְקֻמָהּ — не знал, когда она легла и когда встала."],"genesis-19-36":["Обе дочери Лота зачали от своего отца.","De twee dochters van Lot werden zwanger van hun vader.",""],"genesis-19-37":["Старшая родила сына и назвала его Моав. Он отец Моава до сегодняшнего дня.","De oudste baarde een zoon en noemde hem Moav. Hij is de vader van Moav tot op deze dag.",""],"genesis-19-38":["Младшая тоже родила сына и назвала его Бен-Амми. Он отец сыновей Аммона до сегодняшнего дня.","Ook de jongste baarde een zoon en noemde hem Ben-Ammi. Hij is de vader van de zonen van Ammon tot op deze dag.",""],"genesis-20-1":["Авраам отправился оттуда в землю Негев, поселился между Кадешем и Шуром и был пришельцем в Граре.","Abraham trok van daar naar het land Negev, vestigde zich tussen Kadesj en Sjoer en was vreemdeling in Gerar.",""],"genesis-20-2":["Авраам сказал о Саре, своей жене: «Она моя сестра». Авимелех, царь Грара, послал и взял Сару.","Abraham zei van Sara, zijn vrouw: «Zij is mijn zuster.» Avimelech, de koning van Gerar, stuurde en nam Sara.",""],"genesis-20-3":["Бог пришёл к Авимелеху в ночном сне и сказал ему: «Вот, ты умрёшь из-за женщины, которую ты взял: она замужем».","God kwam tot Avimelech in een droom van de nacht en zei tegen hem: «Je zult sterven om de vrouw die je hebt genomen. Zij is de vrouw van een man.»","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-20-4":["Авимелех не приблизился к ней. Он сказал: «Владыка, неужели Ты убьёшь и праведный народ?","Avimelech was niet tot haar genaderd. Hij zei: «Heer, zult U ook een rechtvaardig volk doden?","В стихе אֲדֹנָי, не יהוה: Владыка / Heer. JPS: a righteous nation; фр.: un peuple innocent. По-еврейски גּוֹי צַדִּיק — праведный народ."],"genesis-20-5":["Разве не он сам сказал мне: „Она моя сестра“? И она сама тоже сказала: „Он мой брат“. В простоте сердца и с чистыми руками я сделал это».","Heeft hij zelf niet tegen mij gezegd: „Zij is mijn zuster“? En zij, ook zij, heeft gezegd: „Hij is mijn broer.“ In de eenvoud van mijn hart en met reine handen heb ik dit gedaan.»",""],"genesis-20-6":["Бог сказал ему во сне: «Я тоже знаю, что ты сделал это в простоте сердца, и Я удержал тебя, чтобы ты не согрешил против Меня. Поэтому Я не дал тебе прикоснуться к ней.","God zei tegen hem in de droom: «Ook Ik weet dat je dit in de eenvoud van je hart hebt gedaan, en Ik heb je ook weerhouden tegen Mij te zondigen. Daarom heb Ik je niet toegestaan haar aan te raken.",""],"genesis-20-7":["Теперь верни жену этого человека, потому что он пророк. Он помолится за тебя, и ты будешь жить. А если ты её не вернёшь, знай: ты непременно умрёшь, ты и всё, что у тебя».","Geef nu de vrouw van die man terug, want hij is een profeet. Hij zal voor je bidden, en je zult leven. Als je haar niet teruggeeft, weet dan dat je zeker zult sterven, jij en alles wat van jou is.»",""],"genesis-20-8":["Авимелех встал рано утром, позвал всех своих слуг и сказал им в уши все эти слова. Люди очень испугались.","Avimelech stond vroeg in de morgen op, riep al zijn dienaren en sprak al deze woorden in hun oren. De mannen werden zeer bang.",""],"genesis-20-9":["Авимелех позвал Авраама и сказал ему: «Что ты нам сделал? Чем я согрешил против тебя, что ты навёл на меня и на моё царство великий грех? Дела, которых не делают, ты сделал со мной».","Avimelech riep Abraham en zei tegen hem: «Wat heb je ons aangedaan? Wat heb ik tegen je misdaan, dat je over mij en over mijn koninkrijk een grote zonde hebt gebracht? Daden die men niet doet, heb je mij aangedaan.»",""],"genesis-20-10":["Авимелех сказал Аврааму: «Что ты увидел, что сделал это?»","Avimelech zei tegen Abraham: «Wat heb je gezien, dat je dit hebt gedaan?»","JPS: what sawest thou; фр.: qu'avais-tu en vue. По-еврейски מָה רָאִיתָ — что ты увидел."],"genesis-20-11":["Авраам сказал: «Я сказал: „Верно, нет страха перед Богом в этом месте, и меня убьют из-за моей жены“.","Abraham zei: «Ik zei: „Vast is er geen vrees voor God op deze plaats, en zij zullen mij doden om mijn vrouw.“",""],"genesis-20-12":["К тому же она и вправду моя сестра, дочь моего отца, только не дочь моей матери, и она стала мне женой.","Bovendien is zij werkelijk mijn zuster, de dochter van mijn vader, maar niet de dochter van mijn moeder, en zij is mijn vrouw geworden.",""],"genesis-20-13":["Когда Бог заставил меня скитаться от дома моего отца, я сказал ей: „Вот добро, которое ты сделаешь мне. Во всяком месте, куда мы придём, скажи обо мне: Он мой брат“».","Toen God mij liet rondzwerven, weg van het huis van mijn vader, zei ik tegen haar: „Dit is de goedheid die je mij zult doen. Op elke plaats waar wij komen, zeg van mij: Hij is mijn broer.“»","JPS: say of me, He is my brother; фр.: dis que je suis ton frère. По-еврейски אִמְרִי־לִי אָחִי הוּא — скажи обо мне: он мой брат."],"genesis-20-14":["Авимелех взял овец и быков, рабов и рабынь, отдал их Аврааму и вернул ему Сару, его жену.","Avimelech nam schapen en runderen, slaven en slavinnen, gaf ze aan Abraham en gaf hem Sara, zijn vrouw, terug.",""],"genesis-20-15":["Авимелех сказал: «Вот моя земля перед тобой. Живи там, где хорошо в твоих глазах».","Avimelech zei: «Hier is mijn land, voor je. Woon waar het goed is in jouw ogen.»",""],"genesis-20-16":["Саре он сказал: «Вот, я дал твоему брату тысячу серебра. Вот, это тебе покрытие глаз для всех, кто с тобой, и перед всеми ты оправдана».","Tegen Sara zei hij: «Ik heb je broer duizend zilver gegeven. Dit is voor jou een bedekking van de ogen voor allen die bij je zijn, en tegenover allen ben je in het gelijk gesteld.»","JPS: covering of the eyes, thou art righted, thy brother; фр.: voile, regarder en face, ton parent. По-еврейски כְּסוּת עֵינַיִם, וְנֹכָחַת, לְאָחִיךְ — покрытие глаз, ты оправдана, твоему брату."],"genesis-20-17":["Авраам помолился Богу, и Бог исцелил Авимелеха, его жену и его рабынь, и они рожали.","Abraham bad tot God, en God genas Avimelech, zijn vrouw en zijn slavinnen, en zij baarden.",""],"genesis-20-18":["Господь крепко закрыл всякое чрево в доме Авимелеха из-за Сары, жены Авраама.","De Eeuwige had iedere schoot in het huis van Avimelech volkomen gesloten, om Sara, de vrouw van Abraham.","JPS: the LORD; фр.: Dieu. По-еврейски יְהֹוָה — Господь."],"genesis-21-1":["Господь навестил Сару, как Он сказал, и Господь сделал Саре так, как Он говорил.","De Eeuwige bezocht Sara, zoals Hij had gezegd, en de Eeuwige deed voor Sara zoals Hij had gesproken.",""],"genesis-21-2":["Сара зачала и родила Аврааму сына в его старости, в назначенный срок, о котором говорил ему Бог.","Sara werd zwanger en baarde Abraham een zoon in zijn ouderdom, op de vastgestelde tijd waarover God tot hem gesproken had.",""],"genesis-21-3":["Авраам назвал имя своего сына, который родился у него, которого родила ему Сара, — Ицхак.","Abraham noemde de naam van zijn zoon die hem geboren was, die Sara hem gebaard had: Jitschak.",""],"genesis-21-4":["Авраам обрезал своего сына Ицхака, восьми дней от роду, как повелел ему Бог.","Abraham besneed zijn zoon Jitschak toen die acht dagen oud was, zoals God hem geboden had.",""],"genesis-21-5":["Аврааму было сто лет, когда у него родился его сын Ицхак.","Abraham was honderd jaar oud toen zijn zoon Jitschak hem geboren werd.",""],"genesis-21-6":["Сара сказала: «Бог сделал мне смех. Каждый, кто услышит, будет смеяться из-за меня».","Sara zei: «God heeft gelach voor mij gemaakt. Iedereen die het hoort, zal vanwege mij lachen.»","JPS: laughter, will laugh; фр.: félicité, félicitera. По-еврейски צְחֹק и יִצְחַק — смех, игра с именем Ицхак."],"genesis-21-7":["Она сказала: «Кто сказал бы Аврааму, что Сара кормит детей грудью? А я родила ему сына в его старости».","Zij zei: «Wie zou tegen Abraham gezegd hebben dat Sara kinderen zoogt? Ik heb hem een zoon gebaard in zijn ouderdom.»",""],"genesis-21-8":["Ребёнок вырос и был отнят от груди. Авраам устроил большой пир в день, когда Ицхака отняли от груди.","Het kind groeide op en werd gespeend. Abraham maakte een groot feest op de dag dat Jitschak gespeend werd.",""],"genesis-21-9":["Сара увидела сына Агари, египтянки, которого та родила Аврааму: он смеялся.","Sara zag de zoon van Hagar, de Egyptische, die zij Abraham gebaard had: hij lachte.","JPS: making sport; фр.: railleries. По-еврейски מְצַחֵק — смеялся, тот же корень, что имя Ицхак."],"genesis-21-10":["Она сказала Аврааму: «Прогони эту рабыню и её сына, потому что сын этой рабыни не будет наследником вместе с моим сыном, с Ицхаком».","Zij zei tegen Abraham: «Jaag deze slavin en haar zoon weg, want de zoon van deze slavin zal niet erven samen met mijn zoon, met Jitschak.»",""],"genesis-21-11":["Это было очень плохо в глазах Авраама из-за его сына.","De zaak was zeer kwalijk in de ogen van Abraham, vanwege zijn zoon.",""],"genesis-21-12":["Бог сказал Аврааму: «Пусть это не будет плохо в твоих глазах из-за мальчика и из-за твоей рабыни. Всё, что скажет тебе Сара, слушай её голос, потому что в Ицхаке тебе будет названо потомство.","God zei tegen Abraham: «Laat het niet kwalijk zijn in jouw ogen vanwege de jongen en vanwege je slavin. Luister naar haar stem in alles wat Sara tegen je zegt, want in Jitschak zal voor jou nageslacht genoemd worden.","JPS: in Isaac shall seed be called to thee; фр.: la postérité d'Isaac portera ton nom. По-еврейски בְיִצְחָק יִקָּרֵא לְךָ זָרַע — в Ицхаке тебе будет названо потомство."],"genesis-21-13":["Сына рабыни Я тоже сделаю народом, потому что он твоё потомство».","Ook de zoon van de slavin zal Ik tot een volk maken, want hij is jouw nageslacht.»",""],"genesis-21-14":["Авраам встал рано утром, взял хлеб и мех с водой, дал Агари, положив ей на плечо, и ребёнка, и отослал её. Она ушла и заблудилась в пустыне Беэр-Шевы.","Abraham stond vroeg in de morgen op, nam brood en een zak water, gaf het aan Hagar, legde het op haar schouder, en het kind, en stuurde haar weg. Zij ging en dwaalde in de woestijn van Beër-Sjeva.","JPS отделяет ребёнка от «положил на плечо»; фр. кладёт на плечо и ребёнка. По-еврейски וְאֶת־הַיֶּלֶד — отдельное дополнение к «дал»."],"genesis-21-15":["Вода в мехе кончилась, и она бросила ребёнка под один из кустов.","Het water uit de zak was op, en zij wierp het kind onder een van de struiken.","JPS: cast under shrubs; фр.: abandonna au pied d'un arbre. По-еврейски וַתַּשְׁלֵךְ תַּחַת אַחַד הַשִּׂיחִם — бросила под один из кустов."],"genesis-21-16":["Она пошла и села напротив, поодаль, на расстоянии выстрела из лука, потому что сказала: «Не видеть бы мне смерти ребёнка». Она села напротив, подняла голос и заплакала.","Zij ging weg en ging tegenover hem zitten, op een afstand van een boogschot, want zij zei: «Laat ik de dood van het kind niet zien.» Zij zat tegenover hem, verhief haar stem en weende.",""],"genesis-21-17":["Бог услышал голос мальчика. Посланник Бога воззвал к Агари с неба и сказал ей: «Что с тобой, Агар? Не бойся, потому что Бог услышал голос мальчика там, где он.","God hoorde de stem van de jongen. Een bode van God riep tot Hagar vanuit de hemel en zei tegen haar: «Wat is er met je, Hagar? Wees niet bang, want God heeft de stem van de jongen gehoord, daar waar hij is.","JPS: angel of God, the voice; фр.: messager du Seigneur, le gémissement. По-еврейски מַלְאַךְ אֱלֹהִים и קוֹל — посланник Бога и голос."],"genesis-21-18":["Встань, подними мальчика и крепко держи его своей рукой, потому что Я сделаю его великим народом».","Sta op, til de jongen op en houd hem vast met je hand, want Ik zal hem tot een groot volk maken.»",""],"genesis-21-19":["Бог открыл ей глаза, и она увидела колодец с водой. Она пошла, наполнила мех водой и напоила мальчика.","God opende haar ogen, en zij zag een put met water. Zij ging, vulde de zak met water en gaf de jongen te drinken.","JPS: God, a well; фр.: le Seigneur, une source. По-еврейски אֱלֹהִים и בְּאֵר — Бог и колодец."],"genesis-21-20":["Бог был с мальчиком, и он вырос. Он жил в пустыне и стал стрелком из лука.","God was met de jongen, en hij groeide op. Hij woonde in de woestijn en werd een boogschutter.",""],"genesis-21-21":["Он жил в пустыне Паран, и его мать взяла ему жену из земли Египта.","Hij woonde in de woestijn Paran, en zijn moeder nam voor hem een vrouw uit het land Egypte.",""],"i-samuel-1-1":["Был один человек из Раматаим-Цофим, с горы Эфраима. Имя его — Элькана, сын Йерохама, сын Элигу, сын Тоху, сын Цуфа, эфратянин.","Er was een man uit Ramatajim-Tsofim, van de berg Efrajim. Zijn naam was Elkana, zoon van Jerocham, zoon van Elihoe, zoon van Tochoe, zoon van Tsoef, een Efratiet.","JPS: an Ephraimite; фр.: un Ephratéen. По-еврейски אֶפְרָתִי — эфратянин."],"i-samuel-1-2":["У него были две жены. Одну звали Ханна, другую — Пнина. У Пнины были дети, у Ханны детей не было.","Hij had twee vrouwen. De ene heette Channa, de andere Penina. Penina had kinderen, Channa had geen kinderen.",""],"i-samuel-1-3":["Этот человек из года в год поднимался из своего города, чтобы поклониться и принести жертву Господу воинств в Шило. Там два сына Эли, Хофни и Пинхас, были священниками Господа.","Deze man ging jaar na jaar uit zijn stad op, om zich neer te buigen en te offeren aan de Eeuwige der legerscharen in Sjilo. Daar waren de twee zonen van Eli, Chofni en Pinchas, priesters van de Eeuwige.",""],"i-samuel-1-4":["Когда пришёл день, Элькана принёс жертву и дал доли Пнине, своей жене, и всем её сыновьям и дочерям.","Toen de dag kwam, bracht Elkana een offer en gaf hij porties aan Penina, zijn vrouw, en aan al haar zonen en dochters.",""],"i-samuel-1-5":["А Ханне он давал одну двойную долю, потому что любил Ханну. Господь же закрыл её чрево.","Aan Channa gaf hij één dubbele portie, want hij hield van Channa. Maar de Eeuwige had haar schoot gesloten.","JPS: a double portion; фр.: une seule portion, à son grand déplaisir. По-еврейски מָנָה אַחַת אַפָּיִם — тёмное место: одна доля, אַפָּיִם как «двойная»."],"i-samuel-1-6":["Её соперница сильно злила её, чтобы та роптала, потому что Господь закрыл её чрево.","Haar rivale tergde haar hevig, om haar te laten morren, want de Eeuwige had haar schoot gesloten.","JPS: the LORD; фр.: Dieu. По-еврейски יְהֹוָה — Господь."],"i-samuel-1-7":["Так бывало из года в год: каждый раз, когда она поднималась в дом Господа, та её злила, и она плакала и не ела.","Zo gebeurde het jaar op jaar: telkens als zij opging naar het huis van de Eeuwige, tergde de ander haar, en zij weende en at niet.",""],"i-samuel-1-8":["Элькана, её муж, сказал ей: «Ханна, почему ты плачешь? Почему ты не ешь? Почему твоё сердце печалится? Разве я не лучше тебе, чем десять сыновей?»","Elkana, haar man, zei tegen haar: «Channa, waarom huil je? Waarom eet je niet? Waarom is je hart bedroefd? Ben ik voor jou niet beter dan tien zonen?»",""],"i-samuel-1-9":["Ханна встала после еды в Шило и после питья. Эли, священник, сидел на сиденье у косяка храма Господа.","Channa stond op na het eten in Sjilo en na het drinken. Eli, de priester, zat op de zetel bij de deurpost van de tempel van de Eeuwige.","JPS: the priest; фр.: le pontife. По-еврейски הַכֹּהֵן — священник."],"i-samuel-1-10":["Она была горька душой, молилась Господу и сильно плакала.","Zij was bitter van ziel, bad tot de Eeuwige en weende hevig.",""],"i-samuel-1-11":["Она дала обет и сказала: «Господь воинств, если Ты действительно взглянешь на страдание Твоей рабы, вспомнишь меня и не забудешь Твою рабу, и дашь Твоей рабе мужское потомство, я отдам его Господу на все дни его жизни, и бритва не взойдёт ему на голову».","Zij deed een gelofte en zei: «Eeuwige der legerscharen, als U werkelijk de ellende van Uw slavin aanziet, aan mij denkt en Uw slavin niet vergeet, en aan Uw slavin mannelijk nageslacht geeft, dan geef ik hem aan de Eeuwige voor alle dagen van zijn leven, en geen scheermes zal op zijn hoofd komen.»",""],"i-samuel-1-12":["Она долго молилась перед Господом, а Эли смотрел на её рот.","Terwijl zij lang bad voor de Eeuwige, lette Eli op haar mond.",""],"i-samuel-1-13":["Ханна говорила в своём сердце: только губы её двигались, а голоса не было слышно. Эли счёл её пьяной.","Channa sprak in haar hart: alleen haar lippen bewogen, haar stem was niet te horen. Eli hield haar voor dronken.",""],"i-samuel-1-14":["Эли сказал ей: «До каких пор ты будешь пьяной? Убери от себя своё вино».","Eli zei tegen haar: «Hoe lang blijf je dronken? Doe je wijn van je weg.»","JPS: put away thy wine from thee; фр.: va cuver ton vin. По-еврейски הָסִירִי אֶת־יֵינֵךְ מֵעָלָיִךְ — убери от себя своё вино."],"i-samuel-1-15":["Ханна ответила: «Нет, господин мой, я женщина с тяжёлым духом. Вина и крепкого напитка я не пила. Я излила свою душу перед Господом.","Channa antwoordde: «Nee, mijn heer, ik ben een vrouw met een zwaar gemoed. Wijn en sterke drank heb ik niet gedronken. Ik heb mijn ziel uitgestort voor de Eeuwige.",""],"i-samuel-1-16":["Не сочти свою рабу дочерью ничтожества. От великой жалобы и досады я говорила до сих пор».","Reken je slavin niet als een dochter van niets. Door mijn vele klacht en mijn ergernis heb ik tot nu toe gesproken.»",""],"i-samuel-1-17":["Эли ответил: «Иди с миром, и Бог Исраэля даст тебе то, чего ты просила у Него».","Eli antwoordde: «Ga in vrede, en de God van Israël geve wat je Hem gevraagd hebt.»",""],"i-samuel-1-18":["Она сказала: «Пусть твоя служанка найдёт милость в твоих глазах». Женщина пошла своей дорогой, поела, и прежнего лица у неё уже не было.","Zij zei: «Laat je dienares gunst vinden in jouw ogen.» De vrouw ging haar weg, at, en haar gezicht was niet meer zoals het geweest was.","JPS добавляет sad; фр.: physionomie ne fut plus la même. По-еврейски וּפָנֶיהָ לֹא־הָיוּ־לָהּ עוֹד — прежнего лица у неё уже не было."],"i-samuel-1-19":["Они встали рано утром, поклонились Господу, вернулись и пришли в свой дом, в Раму. Элькана был с Ханной, своей женой, и Господь вспомнил её.","Zij stonden vroeg in de morgen op, bogen zich neer voor de Eeuwige, keerden terug en kwamen naar hun huis, naar Rama. Elkana sliep met Channa, zijn vrouw, en de Eeuwige herinnerde zich haar.",""],"i-samuel-1-20":["Когда дни совершили круг, Ханна зачала и родила сына, и назвала его Шмуэль: «потому что от Господа я просила его».","Toen de kring van de dagen rond was, werd Channa zwanger en baarde zij een zoon. Zij noemde hem Sjemoeël: «want van de Eeuwige heb ik hem gevraagd.»",""],"genesis-24-15":["Он ещё не кончил говорить, и вот выходит Ривка, которая родилась у Бетуэля, сына Мильки, жены Нахора, брата Авраама, и кувшин её на плече.","Hij was nog niet uitgesproken, en zie, Rivka kwam naar buiten, geboren bij Betoel, de zoon van Milka, de vrouw van Nachor, de broer van Abraham, met haar kruik op haar schouder.",""],"genesis-24-16":["Девушка была очень красива на вид, девственница, и ни один мужчина не был с ней. Она спустилась к источнику, наполнила свой кувшин и поднялась.","Het meisje was heel mooi om te zien, een maagd, en geen man had met haar geslapen. Zij daalde af naar de bron, vulde haar kruik en kwam weer boven.","JPS: neither had any man known her; фр.: nul homme n'avait approché d'elle. По-еврейски לֹא יְדָעָהּ — ни один мужчина не был с ней."],"genesis-24-17":["Слуга побежал ей навстречу и сказал: «Дай мне, прошу, глотнуть немного воды из твоего кувшина».","De dienaar snelde haar tegemoet en zei: «Laat mij, alsjeblieft, een beetje water drinken uit jouw kruik.»",""],"genesis-24-18":["Она сказала: «Пей, господин мой». Она поспешила, спустила кувшин на руку и напоила его.","Zij zei: «Drink, mijn heer.» Zij haastte zich, liet haar kruik op haar hand zakken en gaf hem te drinken.",""],"genesis-24-19":["Когда она напоила его, она сказала: «Я начерпаю и твоим верблюдам, пока они не кончат пить».","Toen zij hem te drinken had gegeven, zei zij: «Ook voor jouw kamelen zal ik putten, totdat zij klaar zijn met drinken.»",""],"genesis-24-20":["Она поспешила, вылила кувшин в поилку, снова побежала к колодцу черпать и начерпала всем его верблюдам.","Zij haastte zich, leegde haar kruik in de drinkbak, rende weer naar de put om te putten en putte voor al zijn kamelen.","JPS: the well; фр.: la fontaine. По-еврейски הַבְּאֵר — колодец."],"genesis-24-21":["Человек смотрел на неё в изумлении и молчал, чтобы узнать, дал ли Господь успех его пути или нет.","De man keek haar verwonderd aan en zweeg, om te weten of de Eeuwige zijn weg had doen slagen of niet.",""],"genesis-24-22":["Когда верблюды напились, человек взял золотое кольцо весом в бека и два браслета для её рук, весом в десять золота.","Toen de kamelen gedronken hadden, nam de man een gouden ring, een beka zwaar, en twee armbanden voor haar armen, tien goud in gewicht.","JPS: half a shekel; фр.: un béka. По-еврейски בֶּקַע — бека."],"genesis-24-23":["Он сказал: «Чья ты дочь? Скажи мне, прошу. Есть ли в доме твоего отца место нам переночевать?»","Hij zei: «Van wie ben jij de dochter? Zeg het mij, alsjeblieft. Is er in het huis van je vader plaats voor ons om te overnachten?»",""],"genesis-24-24":["Она сказала ему: «Я дочь Бетуэля, сына Мильки, которого она родила Нахору».","Zij zei tegen hem: «Ik ben de dochter van Betoel, de zoon van Milka, die zij aan Nachor gebaard heeft.»",""],"genesis-24-25":["Она сказала ему: «Есть у нас и солома, и корма вдоволь, и место переночевать».","Zij zei tegen hem: «Wij hebben zowel stro als voer in overvloed, en ook plaats om te overnachten.»",""],"genesis-24-26":["Человек склонился и пал ниц перед Господом.","De man boog zich en wierp zich neer voor de Eeuwige.",""],"genesis-24-27":["Он сказал: «Благословен Господь, Бог моего господина Авраама, который не отнял у моего господина Своё добро и Свою верность. Меня Господь по пути привёл к дому братьев моего господина».","Hij zei: «Gezegend is de Eeuwige, de God van mijn heer Abraham, die Zijn goedheid en Zijn trouw niet aan mijn heer heeft onttrokken. Mij heeft de Eeuwige op de weg geleid naar het huis van de broers van mijn heer.»","Фр. обрывает стих на mon maître и пишет Il с заглавной. Дальше в еврейском говорит человек: меня Господь привёл к дому братьев моего господина."],"genesis-24-28":["Девушка побежала и рассказала в доме своей матери эти слова.","Het meisje rende weg en vertelde in het huis van haar moeder deze woorden.","JPS: her mother's house; фр.: la chambre de sa mère. По-еврейски לְבֵית אִמָּהּ — в дом своей матери."],"genesis-24-29":["У Ривки был брат, его звали Лаван. Лаван побежал к человеку наружу, к источнику.","Rivka had een broer, zijn naam was Lavan. Lavan rende naar de man toe, naar buiten, naar de bron.",""],"genesis-24-30":["Когда он увидел кольцо и браслеты на руках своей сестры и услышал слова своей сестры Ривки: «Так сказал мне этот человек», он подошёл к человеку. И вот, тот стоял у верблюдов при источнике.","Toen hij de ring zag en de armbanden aan de armen van zijn zuster, en de woorden hoorde van zijn zuster Rivka: «Zo heeft die man tegen mij gesproken», ging hij naar de man. En zie, die stond bij de kamelen bij de bron.",""],"genesis-24-31":["Он сказал: «Войди, благословенный Господом. Зачем ты стоишь снаружи? Я освободил дом и место для верблюдов».","Hij zei: «Kom binnen, gezegende van de Eeuwige. Waarom blijf je buiten staan? Ik heb het huis vrijgemaakt, en er is plaats voor de kamelen.»","JPS: blessed of the LORD; фр.: bien-aimé du Seigneur. По-еврейски בְּרוּךְ יְהֹוָה — благословенный Господом."],"genesis-24-32":["Человек вошёл в дом и развьючил верблюдов. Он дал солому и корм верблюдам и воду, чтобы омыть свои ноги и ноги людей, которые были с ним.","De man kwam het huis binnen en laadde de kamelen af. Hij gaf stro en voer voor de kamelen, en water om zijn voeten te wassen en de voeten van de mannen die bij hem waren.","JPS: he gave; фр.: on apporta. Подлежащее וַיִּתֵּן не названо отдельно."],"genesis-24-33":["Перед ним поставили есть. Он сказал: «Не буду есть, пока не скажу свои слова». Тот сказал: «Говори».","Er werd eten voor hem neergezet. Hij zei: «Ik eet niet, totdat ik mijn woorden heb gesproken.» De ander zei: «Spreek.»",""],"genesis-24-34":["Он сказал: «Я слуга Авраама.","Hij zei: «Ik ben de dienaar van Abraham.",""],"genesis-24-35":["Господь очень благословил моего господина, и тот стал велик. Он дал ему овец и быков, серебро и золото, рабов и рабынь, верблюдов и ослов.","De Eeuwige heeft mijn heer zeer gezegend, en hij is groot geworden. Hij heeft hem schapen en runderen gegeven, zilver en goud, slaven en slavinnen, kamelen en ezels.",""],"genesis-24-36":["Сара, жена моего господина, родила моему господину сына после своей старости, и он отдал ему всё, что у него есть.","Sara, de vrouw van mijn heer, heeft mijn heer een zoon gebaard na haar ouderdom, en hij heeft hem alles gegeven wat hij heeft.",""],"genesis-24-37":["Мой господин взял с меня клятву, сказав: „Не бери жену моему сыну из дочерей кнаани, в чьей земле я живу.","Mijn heer heeft mij een eed laten zweren: „Neem voor mijn zoon geen vrouw uit de dochters van de Kenaäniet, in wiens land ik woon.",""],"genesis-24-38":["Нет: к дому моего отца ты пойдёшь и к моему роду, и возьмёшь жену моему сыну“.","Nee: naar het huis van mijn vader zul je gaan en naar mijn familie, en daar zul je een vrouw voor mijn zoon nemen.“",""],"genesis-24-39":["Я сказал своему господину: „Может быть, женщина не пойдёт за мной“.","Ik zei tegen mijn heer: „Misschien gaat de vrouw niet met mij mee.“",""],"genesis-24-40":["Он сказал мне: „Господь, перед которым я хожу, пошлёт с тобой Своего посланника, даст успех твоему пути, и ты возьмёшь жену моему сыну из моего рода и из дома моего отца.","Hij zei tegen mij: „De Eeuwige, voor wie ik gewandeld heb, zal Zijn bode met je meesturen, je weg doen slagen, en je zult een vrouw voor mijn zoon nemen uit mijn familie en uit het huis van mijn vader.","JPS: His angel; фр.: son envoyé. По-еврейски מַלְאָכוֹ — Его посланник."],"genesis-24-41":["Тогда ты будешь свободен от моей клятвы, когда придёшь к моему роду. Если же тебе её не отдадут, ты будешь чист от моей клятвы“.","Dan zul je vrij zijn van mijn eed, wanneer je bij mijn familie komt. En als zij haar niet aan je geven, zul je vrij zijn van mijn eed.“",""],"genesis-24-42":["Сегодня я пришёл к источнику и сказал: „Господь, Бог моего господина Авраама, если Ты дашь, прошу, успех моему пути, которым я иду:","Vandaag kwam ik bij de bron en zei: „Eeuwige, God van mijn heer Abraham, als U alstublieft mijn weg doet slagen, de weg die ik ga:",""],"genesis-24-43":["вот, я стою у источника воды, и пусть будет: молодая женщина выйдет черпать, и я скажу ей: дай мне, прошу, немного воды из твоего кувшина,","zie, ik sta bij de waterbron. Laat het gebeuren dat de jonge vrouw die komt putten, en tegen wie ik zeg: geef mij, alsjeblieft, een beetje water uit jouw kruik,",""],"genesis-24-44":["и она скажет мне: пей и ты, и твоим верблюдам я тоже начерпаю, — пусть она будет той женщиной, которую Господь определил сыну моего господина“.","en zij tegen mij zegt: drink ook jij, en ook voor jouw kamelen zal ik putten, — laat haar de vrouw zijn die de Eeuwige heeft aangewezen voor de zoon van mijn heer.“","JPS: appointed; фр.: agrée. По-еврейски הֹכִיחַ — определил."],"genesis-24-45":["Я ещё не кончил говорить в своём сердце, и вот выходит Ривка, и кувшин её на плече. Она спустилась к источнику и начерпала. Я сказал ей: „Напой меня, прошу“.","Ik was nog niet uitgesproken in mijn hart, en zie, Rivka kwam naar buiten, haar kruik op haar schouder. Zij daalde af naar de bron en putte. Ik zei tegen haar: „Laat mij drinken, alsjeblieft.“",""],"genesis-24-46":["Она поспешила, спустила с себя кувшин и сказала: „Пей, и твоих верблюдов я тоже напою“. Я пил, и верблюдов она тоже напоила.","Zij haastte zich, liet haar kruik van zich af zakken en zei: „Drink, en ook je kamelen zal ik te drinken geven.“ Ik dronk, en ook de kamelen gaf zij te drinken.","Во французском нет конца стиха: וָאֵשְׁתְּ וְגַם הַגְּמַלִּים הִשְׁקָתָה — я пил, и верблюдов она напоила."],"genesis-24-47":["Я спросил её и сказал: „Чья ты дочь?“ Она сказала: „Дочь Бетуэля, сына Нахора, которого родила ему Милька“. Я надел кольцо ей на нос и браслеты ей на руки.","Ik vroeg haar en zei: „Van wie ben jij de dochter?“ Zij zei: „De dochter van Betoel, de zoon van Nachor, die Milka hem gebaard heeft.“ Ik deed de ring aan haar neus en de armbanden aan haar armen.",""],"genesis-24-48":["Я склонился и пал ниц перед Господом и благословил Господа, Бога моего господина Авраама, который вёл меня путём истины, чтобы взять дочь брата моего господина его сыну.","Ik boog mij en wierp mij neer voor de Eeuwige, en ik zegende de Eeuwige, de God van mijn heer Abraham, die mij op de weg van waarheid heeft geleid om de dochter van de broer van mijn heer te nemen voor zijn zoon.","JPS: my master's brother's daughter; фр.: la parente de mon maître. По-еврейски בַּת־אֲחִי אֲדֹנִי — дочь брата моего господина."],"genesis-24-49":["Теперь, если вы делаете добро и верность моему господину, скажите мне. Если нет, скажите мне, и я поверну направо или налево».","Nu dan, als jullie goedheid en trouw bewijzen aan mijn heer, zeg het mij. Zo niet, zeg het mij, zodat ik naar rechts of naar links kan gaan.»",""],"genesis-24-50":["Лаван и Бетуэль ответили: «От Господа вышло это дело. Мы не можем сказать тебе ни дурного, ни доброго.","Lavan en Betoel antwoordden: «Van de Eeuwige is deze zaak uitgegaan. Wij kunnen je niets kwaads of goeds zeggen.","JPS: from the LORD; фр.: de Dieu. По-еврейски מֵיְהֹוָה — от Господа."],"genesis-24-51":["Вот Ривка перед тобой. Возьми и иди, и пусть она будет женой сыну твоего господина, как сказал Господь».","Hier is Rivka voor je. Neem haar en ga, en laat haar een vrouw zijn voor de zoon van jouw heer, zoals de Eeuwige gesproken heeft.»",""],"genesis-24-52":["Когда слуга Авраама услышал их слова, он пал ниц на землю перед Господом.","Toen de dienaar van Abraham hun woorden hoorde, wierp hij zich ter aarde voor de Eeuwige.",""],"proverbs-31-10":["Доблестную жену кто найдёт? Её цена далеко выше жемчуга.","Een vrouw van kracht, wie zal haar vinden? Haar waarde ligt ver boven parels.","JPS: rubies; фр.: perles. По-еврейски פְּנִינִים — жемчуг."],"proverbs-31-11":["Сердце её мужа доверяет ей, и в добыче у него нет недостатка.","Het hart van haar man vertrouwt op haar, en aan buit ontbreekt het hem niet.","JPS: gain; фр.: ressources. По-еврейски שָׁלָל — добыча."],"proverbs-31-12":["Она воздаёт ему добром, а не злом, все дни своей жизни.","Zij doet hem goed en geen kwaad, alle dagen van haar leven.","JPS: good and not evil; фр.: bonheur, ne lui cause pas de peine. По-еврейски טוֹב וְלֹא־רָע — добро, а не зло."],"proverbs-31-13":["Она ищет шерсть и лён и работает с охотой своих рук.","Zij zoekt wol en vlas en werkt met de lust van haar handen.",""],"proverbs-31-14":["Она — как купеческие корабли, издалека привозит свой хлеб.","Zij is als koopvaardijschepen, van verre brengt zij haar brood.",""],"proverbs-31-15":["Она встаёт ещё ночью, даёт добычу своему дому и долю своим служанкам.","Zij staat op terwijl het nog nacht is, geeft prooi aan haar huis en een vast deel aan haar dienaressen.","JPS: food; фр.: vivres. По-еврейски טֶרֶף — добыча."],"proverbs-31-16":["Она задумала поле и взяла его. Плодом своих рук она посадила виноградник.","Zij neemt een akker in overweging en verwerft hem. Van de vrucht van haar handen plant zij een wijngaard.",""],"proverbs-31-17":["Она опоясывает силой свои бёдра и укрепляет свои руки.","Zij gordt haar lendenen met kracht en maakt haar armen sterk.",""],"proverbs-31-18":["Она вкусила, что хорош её товар. В ночи её светильник не гаснет.","Zij proeft dat haar koopwaar goed is. Haar lamp gaat in de nacht niet uit.","JPS: perceiveth; фр.: s'assure. По-еврейски טָעֲמָה — вкусила."],"proverbs-31-19":["Она протягивает руки к гребню, и ладони её держат веретено.","Zij strekt haar handen uit naar de spinrok, en haar handpalmen houden de spil.","JPS: distaff; фр.: rouet. По-еврейски כִּישׁוֹר — гребень пряхи, не колесо."],"proverbs-31-20":["Ладонь свою она открывает бедному, и руки свои протягивает нищему.","Haar handpalm opent zij voor de arme, en haar handen strekt zij uit naar de behoeftige.",""],"proverbs-31-21":["Она не боится снега для своего дома, потому что весь её дом одет в багрянец.","Zij vreest de sneeuw niet voor haar huis, want heel haar huis is in scharlaken gekleed.","JPS: scarlet; фр.: riches étoffes. По-еврейски שָׁנִים — багрянец, либо «вдвойне»."],"proverbs-31-22":["Покрывала она сделала себе. Тонкий лён и пурпур — её одежда.","Spreien maakt zij voor zichzelf. Fijn linnen en purper zijn haar kleding.","JPS: coverlets; фр.: tapis, и добавляет se brode. По-еврейски מַרְבַדִּים — покрывала, без «вышивает»."],"proverbs-31-23":["Её муж известен в воротах, когда сидит со старейшинами земли.","Haar man is bekend in de poorten, als hij zit met de oudsten van het land.",""],"proverbs-31-24":["Льняное полотно она сделала и продала, и пояс отдала купцу.","Linnen maakte zij en verkocht het, en een gordel gaf zij aan de koopman.",""],"proverbs-31-25":["Сила и достоинство — её одежда, и она смеётся над грядущим днём.","Kracht en waardigheid zijn haar kleding, en zij lacht om de komende dag.",""],"proverbs-31-26":["Свой рот она открывает с мудростью, и Тора доброты на её языке.","Haar mond opent zij met wijsheid, en de Tora van goedheid is op haar tong.","JPS: the law of kindness; фр.: des leçons de bonté. По-еврейски תּוֹרַת־חֶסֶד — Тора доброты."],"proverbs-31-27":["Она смотрит за путями своего дома и не ест хлеб праздности.","Zij houdt de wegen van haar huis in het oog en eet niet het brood van ledigheid.",""],"proverbs-31-28":["Встают её сыновья и называют её счастливой. Её муж — и он хвалит её:","Haar zonen staan op en noemen haar gelukkig. Haar man, en hij prijst haar:",""],"proverbs-31-29":["«Многие дочери явили доблесть, а ты поднялась выше всех их».","«Veel dochters hebben kracht getoond, maar jij stijgt uit boven hen allen.»",""],"proverbs-31-30":["Прелесть — ложь, и красота — пар. Женщина, боящаяся Господа, она будет восхвалена.","Bevalligheid is leugen, en schoonheid is een zucht. Een vrouw die de Eeuwige vreest, zij zal geprezen worden.",""],"proverbs-31-31":["Дайте ей от плода её рук, и пусть дела её хвалят её в воротах.","Jullie, geef haar van de vrucht van haar handen, en laten haar werken haar prijzen in de poorten.",""],"genesis-26-13":["Этот человек богател и всё богател, пока не стал очень богат.","De man werd rijk en bleef rijker worden, tot hij zeer rijk was.",""],"genesis-26-14":["У него были стада овец и коз, стада крупного скота и много работников, и Плиштим завидовали ему.","Hij had kudden schapen en geiten, kudden runderen en veel knechten, en de Pelisjtim waren jaloers op hem.","JPS: a great household; фр.: cultures considérables. По-еврейски עֲבֻדָּה — работа, здесь работники."],"genesis-26-15":["Все колодцы, которые выкопали слуги его отца в дни Авраама, его отца, Плиштим засыпали и наполнили землёй.","Alle putten die de knechten van zijn vader hadden gegraven in de dagen van zijn vader Abraham, stopten de Pelisjtim dicht en vulden ze met aarde.",""],"genesis-26-16":["Авимелех сказал Ицхаку: «Уйди от нас, потому что ты стал гораздо могущественнее нас».","Avimelech zei tegen Jitschak: «Ga bij ons weg, want je bent veel machtiger geworden dan wij.»",""],"genesis-26-17":["Ицхак ушёл оттуда, остановился в долине Грара и поселился там.","Jitschak trok daarvandaan, sloeg zijn kamp op in het dal van Gerar en woonde daar.",""],"genesis-26-18":["Ицхак снова выкопал колодцы с водой, которые выкопали во дни Авраама, его отца. Плиштим засыпали их после смерти Авраама. Он дал им те имена, которыми назвал их его отец.","Jitschak groef opnieuw de waterputten die men in de dagen van zijn vader Abraham had gegraven. De Pelisjtim hadden ze na de dood van Abraham dichtgestopt. Hij gaf ze de namen die zijn vader ze had gegeven.",""],"genesis-26-19":["Слуги Ицхака копали в долине и нашли там колодец живой воды.","De knechten van Jitschak groeven in het dal en vonden daar een put met levend water.","JPS: a well of living water; фр.: une source d’eau vive. По-еврейски בְּאֵר מַיִם חַיִּים — колодец живой воды."],"genesis-26-20":["Пастухи Грара стали спорить с пастухами Ицхака и говорили: «Вода наша». Он назвал колодец Эсек, потому что они спорили с ним.","De herders van Gerar twistten met de herders van Jitschak en zeiden: «Het water is van ons.» Hij noemde de put Esek, omdat zij met hem twistten.",""],"genesis-26-21":["Они выкопали другой колодец, и из-за него тоже спорили. Он назвал его Ситна.","Zij groeven een andere put, en ook daarover twistten zij. Hij noemde die Sitna.",""],"genesis-26-22":["Он перешёл оттуда и выкопал другой колодец, и из-за него не спорили. Он назвал его Реховот и сказал: «Теперь Господь дал нам простор, и мы будем плодиться на этой земле».","Hij trok daarvandaan en groef een andere put, en daarover twistten zij niet. Hij noemde die Rechovot en zei: «Nu heeft de Eeuwige ons ruimte gegeven, en wij zullen vruchtbaar zijn in het land.»",""],"genesis-26-23":["Оттуда он поднялся в Беэр-Шеву.","Vandaar trok hij op naar Beër-Sjeva.",""],"genesis-26-24":["В ту ночь ему явился Господь и сказал: «Я — Бог Авраама, твоего отца. Не бойся, потому что Я с тобой. Я благословлю тебя и умножу твоё потомство ради Авраама, Моего слуги».","Die nacht verscheen de Eeuwige aan hem en zei: «Ik ben de God van Abraham, je vader. Wees niet bang, want Ik ben met je. Ik zal je zegenen en je nageslacht talrijk maken omwille van Abraham, Mijn dienaar.»",""],"genesis-26-25":["Он построил там жертвенник, воззвал к имени Господа, поставил там свой шатёр, и там слуги Ицхака выкопали колодец.","Hij bouwde daar een altaar, riep de naam van de Eeuwige aan, zette daar zijn tent op, en daar groeven de knechten van Jitschak een put.",""],"genesis-26-26":["Авимелех пришёл к нему из Грара, и Ахузат, его друг, и Пихоль, начальник его войска.","Avimelech kwam vanuit Gerar naar hem toe, met Achoezat, zijn vriend, en Pichol, de bevelhebber van zijn leger.",""],"genesis-26-27":["Ицхак сказал им: «Зачем вы пришли ко мне? Вы ненавидите меня и отослали меня от себя».","Jitschak zei tegen hen: «Waarom zijn jullie naar mij gekomen? Jullie haten mij en hebben mij van jullie weggestuurd.»",""],"genesis-26-28":["Они сказали: «Мы ясно увидели, что Господь с тобой, и мы сказали: пусть будет клятва между нами, между нами и тобой, и заключим с тобой брит,","Zij zeiden: «Wij hebben duidelijk gezien dat de Eeuwige met je is, en wij zeiden: laat er een eed zijn tussen ons, tussen ons en jou, en laten wij een briet met je sluiten,","JPS: an oath; фр.: un engagement réciproque. По-еврейски אָלָה — клятва."],"genesis-26-29":["что ты не сделаешь нам зла, как мы тебя не тронули и как мы делали тебе только добро и отпустили тебя с миром. Теперь ты благословен Господом».","dat je ons geen kwaad zult doen, zoals wij jou niet hebben aangeraakt en zoals wij jou alleen goed hebben gedaan en jou in vrede hebben weggestuurd. Jij bent nu door de Eeuwige gezegend.»","JPS: thou art now the blessed; фр.: sois béni. По-еврейски אַתָּה עַתָּה בְּרוּךְ יְהֹוָה — ты теперь благословен Господом."],"genesis-26-30":["Он устроил им пир, и они ели и пили.","Hij richtte een maaltijd voor hen aan, en zij aten en dronken.",""],"genesis-26-31":["Утром они встали рано и поклялись друг другу. Ицхак отпустил их, и они ушли от него с миром.","Vroeg in de morgen stonden zij op en zwoeren elkaar een eed. Jitschak liet hen gaan, en zij gingen in vrede van hem weg.","JPS: in peace; фр.: amicalement. По-еврейски בְּשָׁלוֹם — с миром."],"genesis-26-32":["В тот же день пришли слуги Ицхака, рассказали ему о колодце, который выкопали, и сказали ему: «Мы нашли воду».","Diezelfde dag kwamen de knechten van Jitschak, vertelden hem over de put die zij hadden gegraven, en zeiden tegen hem: «Wij hebben water gevonden.»",""],"genesis-26-33":["Он назвал её Шива. Поэтому имя города — Беэр-Шева до сего дня.","Hij noemde die Sjiva. Daarom is de naam van de stad Beër-Sjeva tot op deze dag.",""],"genesis-26-34":["Эсаву было сорок лет, и он взял в жёны Йегудит, дочь Беэри, хетта, и Басемат, дочь Эйлона, хетта.","Esav was veertig jaar en nam tot vrouw Jehoedit, de dochter van Beëri de Chitti, en Basemat, de dochter van Elon de Chitti.",""],"genesis-26-35":["Они были горечью духа для Ицхака и Ривки.","Zij werden een bitterheid van geest voor Jitschak en Rivka.",""],"genesis-27-1":["Ицхак состарился, и глаза его ослабели, так что он не видел. Он позвал Эсава, своего старшего сына, и сказал ему: «Сын мой». Тот сказал ему: «Вот я».","Toen Jitschak oud was geworden en zijn ogen dof waren, zodat hij niet zien kon, riep hij Esav, zijn oudste zoon, en zei tegen hem: «Mijn zoon.» Hij zei tegen hem: «Hier ben ik.»",""],"genesis-27-2":["Он сказал: «Вот, я состарился, я не знаю дня моей смерти.","Hij zei: «Zie, ik ben oud geworden, ik weet de dag van mijn dood niet.",""],"genesis-27-3":["Теперь возьми своё оружие, свой колчан и свой лук, выйди в поле и налови мне дичи.","Neem nu je wapens, je pijlkoker en je boog, ga het veld in en jaag wild voor mij.",""],"genesis-27-4":["Приготовь мне вкусное блюдо, какое я люблю, принеси мне, и я поем, чтобы моя душа благословила тебя, прежде чем я умру».","Maak voor mij een smakelijk gerecht, zoals ik het graag heb, breng het mij, en ik zal eten, zodat mijn ziel je zegent voordat ik sterf.»","JPS: my soul; фр.: mon cœur. По-еврейски נַפְשִׁי — моя душа."],"genesis-27-5":["Ривка слышала, как Ицхак говорил Эсаву, своему сыну. Эсав пошёл в поле охотиться на дичь, чтобы принести её.","Rivka hoorde hoe Jitschak sprak tegen Esav, zijn zoon. Esav ging het veld in om wild te jagen en het te brengen.",""],"genesis-27-6":["Ривка сказала Яакову, своему сыну: «Вот, я слышала, как твой отец говорил Эсаву, твоему брату:","Rivka zei tegen Jaäkov, haar zoon: «Hoor, ik heb gehoord hoe je vader tegen Esav, je broer, zei:",""],"genesis-27-7":["„Принеси мне дичь и приготовь мне вкусное блюдо, я поем и благословлю тебя перед Господом перед моей смертью“.","„Breng mij wild en maak voor mij een smakelijk gerecht, dan zal ik eten en je zegenen voor de Eeuwige, vóór mijn dood“.",""],"genesis-27-8":["Теперь, сын мой, послушай мой голос, то, что я тебе велю.","Nu, mijn zoon, luister naar mijn stem, naar wat ik je opdraag.",""],"genesis-27-9":["Пойди к стаду и возьми мне оттуда двух хороших козлят, и я приготовлю из них твоему отцу вкусное блюдо, какое он любит.","Ga naar de kudde en haal mij daarvandaan twee goede geitenbokjes. Ik maak daar voor je vader een smakelijk gerecht van, zoals hij het graag heeft.",""],"genesis-27-10":["Ты принесёшь это отцу, он поест, и он благословит тебя перед смертью».","Jij brengt het naar je vader, hij zal eten, en hij zal je zegenen vóór zijn dood.»",""],"genesis-27-11":["Яаков сказал Ривке, своей матери: «Эсав, мой брат, человек волосатый, а я человек гладкий.","Jaäkov zei tegen Rivka, zijn moeder: «Esav, mijn broer, is een behaarde man, en ik ben een gladde man.",""],"genesis-27-12":["Может быть, отец ощупает меня, и я буду в его глазах как тот, кто его морочит, и навлеку на себя проклятие, а не благословение».","Misschien betast mijn vader mij, en dan lijk ik in zijn ogen iemand die hem voor de gek houdt, en breng ik een vloek over mij, en geen zegen.»","JPS: a mocker; фр.: un trompeur. По-еврейски כִּמְתַעְתֵּעַ — как тот, кто морочит."],"genesis-27-13":["Мать сказала ему: «На мне твоё проклятие, сын мой. Только послушай мой голос, пойди и возьми мне их».","Zijn moeder zei tegen hem: «Op mij je vloek, mijn zoon. Luister alleen naar mijn stem, ga en haal ze voor mij.»",""],"genesis-27-14":["Он пошёл, взял и принёс матери, и мать приготовила вкусное блюдо, какое любил его отец.","Hij ging, nam en bracht het naar zijn moeder, en zijn moeder maakte een smakelijk gerecht, zoals zijn vader het graag had.",""],"genesis-27-15":["Ривка взяла лучшие одежды Эсава, своего старшего сына, которые были у неё в доме, и одела Яакова, своего младшего сына.","Rivka nam de mooiste kleren van Esav, haar oudste zoon, die bij haar in huis waren, en trok ze Jaäkov, haar jongste zoon, aan.",""],"genesis-27-16":["Шкурами козлят она обтянула его руки и гладкое место на шее.","De huiden van de geitenbokjes deed zij om zijn handen en om het gladde van zijn hals.",""],"genesis-27-17":["Она дала вкусное блюдо и хлеб, которые приготовила, в руки Яакова, своего сына.","Zij gaf het smakelijke gerecht en het brood dat zij had gemaakt in de hand van Jaäkov, haar zoon.",""],"genesis-27-18":["Он вошёл к отцу и сказал: «Отец мой». Тот сказал: «Вот я. Кто ты, сын мой?»","Hij kwam bij zijn vader en zei: «Mijn vader.» Die zei: «Hier ben ik. Wie ben jij, mijn zoon?»",""],"genesis-27-19":["Яаков сказал отцу: «Я — Эсав, твой первенец. Я сделал, как ты мне сказал. Встань, прошу, сядь и поешь моей дичи, чтобы твоя душа благословила меня».","Jaäkov zei tegen zijn vader: «Ik ben Esav, je eerstgeborene. Ik heb gedaan zoals je mij gezegd hebt. Sta op, ga zitten en eet van mijn wild, zodat je ziel mij zegent.»","JPS: thy soul; фр.: ton cœur. По-еврейски נַפְשֶׁךָ — твоя душа."],"genesis-27-20":["Ицхак сказал сыну: «Как это ты так быстро нашёл, сын мой?» Тот сказал: «Господь, твой Бог, послал мне навстречу».","Jitschak zei tegen zijn zoon: «Hoe heb je het zo snel gevonden, mijn zoon?» Hij zei: «De Eeuwige, je God, heeft het mij doen tegenkomen.»","JPS: sent me good speed; фр.: bonne chance. По-еврейски הִקְרָה לְפָנָי — послал мне навстречу."],"genesis-27-21":["Ицхак сказал Яакову: «Подойди, я ощупаю тебя, сын мой: ты ли это мой сын Эсав или нет?»","Jitschak zei tegen Jaäkov: «Kom dichterbij, dan betast ik je, mijn zoon, of jij werkelijk mijn zoon Esav bent of niet?»",""],"genesis-27-22":["Яаков подошёл к Ицхаку, своему отцу. Тот ощупал его и сказал: «Голос — голос Яакова, а руки — руки Эсава».","Jaäkov kwam dicht bij Jitschak, zijn vader. Die betastte hem en zei: «De stem is de stem van Jaäkov, maar de handen zijn de handen van Esav.»",""],"genesis-27-23":["Он не узнал его, потому что руки его были волосатые, как руки Эсава, его брата, и благословил его.","Hij herkende hem niet, want zijn handen waren behaard als de handen van Esav, zijn broer, en hij zegende hem.",""],"genesis-27-24":["Он сказал: «Ты и есть мой сын Эсав?» Тот сказал: «Я».","Hij zei: «Ben jij werkelijk mijn zoon Esav?» Hij zei: «Ik ben het.»",""],"genesis-27-25":["Он сказал: «Подай мне, я поем дичи моего сына, чтобы моя душа благословила тебя». Тот подал ему, и он ел. Он принёс ему вина, и он пил.","Hij zei: «Breng het bij mij, dan eet ik van het wild van mijn zoon, zodat mijn ziel je zegent.» Hij bracht het bij hem, en hij at. Hij bracht hem wijn, en hij dronk.","JPS: my soul; фр.: mon cœur. По-еврейски נַפְשִׁי — моя душа."],"genesis-27-26":["Ицхак, его отец, сказал ему: «Подойди и поцелуй меня, сын мой».","Jitschak, zijn vader, zei tegen hem: «Kom dichterbij en kus mij, mijn zoon.»",""],"genesis-27-27":["Он подошёл и поцеловал его. Тот вдохнул запах его одежды, благословил его и сказал: «Вот, запах моего сына — как запах поля, которое благословил Господь.","Hij kwam dichtbij en kuste hem. Die rook de geur van zijn kleren, zegende hem en zei: «Zie, de geur van mijn zoon is als de geur van een veld dat de Eeuwige heeft gezegend.",""],"i-kings-1-32":["Царь Давид сказал: «Позовите ко мне Цадока, священника, Натана, пророка, и Бенаягу, сына Йегояды». Они пришли к царю.","Koning David zei: «Roep Tsadok, de priester, Natan, de profeet, en Benajaoe, de zoon van Jehojada, bij mij.» Zij kwamen voor de koning.",""],"i-kings-1-33":["Царь сказал им: «Возьмите с собой слуг вашего господина, посадите моего сына Шломо на моего мула и сведите его к Гихону.","De koning zei tegen hen: «Neem de dienaren van jullie heer met jullie mee, zet mijn zoon Sjlomo op mijn eigen muildier en breng hem omlaag naar Gichon.",""],"i-kings-1-34":["Там Цадок, священник, и Натан, пророк, помажут его царём над Исраэлем. Затрубите в шофар и скажите: „Да живёт царь Шломо“.","Daar zullen Tsadok, de priester, en Natan, de profeet, hem zalven tot koning over Israël. Blaas op de sjofar en zeg: „Leve koning Sjlomo“.",""],"i-kings-1-35":["Потом поднимитесь за ним. Он придёт, сядет на мой престол и будет царствовать вместо меня. Его я назначил правителем над Исраэлем и над Йегудой».","Daarna trekken jullie achter hem op. Hij zal komen, op mijn troon gaan zitten en in mijn plaats regeren. Hem heb ik aangesteld als vorst over Israël en over Jehoeda.»","JPS: prince; фр.: chef. По-еврейски נָגִיד — назначенный правитель."],"i-kings-1-36":["Бенаягу, сын Йегояды, ответил царю: «Амен. Так пусть скажет Господь, Бог моего господина, царя.","Benajaoe, de zoon van Jehojada, antwoordde de koning: «Amen. Laat de Eeuwige, de God van mijn heer de koning, zo zeggen.",""],"i-kings-1-37":["Как Господь был с моим господином, царём, так пусть будет Он со Шломо и сделает его престол выше престола моего господина, царя Давида».","Zoals de Eeuwige met mijn heer de koning is geweest, zo moge Hij met Sjlomo zijn en zijn troon groter maken dan de troon van mijn heer, koning David.»",""],"i-kings-1-38":["Цадок, священник, Натан, пророк, Бенаягу, сын Йегояды, Керети и Пелети спустились, посадили Шломо на мула царя Давида и повели его к Гихону.","Tsadok de priester, Natan de profeet, Benajaoe de zoon van Jehojada, en de Kereti en de Peleti daalden af, zetten Sjlomo op het muildier van koning David en brachten hem naar Gichon.",""],"i-kings-1-39":["Цадок, священник, взял рог с маслом из шатра и помазал Шломо. Затрубили в шофар, и весь народ сказал: «Да живёт царь Шломо».","Tsadok de priester nam de hoorn met olie uit de tent en zalfde Sjlomo. Zij bliezen op de sjofar, en heel het volk zei: «Leve koning Sjlomo.»",""],"i-kings-1-40":["Весь народ поднялся за ним. Народ играл на флейтах и радовался великой радостью, и земля раскололась от их голоса.","Heel het volk trok achter hem op. Het volk speelde op fluiten en juichte met grote vreugde, en de aarde scheurde van hun geluid.","JPS: the earth rent; фр.: ébranlaient la terre. По-еврейски וַתִּבָּקַע הָאָרֶץ — земля раскололась."],"i-kings-1-41":["Адониягу и все званые, которые были с ним, услышали это, когда кончили есть. Йоав услышал звук шофара и сказал: «Почему шумит город?»","Adoniahoe en alle genodigden die bij hem waren hoorden het, toen zij klaar waren met eten. Joav hoorde het geluid van de sjofar en zei: «Waarom is de stad in oproer?»",""],"i-kings-1-42":["Он ещё говорил, и вот пришёл Йонатан, сын Эвьятара, священника. Адониягу сказал: «Войди. Ты достойный человек и несёшь добрую весть».","Hij sprak nog, en zie, Jonatan, de zoon van Evjatar de priester, kwam. Adoniahoe zei: «Kom binnen. Jij bent een flink man en je brengt goed nieuws.»",""],"i-kings-1-43":["Йонатан ответил Адониягу: «На самом деле наш господин, царь Давид, поставил Шломо царём.","Jonatan antwoordde Adoniahoe: «Werkelijk, onze heer koning David heeft Sjlomo koning gemaakt.",""],"i-kings-1-44":["Царь послал с ним Цадока, священника, Натана, пророка, Бенаягу, сына Йегояды, Керети и Пелети, и они посадили его на мула царя.","De koning heeft Tsadok de priester, Natan de profeet, Benajaoe de zoon van Jehojada en de Kereti en de Peleti met hem meegestuurd, en zij hebben hem op het muildier van de koning gezet.",""],"i-kings-1-45":["Цадок, священник, и Натан, пророк, помазали его царём у Гихона. Оттуда они поднялись радостные, и город шумит. Это тот голос, который вы слышали.","Tsadok de priester en Natan de profeet hebben hem bij Gichon tot koning gezalfd. Zij zijn vandaar opgetrokken, vol vreugde, en de stad is in oproer. Dat is het geluid dat jullie hebben gehoord.",""],"i-kings-1-46":["Шломо тоже сел на царский престол.","Ook heeft Sjlomo plaatsgenomen op de troon van het koningschap.",""],"i-kings-1-47":["Ещё пришли слуги царя благословить нашего господина, царя Давида, и сказали: „Пусть Бог сделает имя Шломо лучше твоего имени, а его престол выше твоего престола“. И царь поклонился на ложе.","Ook kwamen de dienaren van de koning om onze heer, koning David, te zegenen. Zij zeiden: „Moge God de naam van Sjlomo beter maken dan jouw naam en zijn troon groter dan jouw troon.“ En de koning boog zich neer op het bed.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"i-kings-1-48":["А царь сказал ещё так: „Благословен Господь, Бог Исраэля, который сегодня дал сидящего на моём престоле, и мои глаза видят это“».","Ook zei de koning dit: „Gezegend is de Eeuwige, de God van Israël, die vandaag iemand heeft gegeven die op mijn troon zit, en mijn ogen zien het.“»",""],"i-kings-1-49":["Все званые Адониягу затрепетали, встали и пошли каждый своей дорогой.","Alle genodigden van Adoniahoe beefden, stonden op en gingen ieder zijn eigen weg.",""],"i-kings-1-50":["Адониягу испугался Шломо, встал, пошёл и схватился за рога жертвенника.","Adoniahoe was bang voor Sjlomo. Hij stond op, ging en greep de horens van het altaar.",""],"i-kings-1-51":["Шломо передали: «Вот, Адониягу боится царя Шломо. Он схватился за рога жертвенника и говорит: „Пусть царь Шломо поклянётся мне сегодня, что не умертвит своего слугу мечом“».","Men berichtte Sjlomo: «Zie, Adoniahoe is bang voor koning Sjlomo. Hij heeft de horens van het altaar gegrepen en zegt: „Laat koning Sjlomo mij vandaag zweren dat hij zijn dienaar niet met het zwaard zal doden.“»",""],"i-kings-1-52":["Шломо сказал: «Если он будет достойным человеком, ни один волос его не упадёт на землю. А если найдётся в нём зло, он умрёт».","Sjlomo zei: «Als hij een flink man blijkt, zal geen haar van hem op de aarde vallen. Maar als er kwaad in hem gevonden wordt, zal hij sterven.»",""],"i-kings-1-53":["Царь Шломо послал, и его свели с жертвенника. Он пришёл, поклонился царю Шломо, и Шломо сказал ему: «Ступай в свой дом».","Koning Sjlomo stuurde, en zij haalden hem van het altaar af. Hij kwam en boog zich neer voor koning Sjlomo, en Sjlomo zei tegen hem: «Ga naar je huis.»",""],"genesis-30-1":["Рахель увидела, что не родила Яакову, и Рахель позавидовала сестре, и сказала Яакову: «Дай мне сыновей, а если нет — я умру».","Rachel zag dat zij Jaäkov niet gebaard had. Rachel was jaloers op haar zuster en zei tegen Jaäkov: «Geef mij zonen, en zo niet, dan sterf ik.»",""],"genesis-30-2":["Яаков разгневался на Рахель и сказал: «Разве я вместо Бога, который не дал тебе плода чрева?»","Jaäkov werd woedend op Rachel en zei: «Sta ik soms op de plaats van God, die jou de vrucht van de schoot heeft onthouden?»",""],"genesis-30-3":["Она сказала: «Вот моя служанка Бильга. Войди к ней, пусть она родит мне на колени, и через неё у меня тоже будут дети».","Zij zei: «Hier is mijn dienstmaagd Bilha. Ga bij haar binnen, laat zij op mijn knieën baren, en ook ik zal door haar kinderen krijgen.»","JPS: upon my knees; фр.: dans mes bras. По-еврейски עַל־בִּרְכַּי — на моих коленях."],"genesis-30-4":["Она дала ему свою рабыню Бильгу в жёны, и Яаков вошёл к ней.","Zij gaf hem Bilha, haar slavin, tot vrouw, en Jaäkov ging bij haar binnen.",""],"genesis-30-5":["Бильга зачала и родила Яакову сына.","Bilha werd zwanger en baarde Jaäkov een zoon.",""],"genesis-30-6":["Рахель сказала: «Бог рассудил меня, услышал и мой голос и дал мне сына». Поэтому она назвала его Дан.","Rachel zei: «God heeft mij recht gedaan, ook mijn stem gehoord en mij een zoon gegeven.» Daarom noemde zij hem Dan.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-7":["Бильга, рабыня Рахели, снова зачала и родила Яакову второго сына.","Bilha, de slavin van Rachel, werd opnieuw zwanger en baarde Jaäkov een tweede zoon.",""],"genesis-30-8":["Рахель сказала: «Божьей борьбой я боролась с сестрой и одолела». И она назвала его Нафтали.","Rachel zei: «Met een worsteling van God heb ik met mijn zuster geworsteld, en ik heb het gehaald.» En zij noemde hem Naftali.","JPS: mighty wrestlings; фр.: une lutte de Dieu. По-еврейски נַפְתּוּלֵי אֱלֹהִים — борьба Бога."],"genesis-30-9":["Леа увидела, что перестала рожать, взяла свою рабыню Зильпу и дала её Яакову в жёны.","Lea zag dat zij ophield met baren. Zij nam Zilpa, haar slavin, en gaf haar aan Jaäkov tot vrouw.",""],"genesis-30-10":["Зильпа, рабыня Леи, родила Яакову сына.","Zilpa, de slavin van Lea, baarde Jaäkov een zoon.",""],"genesis-30-11":["Леа сказала: «Пришла удача». И назвала его Гад.","Lea zei: «Geluk is gekomen.» En zij noemde hem Gad.","JPS: Fortune is come; фр.: une bande m’arrive. По-еврейски בָּא גָד — пришла удача; имя Гад."],"genesis-30-12":["Зильпа, рабыня Леи, родила Яакову второго сына.","Zilpa, de slavin van Lea, baarde Jaäkov een tweede zoon.",""],"genesis-30-13":["Леа сказала: «К моему счастью, дочери назвали меня счастливой». И она назвала его Ашер.","Lea zei: «Tot mijn geluk: dochters hebben mij gelukkig genoemd.» En zij noemde hem Asjer.","JPS: Happy am I, daughters will call me happy; фр.: né pour mon bonheur, les filles m’ont nommée. По-еврейски בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת — к счастью моему, дочери назвали меня счастливой."],"genesis-30-14":["Реувен пошёл во дни жатвы пшеницы, нашёл в поле мандрагоры и принёс их Лее, своей матери. Рахель сказала Лее: «Дай мне, прошу, мандрагор твоего сына».","Reüven ging in de dagen van de tarweoogst, vond alruinen op het veld en bracht ze naar Lea, zijn moeder. Rachel zei tegen Lea: «Geef mij toch van de alruinen van je zoon.»",""],"genesis-30-15":["Та сказала ей: «Мало того, что ты забрала моего мужа? Ещё и мандрагоры моего сына возьмёшь?» Рахель сказала: «Тогда он ляжет с тобой этой ночью за мандрагоры твоего сына».","Zij zei tegen haar: «Is het nog niet genoeg dat je mijn man hebt genomen? Wil je ook de alruinen van mijn zoon nemen?» Rachel zei: «Dan zal hij vannacht bij jou slapen, in ruil voor de alruinen van je zoon.»",""],"genesis-30-16":["Вечером Яаков пришёл с поля. Леа вышла ему навстречу и сказала: «Ты войдёшь ко мне, потому что я наняла тебя за мандрагоры моего сына». И он спал с ней в ту ночь.","Jaäkov kwam ’s avonds van het veld. Lea ging hem tegemoet en zei: «Bij mij kom je binnen, want ik heb je gehuurd voor de alruinen van mijn zoon.» En hij sliep met haar die nacht.",""],"genesis-30-17":["Бог услышал Лею, она зачала и родила Яакову пятого сына.","God luisterde naar Lea. Zij werd zwanger en baarde Jaäkov een vijfde zoon.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-18":["Леа сказала: «Бог дал мне мою плату за то, что я отдала свою рабыню мужу». И она назвала его Иссахар.","Lea zei: «God heeft mij mijn loon gegeven, omdat ik mijn slavin aan mijn man heb gegeven.» En zij noemde hem Jissachar.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-19":["Леа снова зачала и родила Яакову шестого сына.","Lea werd opnieuw zwanger en baarde Jaäkov een zesde zoon.",""],"genesis-30-20":["Леа сказала: «Бог одарил меня добрым даром. На этот раз мой муж будет жить со мной, потому что я родила ему шестерых сыновей». И она назвала его Зевулун.","Lea zei: «God heeft mij een goed geschenk gegeven. Ditmaal zal mijn man bij mij wonen, omdat ik hem zes zonen heb gebaard.» En zij noemde hem Zevuloen.","JPS: a good dowry, my husband will dwell with me; фр.: m’a accordée comme un don, fera de moi sa compagne. По-еврейски זֵבֶד טוֹב — добрый дар; יִזְבְּלֵנִי — будет жить со мной."],"genesis-30-21":["Потом она родила дочь и назвала её Дина.","Daarna baarde zij een dochter en noemde haar Dina.",""],"genesis-30-22":["Бог вспомнил Рахель, Бог услышал её и открыл её чрево.","God dacht aan Rachel. God luisterde naar haar en opende haar schoot.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-23":["Она зачала, родила сына и сказала: «Бог снял с меня позор».","Zij werd zwanger, baarde een zoon en zei: «God heeft mijn schande weggenomen.»",""],"genesis-30-24":["Она назвала его Йосеф и сказала: «Пусть Господь прибавит мне ещё одного сына».","Zij noemde hem Josef en zei: «De Eeuwige voege mij nog een zoon toe.»","JPS: the LORD; фр.: Dieu. По-еврейски יְהֹוָה — Господь."],"genesis-30-25":["Когда Рахель родила Йосефа, Яаков сказал Лавану: «Отпусти меня, я пойду в своё место и в свою землю.","Toen Rachel Josef had gebaard, zei Jaäkov tegen Lavan: «Laat mij gaan, dan trek ik naar mijn eigen plaats en naar mijn land.",""],"genesis-30-26":["Отдай моих жён и моих детей, тех жён, за которых я служил тебе, и я уйду. Ты сам знаешь, какую службу я сослужил тебе».","Geef mij mijn vrouwen en mijn kinderen, de vrouwen voor wie ik jou gediend heb, en laat mij gaan. Jij weet zelf welke dienst ik jou gedaan heb.»","JPS относит for whom и к детям; фр. — только к жёнам. По-еврейски בָּהֵן женский род: служба за жён."],"genesis-30-27":["Лаван сказал ему: «Если я нашёл милость в твоих глазах… Я гадал, и Господь благословил меня из-за тебя».","Lavan zei tegen hem: «Als ik genade heb gevonden in jouw ogen… Ik heb gewicheld, en de Eeuwige heeft mij om jou gezegend.»","JPS: I have observed the signs; фр.: j’avais bien auguré. По-еврейски נִחַשְׁתִּי — я гадал."],"genesis-30-28":["Он сказал: «Назначь свою плату мне, и я её дам».","Hij zei: «Noem mij je loon, en ik zal het geven.»",""],"genesis-30-29":["Он сказал ему: «Ты знаешь, как я служил тебе и каким стал твой скот у меня.","Hij zei tegen hem: «Jij weet hoe ik jou gediend heb en hoe het je vee bij mij is vergaan.",""],"genesis-30-30":["Мало было у тебя до меня, а оно сильно умножилось, и Господь благословил тебя благодаря мне. Когда же и я поработаю для своего дома?»","Weinig was wat jij had voordat ik kwam, en het is sterk toegenomen, en de Eeuwige heeft jou door mij gezegend. Wanneer zal ik ook voor mijn eigen huis werken?»","JPS: whithersoever I turned; фр.: grâce à moi. По-еврейски לְרַגְלִי — у моей ноги, из-за меня."],"genesis-30-31":["Он сказал: «Что мне дать тебе?» Яаков сказал: «Не давай мне ничего. Если сделаешь для меня вот это, я снова буду пасти твоё стадо и стеречь его.","Hij zei: «Wat zal ik je geven?» Jaäkov zei: «Je hoeft mij niets te geven. Als je dit voor mij doet, zal ik opnieuw je kudde weiden en bewaken.",""],"genesis-30-32":["Я пройду сегодня через всё твоё стадо. Убери оттуда всякую крапчатую и пятнистую скотину, всякую бурую среди овец и пятнистую и крапчатую среди коз. Это будет моя плата.","Ik zal vandaag door heel je kudde gaan. Haal daaruit elk gespikkeld en gevlekt dier weg, elk bruin dier onder de schapen, en de gevlekte en gespikkelde onder de geiten. Dat zal mijn loon zijn.","JPS: dark; фр.: brun. По-еврейски חוּם — бурый."],"genesis-30-33":["Моя праведность ответит против меня завтра, когда ты придёшь посмотреть мою плату перед собой: всякая коза не крапчатая и не пятнистая и всякая овца не бурая, если окажется у меня, — краденая».","Mijn gerechtigheid zal tegen mij getuigen op de dag van morgen, wanneer jij mijn loon komt nazien: elk dier onder de geiten dat niet gespikkeld en gevlekt is, en elk bruin dier onder de schapen, als het bij mij is, is gestolen.»","JPS: witness against me; фр.: parlera pour moi. По-еврейски וְעָנְתָה־בִּי — ответит против меня."],"genesis-30-34":["Лаван сказал: «Хорошо, пусть будет по твоему слову».","Lavan zei: «Goed, laat het zijn zoals jij hebt gezegd.»",""],"genesis-30-35":["В тот день он отделил полосатых и пятнистых козлов, всех крапчатых и пятнистых коз, всякую скотину, в которой была белая шерсть, и всех бурых среди овец, и отдал их в руки своих сыновей.","Die dag haalde hij de gestreepte en gevlekte bokken weg, alle gespikkelde en gevlekte geiten, alles waar wit in zat, en alle bruine dieren onder de schapen, en gaf ze in handen van zijn zonen.",""],"genesis-30-36":["Он положил три дня пути между собой и Яаковом, а Яаков пас оставшееся стадо Лавана.","Hij legde een afstand van drie dagreizen tussen zichzelf en Jaäkov, en Jaäkov weidde wat er over was van de kudde van Lavan.",""],"genesis-30-37":["Яаков взял себе свежие прутья тополя, миндаля и платана и вырезал на них белые полосы, обнажив белизну, которая была на прутьях.","Jaäkov nam verse stokken van populier, amandel en plataan en schilde er witte strepen in, zodat het wit van de stokken bloot kwam.",""],"genesis-30-38":["Он поставил прутья, которые очистил, в желобах, в поилках, куда стадо приходило пить, перед стадом, и они приходили в охоту, когда подходили пить.","Hij zette de stokken die hij geschild had in de goten, in de drinkbakken waar de kudde kwam drinken, vóór de kudde, en zij werden hitsig wanneer zij kwamen drinken.","JPS: they conceived; фр.: entrait en chaleur. По-еврейски וַיֵּחַמְנָה — приходили в охоту."],"genesis-30-39":["Стадо приходило в охоту у прутьев, и стадо рожало полосатых, крапчатых и пятнистых.","De kudde werd hitsig bij de stokken, en de kudde wierp gestreepte, gespikkelde en gevlekte jongen.",""],"genesis-30-40":["Яаков отделил ягнят и поставил стадо лицом к полосатым и ко всем бурым в стаде Лавана. Свои стада он держал отдельно и не ставил их к стаду Лавана.","Jaäkov scheidde de lammeren af en richtte de kudde met het gezicht naar de gestreepte en naar alle bruine dieren in de kudde van Lavan. Zijn eigen kudden hield hij apart en hij zette ze niet bij de kudde van Lavan.","JPS: streaked; фр. здесь: tachetés. По-еврейски עָקֹד — полосатый, как עֲקֻדִּים выше."],"genesis-30-41":["Каждый раз, когда крепкие в стаде приходили в охоту, Яаков клал прутья перед глазами стада в желобах, чтобы они приходили в охоту у прутьев.","Telkens als de sterke dieren van de kudde hitsig werden, legde Jaäkov de stokken voor de ogen van de kudde in de goten, zodat zij bij de stokken hitsig werden.",""],"genesis-30-42":["А когда стадо было слабым, он не клал. Слабые доставались Лавану, а крепкие — Яакову.","Maar als de kudde zwak was, legde hij ze niet. Zo waren de zwakke dieren voor Lavan en de sterke voor Jaäkov.",""],"genesis-30-43":["Этот человек чрезвычайно разбогател. У него было много скота, рабыни и рабы, верблюды и ослы.","De man werd buitengewoon rijk. Hij had veel vee, slavinnen en slaven, kamelen en ezels.",""],"i-kings-3-3":["Шломо любил Господа и ходил по уставам Давида, своего отца. Только на высотах он приносил жертвы и воскурял.","Sjlomo had de Eeuwige lief en leefde naar de inzettingen van zijn vader David. Alleen op de hoogten bracht hij offers en brandde hij wierook.","JPS: sacrificed and offered; фр.: brûlait de l’encens. По-еврейски מַקְטִיר — воскурял."],"i-kings-3-4":["Царь пошёл в Гивон принести там жертву, потому что там была великая высота. Тысячу всесожжений вознёс Шломо на том жертвеннике.","De koning ging naar Givon om daar te offeren, want daar was de grote hoogte. Duizend brandoffers bracht Sjlomo op dat altaar.",""],"i-kings-3-5":["В Гивоне Господь явился Шломо в ночном сне, и Бог сказал: «Проси, что Мне дать тебе».","In Givon verscheen de Eeuwige aan Sjlomo in een droom bij nacht, en God zei: «Vraag wat Ik je geven zal.»","Является יְהֹוָה, говорит אֱלֹהִים. JPS сохраняет оба; фр. сводит речь к Seigneur."],"i-kings-3-6":["Шломо сказал: «Ты сделал великую милость Твоему слуге Давиду, моему отцу, как он ходил перед Тобой в истине, в праведности и в прямоте сердца с Тобой. Ты сохранил ему эту великую милость и дал ему сына, который сидит на его престоле, как это сегодня.","Sjlomo zei: «U hebt Uw dienaar David, mijn vader, grote goedheid bewezen, zoals hij voor U wandelde in waarheid, in gerechtigheid en in oprechtheid van hart met U. U hebt deze grote goedheid voor hem bewaard en hem een zoon gegeven die op zijn troon zit, zoals het vandaag is.","JPS: according as he walked; фр.: parce qu’il a marché. По-еврейски כַּאֲשֶׁר — как он ходил."],"i-kings-3-7":["А теперь, Господь, Бог мой, Ты поставил Твоего слугу царём вместо Давида, моего отца, а я малый юноша и не умею ни выйти, ни войти.","Nu dan, Eeuwige, mijn God, U hebt Uw dienaar koning gemaakt in de plaats van mijn vader David, en ik ben een jonge jongen, ik weet niet uit te gaan of binnen te komen.","JPS: I know not how to go out or come in; фр.: inhabile à me conduire. По-еврейски לֹא אֵדַע צֵאת וָבֹא — не умею выйти и войти."],"i-kings-3-8":["Твой слуга — среди Твоего народа, который Ты избрал, народа великого, которого не счесть и не пересчитать, так его много.","Uw dienaar staat te midden van Uw volk dat U hebt uitgekozen, een groot volk dat niet geteld en niet opgesomd kan worden, zo talrijk is het.",""],"i-kings-3-9":["Дай Твоему слуге слушающее сердце, чтобы судить Твой народ и различать добро и зло. Кто сможет судить этот многочисленный народ Твой?»","Geef Uw dienaar een luisterend hart om Uw volk te richten en te onderscheiden tussen goed en kwaad. Want wie kan dit talrijke volk van U richten?»","JPS: an understanding heart; фр.: un cœur intelligent. По-еврейски לֵב שֹׁמֵעַ — слушающее сердце."],"i-kings-3-10":["Это было угодно Владыке, что Шломо просил именно этого.","Het beviel de Heer dat Sjlomo juist dit had gevraagd.","В стихе אֲדֹנָי, не יהוה: Владыка / Heer."],"i-kings-3-11":["Бог сказал ему: «За то, что ты просил этого и не просил себе долгих дней, не просил себе богатства и не просил души твоих врагов, а просил себе разумения, чтобы слышать суд,","God zei tegen hem: «Omdat je dit gevraagd hebt, en niet voor jezelf vele dagen hebt gevraagd, en niet voor jezelf rijkdom hebt gevraagd, en niet het leven van je vijanden hebt gevraagd, maar voor jezelf inzicht hebt gevraagd om recht te horen,",""],"i-kings-3-12":["Вот, Я сделал по твоим словам. Вот, Я дал тебе мудрое и разумное сердце, так что подобного тебе не было до тебя, и после тебя не встанет подобный тебе.","Zie, Ik heb gedaan naar je woorden. Zie, Ik heb je een wijs en verstandig hart gegeven, zodat er vóór jou niemand was zoals jij, en na jou zal niemand opstaan zoals jij.",""],"i-kings-3-13":["Также то, чего ты не просил, Я дал тебе: и богатство, и почёт, так что не было подобного тебе никого среди царей во все твои дни.","Ook wat je niet gevraagd hebt, heb Ik je gegeven: rijkdom en eer, zodat er onder de koningen niemand was zoals jij, al je dagen.",""],"i-kings-3-14":["Если ты будешь ходить Моими путями, хранить Мои уставы и Мои мицвот, как ходил Давид, твой отец, Я продлю твои дни».","Als je op Mijn wegen gaat, om Mijn inzettingen en Mijn mitswot te houden, zoals je vader David is gegaan, dan zal Ik je dagen verlengen.»",""],"i-kings-3-15":["Шломо проснулся, и вот — это сон. Он пришёл в Йерушалаим, встал перед ковчегом брит Владыки, вознёс всесожжения, принёс жертвы благополучия и устроил пир всем своим слугам.","Sjlomo ontwaakte, en zie, het was een droom. Hij kwam naar Jeroesjalajim, ging staan voor de ark van de briet van de Heer, bracht brandoffers, bracht vredeoffers en richtte een maaltijd aan voor al zijn dienaren.","В стихе אֲדֹנָי, не יהוה: Владыка / Heer. JPS: peace-offerings; фр.: sacrifices rémunératoires. По-еврейски שְׁלָמִים — жертвы благополучия."],"genesis-34-1":["Дина, дочь Леи, которую та родила Яакову, вышла посмотреть на дочерей земли.","Dina, de dochter van Lea, die zij aan Jaäkov had gebaard, ging naar buiten om de dochters van het land te zien.","JPS: to see; фр.: faire connaissance. По-еврейски לִרְאוֹת — посмотреть."],"genesis-34-2":["Увидел её Шехем, сын Хамора, хивви, князь земли. Он взял её, был с ней и унизил её.","Sjechem, de zoon van Chamor, de Chivvi, vorst van het land, zag haar. Hij nam haar, sliep met haar en vernederde haar.","JPS сохраняет три глагола: took, lay with, humbled. Фр. сводит их к enleva и s’approcha en faisant violence. По-еврейски וַיִּקַּח, וַיִּשְׁכַּב, וַיְעַנֶּהָ."],"genesis-34-3":["Его душа прилепилась к Дине, дочери Яакова. Он полюбил девушку и говорил к сердцу девушки.","Zijn ziel kleefde aan Dina, de dochter van Jaäkov. Hij hield van het meisje en sprak tot het hart van het meisje.","JPS: spoke comfortingly; фр.: parla à son cœur. По-еврейски עַל־לֵב — говорил к сердцу девушки."],"genesis-34-4":["Шехем сказал Хамору, своему отцу: «Возьми мне эту девочку в жёны».","Sjechem zei tegen Chamor, zijn vader: «Neem dit jonge meisje voor mij tot vrouw.»",""],"genesis-34-5":["Яаков услышал, что тот осквернил Дину, его дочь. Сыновья Яакова были с его скотом в поле, и Яаков молчал, пока они не пришли.","Jaäkov hoorde dat hij Dina, zijn dochter, ontreinigd had. Zijn zonen waren met zijn vee op het veld, en Jaäkov zweeg tot zij kwamen.","JPS: defiled; фр.: déshonoré. По-еврейски טִמֵּא — осквернил."],"genesis-34-6":["Хамор, отец Шехема, вышел к Яакову, чтобы говорить с ним.","Chamor, de vader van Sjechem, ging naar Jaäkov toe om met hem te spreken.",""],"genesis-34-7":["Сыновья Яакова пришли с поля, когда услышали это. Эти люди горевали и сильно разгневались, потому что он сделал гнусность в Исраэле: был с дочерью Яакова. Так не делают.","De zonen van Jaäkov kwamen van het veld toen zij het hoorden. De mannen waren bedroefd en werden zeer kwaad, omdat hij een schanddaad in Israël had gedaan: hij had met de dochter van Jaäkov geslapen. Zo doet men niet.","JPS: lying with; фр.: viol. По-еврейски לִשְׁכַּב אֶת — был с дочерью Яакова."],"genesis-34-8":["Хамор говорил с ними: «Душа моего сына Шехема привязалась к вашей дочери. Отдайте же её ему в жёны.","Chamor sprak met hen: «De ziel van mijn zoon Sjechem hangt aan jullie dochter. Geef haar toch aan hem tot vrouw.",""],"genesis-34-9":["Породнитесь с нами: ваших дочерей отдавайте нам, а наших дочерей берите себе.","Sluit huwelijken met ons: geef jullie dochters aan ons en neem onze dochters voor jullie.",""],"genesis-34-10":["Живите с нами, и земля будет перед вами. Селитесь, торгуйте на ней и берите на ней владение».","Woon bij ons, en het land ligt voor jullie open. Vestig je, drijf er handel en neem er bezit.»","JPS: trade; фр.: exploitez. По-еврейски וְסִחֲרוּהָ — торгуйте."],"genesis-34-11":["Шехем сказал её отцу и её братьям: «Пусть я найду благоволение в ваших глазах. Что скажете мне, то я дам.","Sjechem zei tegen haar vader en haar broers: «Laat ik gunst vinden in jullie ogen. Wat jullie tegen mij zeggen, zal ik geven.",""],"genesis-34-12":["Назначьте мне очень большой выкуп за невесту и дар, и я дам, как вы скажете мне. Только отдайте мне девушку в жёны».","Leg mij een zeer hoge bruidsprijs en een groot geschenk op. Ik geef wat jullie mij zeggen. Geef mij alleen het meisje tot vrouw.»",""],"genesis-34-13":["Сыновья Яакова ответили Шехему и Хамору, его отцу, с обманом. Они говорили так, потому что он осквернил Дину, их сестру.","De zonen van Jaäkov antwoordden Sjechem en Chamor, zijn vader, met bedrog. Zij spraken zo omdat hij Dina, hun zuster, ontreinigd had.",""],"genesis-34-14":["Они сказали им: «Мы не можем сделать это — отдать нашу сестру мужчине, у которого есть крайняя плоть. Это позор для нас.","Zij zeiden tegen hen: «Wij kunnen dit niet doen: onze zuster geven aan een man die een voorhuid heeft. Dat is een schande voor ons.",""],"genesis-34-15":["Только на этом мы согласимся с вами: если вы станете как мы и у вас будет обрезан каждый мужчина.","Alleen hierop stemmen wij met jullie in: als jullie worden zoals wij en bij jullie iedere man besneden wordt.",""],"genesis-34-16":["Тогда мы отдадим вам наших дочерей, а ваших дочерей возьмём себе, будем жить с вами и станем одним народом.","Dan geven wij onze dochters aan jullie en nemen wij jullie dochters voor ons. Wij zullen bij jullie wonen en één volk worden.",""],"genesis-34-17":["Если же вы не послушаете нас и не обрежетесь, мы заберём нашу дочь и уйдём».","Maar als jullie niet naar ons luisteren en je niet laten besnijden, nemen wij onze dochter mee en gaan wij weg.»",""],"genesis-34-18":["Их слова были хороши в глазах Хамора и в глазах Шехема, сына Хамора.","Hun woorden waren goed in de ogen van Chamor en in de ogen van Sjechem, de zoon van Chamor.",""],"genesis-34-19":["Юноша не замедлил сделать это, потому что ему была желанна дочь Яакова. А он был почтённее всех в доме своего отца.","De jongeman stelde het niet uit om het te doen, want hij begeerde de dochter van Jaäkov. Hij was geëerd boven allen in het huis van zijn vader.","JPS: deferred not; фр.: n’hésita point. По-еврейски לֹא־אֵחַר — не замедлил."],"genesis-34-20":["Хамор и Шехем, его сын, пришли к воротам своего города и сказали людям своего города:","Chamor en zijn zoon Sjechem kwamen bij de poort van hun stad en zeiden tegen de mannen van hun stad:",""],"genesis-34-21":["«Эти люди мирны с нами. Пусть живут на земле и торгуют на ней: земля перед ними просторна. Их дочерей возьмём себе в жёны, а наших дочерей отдадим им.","«Deze mannen zijn in vrede met ons. Laten zij in het land wonen en er handel drijven: het land ligt wijd voor hen open. Hun dochters nemen wij voor ons tot vrouwen, en onze dochters geven wij aan hen.","JPS: peaceable; фр.: de bonne foi. По-еврейски שְׁלֵמִים — мирны, целы с нами."],"genesis-34-22":["Только на этом эти люди согласятся жить с нами и стать одним народом: если у нас будет обрезан каждый мужчина, как обрезаны они.","Alleen hierop zullen deze mannen instemmen om bij ons te wonen en één volk te worden: als bij ons iedere man besneden wordt, zoals zij besneden zijn.",""],"genesis-34-23":["Их скот, их имущество и все их животные — разве не нашими они будут? Только согласимся с ними, и они будут жить с нами».","Hun vee, hun have en al hun dieren, zullen die niet van ons worden? Laten wij alleen met hen instemmen, dan zullen zij bij ons wonen.»",""],"genesis-34-24":["Хамора и Шехема, его сына, послушали все, кто выходит из ворот его города. Обрезали каждого мужчину — всех, кто выходит из ворот его города.","Naar Chamor en naar zijn zoon Sjechem luisterden allen die de poort van zijn stad uitgingen. Zij besneden iedere man, allen die de poort van zijn stad uitgingen.","JPS: went out of the gate; фр.: habitaient l’enceinte, citoyens. По-еврейски יֹצְאֵי שַׁעַר — выходящие из ворот города."],"genesis-34-25":["На третий день, когда им было больно, двое из сыновей Яакова, Шимон и Леви, братья Дины, взяли каждый свой меч, пришли на город спокойно и убили всех мужчин.","Op de derde dag, toen zij pijn hadden, namen twee zonen van Jaäkov, Sjimon en Levi, broers van Dina, ieder zijn zwaard en kwamen rustig op de stad af en doodden alle mannen.","JPS: unawares; фр.: avec assurance. По-еврейски בֶּטַח — спокойно: город был беспечен, братья шли без боязни."],"genesis-34-26":["Хамора и Шехема, его сына, они убили остриём меча, забрали Дину из дома Шехема и вышли.","Chamor en zijn zoon Sjechem doodden zij met de scherpte van het zwaard. Zij haalden Dina uit het huis van Sjechem en gingen weg.",""],"genesis-34-27":["Сыновья Яакова пришли к убитым и разграбили город, потому что те осквернили их сестру.","De zonen van Jaäkov kwamen bij de gevallenen en plunderden de stad, omdat zij hun zuster ontreinigd hadden.","JPS: they had defiled; фр.: la ville avait déshonoré. По-еврейски טִמְּאוּ — множественное число: осквернили."],"genesis-34-28":["Их овец, их крупный скот и их ослов, и то, что было в городе, и то, что было в поле, они забрали.","Hun schapen, hun runderen en hun ezels, en wat in de stad was en wat op het veld was, namen zij mee.",""],"genesis-34-29":["Всё их добро, всех их детей и их жён они увели в плен и разграбили, и всё, что было в доме.","Al hun goed, al hun kinderen en hun vrouwen voerden zij gevangen weg en plunderden zij, en alles wat in huis was.",""],"genesis-34-30":["Яаков сказал Шимону и Леви: «Вы привели меня в беду и сделали меня смрадным для жителей земли, для кнаани и перизея. А меня мало числом. Они соберутся против меня, разобьют меня, и я буду истреблён, я и мой дом».","Jaäkov zei tegen Sjimon en Levi: «Jullie hebben mij in het ongeluk gestort en mij stinkend gemaakt bij de bewoners van het land, bij de Kenaäniet en de Perizzi. En ik ben met weinig man. Zij zullen zich tegen mij verzamelen en mij verslaan, en ik zal worden weggevaagd, ik en mijn huis.»",""],"genesis-34-31":["Они сказали: «Разве с нашей сестрой поступают как с блудницей?»","Zij zeiden: «Moest men onze zuster behandelen als een vrouw die zich verkoopt?»",""],"genesis-35-1":["Бог сказал Яакову: «Встань, поднимись в Бейт-Эль и живи там. Сделай там жертвенник Богу, который явился тебе, когда ты бежал от Эсава, своего брата».","God zei tegen Jaäkov: «Sta op, trek op naar Bet-El en woon daar. Maak daar een altaar voor de God die aan je verscheen toen je vluchtte voor Esav, je broer.»","Фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог, не Господь."],"genesis-35-2":["Яаков сказал своему дому и всем, кто был с ним: «Уберите чужих богов, которые среди вас, очиститесь и смените одежды.","Jaäkov zei tegen zijn huis en tegen allen die bij hem waren: «Doe de vreemde goden weg die bij jullie zijn, reinig je en verwissel je kleren.",""],"genesis-35-3":["Встанем и поднимемся в Бейт-Эль. Я сделаю там жертвенник Богу, который ответил мне в день моей беды и был со мной на пути, которым я шёл».","Laten wij opstaan en optrekken naar Bet-El. Ik zal daar een altaar maken voor de God die mij antwoord gaf op de dag van mijn nood en met mij was op de weg die ik ging.»",""],"genesis-35-4":["Они отдали Яакову всех чужих богов, которые были у них в руках, и серьги, которые были у них в ушах. Яаков закопал их под теребинтом, что у Шехема.","Zij gaven Jaäkov alle vreemde goden die in hun hand waren, en de ringen die in hun oren waren. Jaäkov begroef ze onder de terebint bij Sjechem.","JPS: rings, terebinth; фр.: joyaux, tilleul. По-еврейски נְזָמִים — серьги, הָאֵלָה — теребинт."],"genesis-35-5":["Они двинулись в путь. Ужас Божий был на городах вокруг них, и те не гнались за сыновьями Яакова.","Zij trokken verder. Een schrik van God lag op de steden rondom hen, en die achtervolgden de zonen van Jaäkov niet.",""],"genesis-35-6":["Яаков пришёл в Луз, что в земле Кнаан, то есть в Бейт-Эль, он и весь народ, который был с ним.","Jaäkov kwam in Loez, in het land Kenaän, dat is Bet-El, hij en heel het volk dat bij hem was.",""],"genesis-35-7":["Он построил там жертвенник и назвал это место Эль Бейт-Эль, потому что там ему открылся Бог, когда он бежал от своего брата.","Hij bouwde daar een altaar en noemde de plaats El Bet-El, omdat God zich daar aan hem openbaarde toen hij vluchtte voor zijn broer.","JPS: God was revealed; фр.: les puissances célestes. По-еврейски נִגְלוּ אֵלָיו הָאֱלֹהִים — глагол во множественном числе."],"genesis-35-8":["Умерла Двора, кормилица Ривки. Её похоронили ниже Бейт-Эля, под дубом, и он назвал его Аллон-Бахут.","Dvora, de voedster van Rivka, stierf. Zij werd begraven beneden Bet-El, onder de eik, en hij gaf die de naam Allon-Bachoet.","Фр. переводит имя: le Chêne des Pleurs. По-еврейски אַלּוֹן בָּכוּת — имя Аллон-Бахут."],"genesis-35-9":["Бог снова явился Яакову, когда тот пришёл из Падан-Арама, и благословил его.","God verscheen opnieuw aan Jaäkov toen hij uit Paddan-Aram kwam, en Hij zegende hem.","JPS: Paddan-aram; фр.: territoire d’Aram. По-еврейски פַּדַּן אֲרָם — Падан-Арам."],"genesis-35-10":["Бог сказал ему: «Имя твоё — Яаков. Не будут больше звать тебя Яаков, но Исраэль будет твоё имя». И Он назвал его Исраэль.","God zei tegen hem: «Je naam is Jaäkov. Je naam zal niet meer Jaäkov worden genoemd, maar Israël zal je naam zijn.» En Hij noemde hem Israël.",""],"genesis-35-11":["Бог сказал ему: «Я — Эль Шаддай. Плодись и умножайся. От тебя будет народ и собрание народов, и цари выйдут из твоих чресел.","God zei tegen hem: «Ik ben El Sjaddai. Wees vruchtbaar en word talrijk. Uit jou zal een volk komen en een vergadering van volken, en koningen zullen uit je lendenen voortkomen.","JPS: God Almighty, a company of nations; фр.: Dieu tout puissant, un essaim de peuples. По-еврейски אֵל שַׁדַּי — имя Эль Шаддай; קְהַל גּוֹיִם — собрание народов."],"genesis-35-12":["Землю, которую Я дал Аврааму и Ицхаку, Я отдам тебе, и твоему потомству после тебя отдам эту землю».","Het land dat Ik aan Abraham en aan Jitschak heb gegeven, zal Ik aan jou geven, en aan jouw nageslacht na jou zal Ik het land geven.»",""],"genesis-35-13":["Бог поднялся от него на том месте, где говорил с ним.","God steeg op van hem, op de plaats waar Hij met hem gesproken had.","JPS: God went up; фр.: le Seigneur disparut. По-еврейски וַיַּעַל אֱלֹהִים — Бог поднялся."],"genesis-35-14":["Яаков поставил стелу на том месте, где Он говорил с ним, каменную стелу, возлил на неё возлияние и вылил на неё масло.","Jaäkov zette een staande steen op de plaats waar Hij met hem gesproken had, een stenen zuil, en hij goot er een plengoffer over uit en goot er olie over.","JPS: pillar; фр.: monument. По-еврейски מַצֵּבָה — поставленный камень."],"genesis-35-15":["Яаков назвал имя места, где Бог говорил с ним, Бейт-Эль.","Jaäkov noemde de naam van de plaats waar God met hem gesproken had: Bet-El.","Фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"joshua-9-1":["Когда услышали все цари, которые по стороне Ярдена, в горах, в низине и по всему берегу Великого моря напротив Леванона, — хетты и эмори, кнаани, перизеи, хивви и евусеи, —","Toen alle koningen het hoorden die aan de zijde van de Jarden waren, in het bergland, in het laagland en langs heel de kust van de Grote Zee tegenover Levanon — de Chitti en de Emori, de Kenaäniet, de Perizzi, de Chivvi en de Jevusiet —","JPS: beyond the Jordan, the Lowland, in front of Lebanon; фр.: rive, vallée, jusqu’au Liban. По-еврейски עֵבֶר — сторона Ярдена, שְׁפֵלָה — низина, אֶל־מוּל — напротив Леванона."],"joshua-9-2":["они собрались вместе, чтобы воевать с Йехошуа и с Исраэлем, одними устами.","verzamelden zij zich samen om te strijden tegen Jehosjoea en tegen Israël, met één mond.",""],"joshua-9-3":["Жители Гивона услышали, что сделал Йехошуа с Йерихо и с Ай.","De inwoners van Givon hoorden wat Jehosjoea met Jericho en met Ai had gedaan.",""],"joshua-9-4":["Они тоже поступили хитро: пошли, выдали себя за послов и взяли на своих ослов ветхие мешки и винные мехи, ветхие, лопнувшие и перевязанные,","Ook zij handelden met list: zij gingen, gaven zich uit voor gezanten en namen oude zakken mee voor hun ezels, en wijnzakken, oud, gescheurd en dichtgebonden,","JPS: ambassadors; фр.: munis de provisions. В стихе וַיִּצְטַיָּרוּ — выдали себя за послов. JPS: patched; фр.: recousues. מְצֹרָרִים — перевязаны."],"joshua-9-5":["и ветхие залатанные сандалии на ногах, и ветхие плащи на себе. Весь хлеб их припаса был сухой и в крошках.","en versleten, gelapte sandalen aan hun voeten, en versleten mantels om zich heen. Al het brood van hun proviand was droog en verkruimeld.","JPS: crumbs; фр.: moisi. По-еврейски נִקֻּדִים — в крошках, с пятнами."],"joshua-9-6":["Они пришли к Йехошуа, в стан в Гилгаль, и сказали ему и людям Исраэля: «Из далёкой земли мы пришли. Теперь заключите с нами брит».","Zij kwamen bij Jehosjoea, in het kamp te Gilgal, en zeiden tegen hem en tegen de mannen van Israël: «Wij zijn uit een ver land gekomen. Sluit nu een briet met ons.»",""],"joshua-9-7":["Человек Исраэля сказал хивви: «Может быть, ты живёшь среди меня. Как же я заключу с тобой брит?»","De man van Israël zei tegen de Chivvi: «Misschien woon jij in mijn midden. Hoe zou ik dan een briet met jou sluiten?»",""],"joshua-9-8":["Они сказали Йехошуа: «Мы твои рабы». Йехошуа сказал им: «Кто вы и откуда пришли?»","Zij zeiden tegen Jehosjoea: «Wij zijn jouw dienaren.» Jehosjoea zei tegen hen: «Wie zijn jullie, en waar komen jullie vandaan?»",""],"joshua-9-9":["Они сказали ему: «Из очень далёкой земли пришли твои рабы ради имени Господа, твоего Бога. Мы слышали весть о Нём и обо всём, что Он сделал в Египте,","Zij zeiden tegen hem: «Uit een zeer ver land zijn jouw dienaren gekomen omwille van de naam van de Eeuwige, jouw God. Wij hebben de roep over Hem gehoord en alles wat Hij in Egypte heeft gedaan,",""],"joshua-9-10":["и обо всём, что Он сделал двум царям эмори, которые по ту сторону Ярдена: Сихону, царю Хешбона, и Огу, царю Башана, который в Аштароте.","en alles wat Hij heeft gedaan aan de twee koningen van de Emori aan de overkant van de Jarden: aan Sichon, koning van Chesjbon, en aan Og, koning van Basjan, die in Asjtarot was.",""],"joshua-9-11":["Наши старейшины и все жители нашей земли сказали нам: „Возьмите в руки припас на дорогу, идите им навстречу и скажите им: ‚Мы ваши рабы. Теперь заключите с нами брит‘“.","Onze oudsten en alle inwoners van ons land zeiden tegen ons: „Neem proviand voor onderweg in jullie handen, ga hun tegemoet en zeg tegen hen: ‚Wij zijn jullie dienaren. Sluit nu een briet met ons‘.“",""],"joshua-9-12":["Этот наш хлеб мы взяли горячим в припас из наших домов в тот день, когда вышли идти к вам. А теперь вот он сухой и в крошках.","Dit brood van ons namen wij heet mee als proviand uit onze huizen, op de dag dat wij vertrokken om naar jullie te gaan. En nu, zie, het is droog en verkruimeld.","JPS: hot, crumbs; фр.: frais, moisi. По-еврейски חָם — горячий; נִקֻּדִים — в крошках, с пятнами."],"joshua-9-13":["А эти винные мехи мы наполнили новыми, и вот они лопнули. Эти наши плащи и наши сандалии износились от очень долгого пути».","Deze wijnzakken vulden wij nieuw, en zie, ze zijn gescheurd. Deze mantels van ons en onze sandalen zijn versleten van de zeer lange weg.»",""],"joshua-9-14":["Люди взяли из их припаса, а уст Господа не спросили.","De mannen namen van hun proviand, maar de mond van de Eeuwige vroegen zij niet.","JPS добавляет counsel при mouth of the LORD; фр.: consulté le Seigneur, без «уст». По-еврейски אֶת־פִּי יְהוָה לֹא שָׁאָלוּ — не спросили уст Господа."],"joshua-9-15":["Йехошуа заключил с ними мир и заключил с ними брит, чтобы оставить их в живых. Князья общины поклялись им.","Jehosjoea maakte vrede met hen en sloot een briet met hen om hen in leven te laten. De vorsten van de gemeente zwoeren hun een eed.",""],"joshua-9-16":["По прошествии трёх дней после того, как они заключили с ними брит, услышали, что те близки к нему и живут среди него.","Na verloop van drie dagen, nadat zij een briet met hen hadden gesloten, hoorden zij dat zij dicht bij hem waren en in zijn midden woonden.",""],"joshua-9-17":["Сыны Исраэля выступили и на третий день пришли к их городам. Их города: Гивон, Кефира, Беэрот и Кирьят-Еарим.","De zonen van Israël trokken uit en kwamen op de derde dag bij hun steden. Hun steden waren Givon, Kefira, Beërot en Kirjat-Jearim.",""],"joshua-9-18":["Сыны Исраэля не ударили их, потому что князья общины поклялись им Господом, Богом Исраэля. Вся община роптала на князей.","De zonen van Israël sloegen hen niet, want de vorsten van de gemeente hadden hun gezworen bij de Eeuwige, de God van Israël. Heel de gemeente morde tegen de vorsten.",""],"joshua-9-19":["Все князья сказали всей общине: «Мы поклялись им Господом, Богом Исраэля. Теперь мы не можем тронуть их.","Alle vorsten zeiden tegen heel de gemeente: «Wij hebben hun gezworen bij de Eeuwige, de God van Israël. Nu kunnen wij hen niet aanraken.",""],"joshua-9-20":["Вот что мы сделаем им: оставим их в живых, и не будет на нас гнева из-за клятвы, которой мы им поклялись».","Dit zullen wij hun doen: wij laten hen leven, zodat er geen toorn over ons komt vanwege de eed die wij hun hebben gezworen.»","Фр. добавляет divine к קֶצֶף. По-еврейски просто гнев."],"genesis-38-1":["В то время Йегуда отошёл от своих братьев и свернул к одному адулламитянину, которого звали Хира.","In die tijd ging Jehoeda weg van zijn broers en week hij af naar een man uit Adullam, wiens naam Chira was.",""],"genesis-38-2":["Там Йегуда увидел дочь одного кнаани, которого звали Шуа. Он взял её и вошёл к ней.","Daar zag Jehoeda de dochter van een Kenaäniet die Sjoea heette. Hij nam haar en ging bij haar naar binnen.","JPS: took her and went in unto her; фр.: l’épousa et s’approcha. По-еврейски וַיִּקָּחֶהָ וַיָּבֹא אֵלֶיהָ — взял её и вошёл к ней."],"genesis-38-3":["Она зачала, родила сына, и он назвал его Эр.","Zij werd zwanger, baarde een zoon, en hij noemde hem Er.",""],"genesis-38-4":["Она снова зачала, родила сына, и она назвала его Онан.","Zij werd opnieuw zwanger, baarde een zoon, en zij noemde hem Onan.",""],"genesis-38-5":["Она родила ещё сына и назвала его Шела. Он был в Кезиве, когда она родила его.","Zij baarde nog een zoon en noemde hem Sjela. Hij was in Keziv toen zij hem baarde.",""],"genesis-38-6":["Йегуда взял жену Эру, своему первенцу. Её звали Тамар.","Jehoeda nam een vrouw voor Er, zijn eerstgeborene. Haar naam was Tamar.",""],"genesis-38-7":["Эр, первенец Йегуды, был зол в глазах Господа, и Господь умертвил его.","Er, de eerstgeborene van Jehoeda, was slecht in de ogen van de Eeuwige, en de Eeuwige deed hem sterven.","JPS: wicked; фр.: ayant déplu. По-еврейски רַע — зол в глазах Господа."],"genesis-38-8":["Йегуда сказал Онану: «Войди к жене твоего брата, возьми её вместо него и восставь семя твоему брату».","Jehoeda zei tegen Onan: «Ga naar de vrouw van je broer, neem haar in zijn plaats en verwek nageslacht voor je broer.»","JPS: perform the duty of a husband’s brother; фр.: en vertu du lévirat. По-еврейски וְיַבֵּם אֹתָהּ — глагол, без позднего термина «левират»."],"genesis-38-9":["Онан знал, что семя будет не ему. Когда он входил к жене своего брата, он изливал его на землю, чтобы не дать семя своему брату.","Onan wist dat het zaad niet van hem zou zijn. Telkens wanneer hij naar de vrouw van zijn broer ging, stortte hij het op de grond, om zijn broer geen zaad te geven.","JPS: spilled it on the ground; фр.: corrompait sa voie. По-еврейски וְשִׁחֵת אַרְצָה — изливал на землю."],"genesis-38-10":["То, что он сделал, было зло в глазах Господа, и Он умертвил и его.","Wat hij deed, was slecht in de ogen van de Eeuwige, en Hij deed ook hem sterven.",""],"genesis-38-11":["Йегуда сказал Тамар, своей невестке: «Сиди вдовой в доме твоего отца, пока не вырастет Шела, мой сын». Ибо он сказал: «Как бы не умер и он, как его братья». Тамар пошла и жила в доме своего отца.","Jehoeda zei tegen Tamar, zijn schoondochter: «Blijf als weduwe in het huis van je vader, totdat mijn zoon Sjela groot is.» Want hij zei: «Anders sterft ook hij, zoals zijn broers.» Tamar ging weg en woonde in het huis van haar vader.","JPS: for he said; фр.: car il craignait. По-еврейски כִּי אָמַר — ибо он сказал."],"genesis-38-12":["Прошло много дней, и умерла дочь Шуа, жена Йегуды. Йегуда утешился и поднялся к стригальщикам своего скота, он и его друг Хира, адулламитянин, в Тимну.","Er gingen vele dagen voorbij, en de dochter van Sjoea, de vrouw van Jehoeda, stierf. Jehoeda was getroost en trok op naar de scheerders van zijn kudde, hij en zijn vriend Chira, de Adullamiet, naar Timna.","JPS: unto his sheep-shearers; фр.: surveiller la tonte. По-еврейски עַל־גֹּזְזֵי צֹאנוֹ — к стригальщикам его скота."],"genesis-38-13":["Тамар сказали: «Вот твой свёкор поднимается в Тимну стричь свой скот».","Men berichtte Tamar: «Zie, je schoonvader trekt op naar Timna om zijn kudde te scheren.»",""],"genesis-38-14":["Она сняла с себя одежды вдовства, закрылась покрывалом, закуталась и села у входа в Энаим, что на дороге в Тимну. Она видела, что Шела вырос, а её не отдали ему в жёны.","Zij legde haar weduwkleren af, bedekte zich met een sluier, wikkelde zich in en ging zitten bij de ingang van Enajim, aan de weg naar Timna. Zij zag dat Sjela groot was geworden en dat zij hem niet tot vrouw was gegeven.","JPS: the entrance of Enaim; фр.: le carrefour des Deux Sources. По-еврейски פֶּתַח עֵינַיִם — вход Энаим."],"genesis-38-15":["Йегуда увидел её и счёл её блудницей, потому что она закрыла лицо.","Jehoeda zag haar en hield haar voor een vrouw die zich verkoopt, omdat zij haar gezicht bedekt had.",""],"genesis-38-16":["Он свернул к ней с дороги и сказал: «Дай, я войду к тебе». Он не знал, что это его невестка. Она сказала: «Что ты дашь мне, если войдёшь ко мне?»","Hij week naar haar af, bij de weg, en zei: «Toe, laat mij bij je naar binnen gaan.» Hij wist niet dat zij zijn schoondochter was. Zij zei: «Wat geef je mij, als je bij mij naar binnen gaat?»",""],"genesis-38-17":["Он сказал: «Я пришлю козлёнка из стада». Она сказала: «Дашь ли залог, пока не пришлёшь?»","Hij zei: «Ik zal je een geitenbokje uit de kudde sturen.» Zij zei: «Geef je een pand, tot je het stuurt?»",""],"genesis-38-18":["Он сказал: «Какой залог дать тебе?» Она сказала: «Твою печать, твой шнур и твой посох, который у тебя в руке». Он дал ей это, вошёл к ней, и она зачала от него.","Hij zei: «Welk pand zal ik je geven?» Zij zei: «Je zegel, je snoer en je staf die in je hand is.» Hij gaf het haar, ging bij haar naar binnen, en zij werd zwanger van hem.","JPS: came in unto her; фр.: approcha d’elle. По-еврейски וַיָּבֹא אֵלֶיהָ — вошёл к ней."],"genesis-38-19":["Она встала, ушла, сняла с себя покрывало и надела одежды своего вдовства.","Zij stond op, ging weg, legde haar sluier af en trok haar weduwkleren aan.",""],"genesis-38-20":["Йегуда послал козлёнка с другом своим, адулламитянином, чтобы взять залог из руки этой женщины, но тот не нашёл её.","Jehoeda stuurde het geitenbokje met zijn vriend, de Adullamiet, om het pand uit de hand van de vrouw terug te nemen, maar hij vond haar niet.",""],"genesis-38-21":["Он спросил людей её места: «Где посвящённая блудница, та, что в Энаиме у дороги?» Они сказали: «Здесь не было посвящённой блудницы».","Hij vroeg de mannen van haar plaats: «Waar is de gewijde vrouw, zij die in Enajim aan de weg was?» Zij zeiden: «Hier is geen gewijde vrouw geweest.»","JPS и фр. переводят הַקְּדֵשָׁה тем же словом, что זוֹנָה в 38:15: harlot / prostituée. По-еврейски это посвящённая женщина, другое слово."],"genesis-38-22":["Он вернулся к Йегуде и сказал: «Я не нашёл её. И люди этого места сказали: „Здесь не было посвящённой блудницы“».","Hij keerde terug naar Jehoeda en zei: «Ik heb haar niet gevonden. Ook de mannen van de plaats zeiden: „Hier is geen gewijde vrouw geweest.“»","Снова קְדֵשָׁה. JPS и фр. снова harlot / prostituée, как для זוֹנָה."],"genesis-38-23":["Йегуда сказал: «Пусть оставит себе, чтобы нам не стать посмешищем. Вот я послал этого козлёнка, а ты её не нашёл».","Jehoeda zei: «Laat zij het houden, anders worden wij tot schande. Zie, ik heb dit bokje gestuurd, en jij hebt haar niet gevonden.»","JPS: put to shame; фр.: rougir. По-еврейски לָבוּז — стать предметом презрения."],"genesis-38-24":["Около трёх месяцев спустя Йегуде сказали: «Тамар, твоя невестка, блудила, и вот она беременна от блуда». Йегуда сказал: «Выведите её, и пусть её сожгут».","Ongeveer drie maanden later berichtte men Jehoeda: «Tamar, je schoondochter, heeft zich verkocht, en zie, zij is zwanger doordat zij zich verkocht heeft.» Jehoeda zei: «Breng haar naar buiten, en laat haar verbrand worden.»",""],"genesis-38-25":["Её выводили. Она послала своему свёкру сказать: «Я беременна от человека, которому принадлежит это». И сказала: «Узнай, пожалуйста, чьи эта печать, эти шнуры и этот посох».","Men bracht haar naar buiten. Zij stuurde haar schoonvader deze boodschap: «Ik ben zwanger van de man aan wie deze dingen toebehoren.» En zij zei: «Herken toch van wie dit zegel, deze snoeren en deze staf zijn.»",""],"genesis-38-26":["Йегуда узнал их и сказал: «Она праведнее меня, потому что я не отдал её Шеле, моему сыну». И он больше не был с ней.","Jehoeda herkende ze en zei: «Zij is rechtvaardiger dan ik, want ik heb haar niet gegeven aan Sjela, mijn zoon.» En hij sliep niet meer met haar.",""],"genesis-38-27":["Когда пришло ей время родить, вот во чреве у неё близнецы.","Toen het haar tijd was om te baren, zie: een tweeling was in haar schoot.",""],"genesis-38-28":["Когда она рожала, один выставил руку. Повитуха взяла и повязала ему на руку алую нить, сказав: «Этот вышел первым».","Terwijl zij baarde, stak de ene een hand uit. De vroedvrouw nam die en bond een scharlaken draad om zijn hand, en zei: «Deze is het eerst naar buiten gekomen.»",""],"genesis-38-29":["Когда он отдёрнул руку, вышел его брат. Она сказала: «Как ты прорвал себе прорыв!» И назвали его Перец.","Toen hij zijn hand terugtrok, kwam zijn broer naar buiten. Zij zei: «Wat een bres heb je voor jezelf gebroken!» En men noemde hem Perets.","JPS: Wherefore hast thou made a breach; фр.: Avec quelle violence tu te fais jour. По-еврейски מַה־פָּרַצְתָּ עָלֶיךָ פָּרֶץ — какой прорыв ты себе прорвал."],"genesis-38-30":["Потом вышел его брат, у которого на руке была алая нить, и назвали его Зерах.","Daarna kwam zijn broer naar buiten, die de scharlaken draad om zijn hand had, en men noemde hem Zerach.",""],"zechariah-2-14":["«Ликуй и радуйся, дочь Цийона, ибо вот Я прихожу и поселюсь среди тебя», — слово Господа.","«Jubel en verheug je, dochter van Tsijon, want zie, Ik kom en Ik zal in je midden wonen», — woord van de Eeuwige.",""],"zechariah-2-15":["«Многие народы примкнут к Господу в тот день и станут Моим народом. Я поселюсь среди тебя, и ты узнаешь, что Господь воинств послал меня к тебе».","«Vele volken zullen zich op die dag bij de Eeuwige aansluiten en Mij tot volk zijn. Ik zal in je midden wonen, en jij zult weten dat de Eeuwige der legerscharen mij naar jou heeft gezonden.»",""],"zechariah-2-16":["Господь возьмёт Йегуду как свою долю на святой земле и снова изберёт Йерушалаим.","De Eeuwige zal Jehoeda als zijn deel in bezit nemen op de heilige grond en Jeroesjalajim opnieuw verkiezen.",""],"zechariah-2-17":["«Умолкни, всякая плоть, перед Господом, ибо Он пробудился из своего святого жилища».","«Wees stil, alle vlees, voor de Eeuwige, want Hij is ontwaakt uit zijn heilige woning.»","JPS: all flesh; фр.: toute créature. По-еврейски כָּל־בָּשָׂר — всякая плоть."],"zechariah-3-1":["Он показал мне Йехошуа, первосвященника. Тот стоял перед посланником Господа, а обвинитель стоял по правую руку от него, чтобы обвинять его.","Hij liet mij Jehosjoea zien, de hogepriester. Die stond voor de bode van de Eeuwige, en de aanklager stond aan zijn rechterhand om hem aan te klagen.",""],"zechariah-3-2":["Господь сказал обвинителю: «Пусть Господь укорит тебя, обвинитель, пусть укорит тебя Господь, избравший Йерушалаим. Разве этот — не головня, выхваченная из огня?»","De Eeuwige zei tegen de aanklager: «Laat de Eeuwige jou bestraffen, aanklager. Laat de Eeuwige die Jeroesjalajim heeft verkozen, jou bestraffen. Is hij niet een stuk brandhout, uit het vuur gerukt?»","JPS и фр.: Satan. По-еврейски הַשָּׂטָן с артиклем — обвинитель, не имя."],"zechariah-3-3":["А Йехошуа был одет в грязные одежды и стоял перед посланником.","Jehosjoea droeg vuile kleren en stond voor de bode.",""],"zechariah-3-4":["Он ответил и сказал тем, кто стоял перед ним: «Снимите с него грязные одежды». И сказал ему: «Смотри, Я снял с тебя твою вину и одену тебя в праздничные одежды».","Hij antwoordde en zei tegen hen die voor hem stonden: «Trek de vuile kleren van hem uit.» En hij zei tegen hem: «Zie, Ik heb je schuld van je weggenomen en Ik zal je in feestkleren kleden.»","JPS: robes; фр.: habits de prix. По-еврейски מַחֲלָצוֹת — праздничные одежды."],"zechariah-3-5":["Я сказал: «Пусть наденут ему на голову чистый тюрбан». Они надели чистый тюрбан ему на голову и одели его в одежды, а посланник Господа стоял рядом.","Ik zei: «Laten zij een reine tulband op zijn hoofd zetten.» Zij zetten de reine tulband op zijn hoofd en kleedden hem in kleren, en de bode van de Eeuwige stond erbij.","JPS: mitre; фр.: tiare. По-еврейски צָנִיף — тюрбан, головная повязка."],"zechariah-3-6":["Посланник Господа засвидетельствовал Йехошуа и сказал:","De bode van de Eeuwige betuigde aan Jehosjoea en zei:","JPS: forewarned; фр.: fit cette déclaration. По-еврейски וַיָּעַד — торжественно засвидетельствовал."],"zechariah-3-7":["«Так сказал Господь воинств: „Если ты будешь ходить Моими путями и хранить Мою стражу, и если также ты будешь судить Мой дом и стеречь Мои дворы, то Я дам тебе ходить среди этих стоящих.","«Zo zegt de Eeuwige der legerscharen: „Als je op Mijn wegen gaat en Mijn wacht houdt, en als ook jij over Mijn huis rechtspreekt en Mijn voorhoven bewaakt, dan geef Ik je te lopen tussen hen die hier staan.",""],"zechariah-3-8":["Слушай же, Йехошуа, первосвященник, ты и твои товарищи, которые сидят перед тобой: они — люди-знамение. Вот Я привожу Моего раба, отрасль.","Hoor toch, Jehosjoea, hogepriester, jij en je gezellen die voor je zitten: zij zijn mannen die een teken zijn. Zie, Ik breng Mijn dienaar, de spruit.","JPS: men that are a sign; фр.: personnages de marque. По-еврейски אַנְשֵׁי מוֹפֵת — люди-знамение. צֶמַח — отрасль, не титул."],"zechariah-3-9":["Ибо вот камень, который Я положил перед Йехошуа: на одном камне семь глаз. Вот Я вырезаю на нём резьбу, — слово Господа воинств, — и сниму вину этой земли в один день.","Want zie, de steen die Ik voor Jehosjoea heb gelegd: op één steen zeven ogen. Zie, Ik graveer zijn gravering, — woord van de Eeuwige der legerscharen, — en Ik neem de schuld van dat land weg op één dag.","JPS: seven facets; фр.: sept yeux. По-еврейски עֵינַיִם — семь глаз."],"zechariah-3-10":["В тот день, — слово Господа воинств, — вы будете звать каждый своего ближнего под виноградную лозу и под смоковницу“».","Op die dag, — woord van de Eeuwige der legerscharen, — zullen jullie ieder zijn naaste roepen onder de wijnstok en onder de vijgenboom.“»",""],"zechariah-4-1":["Посланник, который говорил со мной, вернулся и разбудил меня, как человека, которого будят ото сна.","De bode die met mij sprak, kwam terug en wekte mij, als een man die uit zijn slaap wordt gewekt.",""],"zechariah-4-2":["Он сказал мне: «Что ты видишь?» Я сказал: «Я увидел, и вот светильник, весь из золота, и чаша наверху него, и семь его лампад на нём, семь и семь трубок к лампадам, которые наверху него,","Hij zei tegen mij: «Wat zie je?» Ik zei: «Ik heb gezien, en zie: een lampenstandaard, helemaal van goud, met zijn schaal bovenop, en zijn zeven lampen erop, zeven en zeven tuiten naar de lampen die bovenop hem staan,","JPS: seven pipes, yea seven; фр.: sept conduits. По-еврейски שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת — семь и семь трубок."],"zechariah-4-3":["и две маслины при нём: одна справа от чаши, другая слева от неё».","en twee olijfbomen erbij, één rechts van de schaal en één links ervan.»",""],"zechariah-4-4":["Я ответил и сказал посланнику, который говорил со мной: «Что это, господин мой?»","Ik antwoordde en zei tegen de bode die met mij sprak: «Wat zijn deze dingen, mijn heer?»","JPS: my lord; фр.: Seigneur. По-еврейски אֲדֹנִי — обращение к посланнику, не имя Бога."],"zechariah-4-5":["Посланник, который говорил со мной, ответил мне: «Разве ты не знаешь, что это?» Я сказал: «Нет, господин мой».","De bode die met mij sprak antwoordde mij: «Weet je niet wat deze zijn?» Ik zei: «Nee, mijn heer.»","JPS: what these are; фр.: ce que signifient ces choses. По-еврейски מָה־הֵמָּה אֵלֶּה — что это, без «означают»."],"zechariah-4-6":["Он ответил и сказал мне: «Вот слово Господа к Зерубавелю: „Не силой и не мощью, но Моим духом, — сказал Господь воинств.","Hij antwoordde en zei tegen mij: «Dit is het woord van de Eeuwige tot Zeroebavel: „Niet door kracht en niet door vermogen, maar door Mijn geest, zegt de Eeuwige der legerscharen.",""],"zechariah-4-7":["Кто ты, великая гора, перед Зерубавелем? Стань равниной. Он вынесет верхний камень при криках: ‚Благоволение, благоволение ему!‘“».","Wie ben jij, grote berg, voor Zeroebavel? Word een vlakte. Hij zal de topsteen naar buiten brengen onder het geroep: ‚Gunst, gunst voor hem!‘“»","JPS: Grace, grace; фр.: Qu’elle est belle. По-еврейски חֵן חֵן לָהּ — благоволение камню; местоимение женского рода при אֶבֶן."],"genesis-41-53":["Семь лет изобилия, которые были в земле Египта, подошли к концу.","De zeven jaren van overvloed die er in het land Egypte waren, liepen ten einde.",""],"genesis-41-54":["Начались семь лет голода, как сказал Йосеф. Голод был во всех странах, а во всей земле Египта был хлеб.","De zeven jaren van honger braken aan, zoals Josef had gezegd. Er was honger in alle landen, maar in heel het land Egypte was er brood.",""],"genesis-41-55":["Вся земля Египта голодала, и народ воззвал к фараону о хлебе. Фараон сказал всему Египту: «Идите к Йосефу. Что он вам скажет, то и делайте».","Heel het land Egypte leed honger, en het volk riep tot de farao om brood. De farao zei tegen heel Egypte: «Ga naar Josef. Wat hij jullie zegt, dat moeten jullie doen.»",""],"genesis-41-56":["Голод был по всему лицу земли. Йосеф открыл всё, что в них было, и продавал зерно Египту. Голод в земле Египта стал сильным.","De honger lag over heel het oppervlak van de aarde. Josef opende alles wat daarin was en verkocht graan aan Egypte. De honger werd sterk in het land Egypte.",""],"genesis-41-57":["Со всей земли приходили в Египет, к Йосефу, покупать зерно, потому что голод стал сильным по всей земле.","Uit heel de aarde kwamen zij naar Egypte, naar Josef, om graan te kopen, want de honger was sterk geworden in heel de aarde.",""],"genesis-42-1":["Яаков увидел, что в Египте есть зерно, и сказал своим сыновьям: «Почему вы смотрите друг на друга?»","Jaäkov zag dat er graan was in Egypte, en hij zei tegen zijn zonen: «Waarom kijken jullie elkaar aan?»",""],"genesis-42-2":["Он сказал: «Вот, я слышал, что в Египте есть зерно. Спуститесь туда и купите нам оттуда, чтобы нам жить, а не умереть».","Hij zei: «Zie, ik heb gehoord dat er graan is in Egypte. Daal daarheen af en koop daar voor ons, zodat wij leven en niet sterven.»",""],"genesis-42-3":["Десять братьев Йосефа спустились купить зерно в Египте.","Tien broers van Josef daalden af om graan in Egypte te kopen.",""],"genesis-42-4":["Биньямина, брата Йосефа, Яаков не послал с братьями, потому что сказал: «Как бы не случилась с ним беда».","Binjamin, de broer van Josef, stuurde Jaäkov niet met zijn broers mee, want hij zei: «Anders overkomt hem een ongeluk.»",""],"genesis-42-5":["Сыновья Исраэля пришли купить зерно среди других пришедших, потому что в земле Кнаан был голод.","De zonen van Israël kwamen graan kopen te midden van de anderen die kwamen, want er was honger in het land Kenaän.",""],"genesis-42-6":["Йосеф был правителем над землёй, это он продавал зерно всему народу земли. Братья Йосефа пришли и поклонились ему лицами до земли.","Josef was de heerser over het land; hij was het die graan verkocht aan heel het volk van het land. De broers van Josef kwamen en bogen zich voor hem neer, met hun gezicht ter aarde.",""],"genesis-42-7":["Йосеф увидел своих братьев и узнал их, но держался с ними как чужой и говорил с ними жёстко. Он сказал им: «Откуда вы пришли?» Они сказали: «Из земли Кнаан, купить еду».","Josef zag zijn broers en herkende hen, maar hij deed zich aan hen als een vreemde voor en sprak hard tegen hen. Hij zei tegen hen: «Waar komen jullie vandaan?» Zij zeiden: «Uit het land Kenaän, om voedsel te kopen.»",""],"genesis-42-8":["Йосеф узнал братьев, а они его не узнали.","Josef herkende zijn broers, maar zij herkenden hem niet.",""],"genesis-42-9":["Йосеф вспомнил сны, которые он видел о них, и сказал им: «Вы шпионы. Вы пришли увидеть наготу земли».","Josef herinnerde zich de dromen die hij over hen gedroomd had, en hij zei tegen hen: «Jullie zijn spionnen. Jullie zijn gekomen om de naaktheid van het land te zien.»","JPS: nakedness of the land; фр.: côté faible. По-еврейски עֶרְוַת הָאָרֶץ — нагота земли."],"genesis-42-10":["Они сказали ему: «Нет, господин мой. Твои слуги пришли купить еду.","Zij zeiden tegen hem: «Nee, mijn heer. Je dienaren zijn gekomen om voedsel te kopen.",""],"genesis-42-11":["Все мы — сыновья одного человека, мы честные люди. Твои слуги не были шпионами».","Wij allen zijn zonen van één man, wij zijn eerlijke mensen. Je dienaren zijn geen spionnen geweest.»",""],"genesis-42-12":["Он сказал им: «Нет, вы пришли увидеть наготу земли».","Hij zei tegen hen: «Nee, jullie zijn gekomen om de naaktheid van het land te zien.»","JPS: nakedness of the land; фр.: côtés faibles. По-еврейски עֶרְוַת הָאָרֶץ — нагота земли."],"genesis-42-13":["Они сказали: «Нас, твоих слуг, двенадцать братьев, сыновей одного человека в земле Кнаан. Младший сегодня с нашим отцом, а одного нет».","Zij zeiden: «Wij, je dienaren, zijn twaalf broers, zonen van één man, in het land Kenaän. De jongste is vandaag bij onze vader, en de ene is er niet.»",""],"genesis-42-14":["Йосеф сказал им: «Именно это я вам и сказал: „вы шпионы“.","Josef zei tegen hen: «Dit is het wat ik tegen jullie gezegd heb: „jullie zijn spionnen“.",""],"genesis-42-15":["Этим вы будете испытаны. Как жив фараон, вы не выйдете отсюда, пока не придёт сюда ваш младший брат.","Hieraan zullen jullie getoetst worden. Zo waar de farao leeft: jullie gaan hier niet weg, tenzij jullie jongste broer hierheen komt.",""],"genesis-42-16":["Пошлите одного из вас, пусть он приведёт вашего брата, а вы будьте связаны. Ваши слова будут проверены: есть ли с вами правда. Если нет — как жив фараон, — вы шпионы».","Stuur één van jullie om jullie broer te halen, en blijf zelf gebonden. Jullie woorden zullen getoetst worden, of de waarheid bij jullie is. Zo niet — zo waar de farao leeft — jullie zijn spionnen.»",""],"genesis-42-17":["Он отдал их под стражу на три дня.","Hij zette hen drie dagen in bewaring.",""],"genesis-42-18":["На третий день Йосеф сказал им: «Сделайте это и живите. Бога я боюсь.","Op de derde dag zei Josef tegen hen: «Doe dit en leef. God vrees ik.","JPS: God; фр.: le Seigneur. По-еврейски הָאֱלֹהִים — Бог."],"genesis-42-19":["Если вы честные, пусть один ваш брат будет связан в доме вашей стражи, а вы идите, отвезите зерно для голода ваших домов.","Als jullie eerlijk zijn, laat dan één van jullie broers gebonden blijven in het huis van jullie bewaring, en ga heen, breng graan voor de honger van jullie huizen.",""],"genesis-42-20":["Младшего брата приведите ко мне. Тогда ваши слова подтвердятся, и вы не умрёте». Так они и сделали.","Breng jullie jongste broer bij mij. Dan zullen jullie woorden bevestigd worden, en jullie zullen niet sterven.» Zo deden zij.",""],"genesis-42-21":["Они сказали друг другу: «Правда, мы виновны перед нашим братом. Мы видели беду его души, когда он умолял нас, и не послушали. Поэтому эта беда и пришла на нас».","Zij zeiden tegen elkaar: «Werkelijk, wij zijn schuldig tegenover onze broer. Wij zagen de nood van zijn ziel toen hij ons smeekte, en wij luisterden niet. Daarom is deze nood over ons gekomen.»","JPS: guilty; фр.: punis. По-еврейски אֲשֵׁמִים — виновны."],"genesis-42-22":["Реувен ответил им: «Разве я не говорил вам: „не грешите против мальчика“, а вы не послушали? Вот, взыскивается и его кровь».","Reüven antwoordde hun: «Heb ik niet tegen jullie gezegd: „bega geen zonde tegen de jongen“, en jullie hebben niet geluisterd? Zie, ook zijn bloed wordt opgeëist.»",""],"genesis-42-23":["Они не знали, что Йосеф их понимает, потому что между ними был переводчик.","Zij wisten niet dat Josef hen verstond, want de tolk stond tussen hen in.",""],"genesis-42-24":["Он отвернулся от них и заплакал. Потом вернулся к ним, поговорил с ними, взял из них Шимона и связал его у них на глазах.","Hij keerde zich van hen af en huilde. Daarna kwam hij bij hen terug, sprak met hen, nam Sjimon uit hun midden en bond hem voor hun ogen vast.",""],"genesis-42-25":["Йосеф велел наполнить их кладь зерном, вернуть серебро каждого в его мешок и дать им припас на дорогу. Так им и сделали.","Josef gebood hun pakken met graan te vullen, ieders zilver in zijn zak terug te leggen en hun voedsel voor onderweg te geven. Zo werd het voor hen gedaan.",""],"genesis-42-26":["Они погрузили своё зерно на ослов и ушли оттуда.","Zij laadden hun graan op hun ezels en gingen daarvandaan.",""],"genesis-42-27":["Один из них открыл свой мешок, чтобы на ночлеге дать корм своему ослу, и увидел своё серебро: вот оно в отверстии его сумки.","Een van hen opende zijn zak om zijn ezel in het nachtverblijf voer te geven, en hij zag zijn zilver: zie, het lag in de opening van zijn reiszak.",""],"genesis-42-28":["Он сказал братьям: «Моё серебро возвращено, и вот оно в моей сумке». Сердце у них упало, они затрепетали и сказали друг другу: «Что это Бог сделал с нами?»","Hij zei tegen zijn broers: «Mijn zilver is teruggebracht, en zie, het ligt in mijn reiszak.» Hun hart bezweek, zij beefden en zeiden tegen elkaar: «Wat heeft God ons aangedaan?»","JPS: God hath done; фр.: le Seigneur nous prépare. По-еврейски אֱלֹהִים עָשָׂה — Бог сделал."],"genesis-42-29":["Они пришли к Яакову, своему отцу, в землю Кнаан и рассказали ему всё, что с ними случилось. Они сказали:","Zij kwamen bij Jaäkov, hun vader, in het land Kenaän en vertelden hem alles wat hun overkomen was. Zij zeiden:",""],"genesis-42-30":["«Человек, господин земли, говорил с нами жёстко и объявил нас шпионами этой земли.","«De man, de heer van het land, sprak hard met ons en zette ons neer als spionnen van het land.",""],"genesis-42-31":["Мы сказали ему: „мы честные люди, мы не были шпионами.","Wij zeiden tegen hem: „wij zijn eerlijke mensen, wij zijn geen spionnen geweest.",""],"genesis-42-32":["Нас двенадцать братьев, сыновей нашего отца. Одного нет, а младший сегодня с нашим отцом в земле Кнаан“.","Wij zijn twaalf broers, zonen van onze vader. De ene is er niet, en de jongste is vandaag bij onze vader in het land Kenaän.“",""],"genesis-42-33":["Человек, господин земли, сказал нам: „по этому я узнаю, что вы честные. Одного вашего брата оставьте у меня, возьмите на голод ваших домов и идите,","De man, de heer van het land, zei tegen ons: „hieraan zal ik weten dat jullie eerlijk zijn. Laat één van jullie broers bij mij, neem mee voor de honger van jullie huizen en ga,",""],"genesis-42-34":["а младшего брата приведите ко мне. Тогда я узнаю, что вы не шпионы, что вы честные. Вашего брата я отдам вам, и вы будете торговать в этой земле“».","en breng jullie jongste broer bij mij. Dan zal ik weten dat jullie geen spionnen zijn, dat jullie eerlijke mensen zijn. Jullie broer zal ik je geven, en jullie mogen handel drijven in het land.“»","JPS: traffic; фр.: circuler. По-еврейски תִּסְחָרוּ — будете торговать."],"genesis-42-35":["Они высыпали свои мешки, и вот у каждого в мешке узел его серебра. Они и их отец увидели узлы серебра и испугались.","Toen zij hun zakken leegden, zie: ieders bundel zilver zat in zijn zak. Zij en hun vader zagen hun bundels zilver en werden bang.",""],"genesis-42-36":["Яаков, их отец, сказал им: «Меня вы лишили детей. Йосефа нет, Шимона нет, а Биньямина хотите забрать. Всё это пало на меня».","Jaäkov, hun vader, zei tegen hen: «Mij hebben jullie van mijn kinderen beroofd. Josef is er niet, Sjimon is er niet, en Binjamin willen jullie meenemen. Dit alles is op mij neergekomen.»",""],"genesis-42-37":["Реувен сказал отцу: «Двух моих сыновей ты убьёшь, если я не приведу его к тебе. Отдай его в мою руку, и я верну его тебе».","Reüven zei tegen zijn vader: «Mijn twee zonen mag je doden als ik hem niet bij je terugbreng. Geef hem in mijn hand, en ik breng hem bij je terug.»",""],"genesis-42-38":["Он сказал: «Сын мой не спустится с вами. Его брат умер, и он один остался. Если на пути, которым вы пойдёте, с ним случится беда, вы с горем спустите мою седину в Шеол».","Hij zei: «Mijn zoon daalt niet met jullie af. Zijn broer is dood, en hij alleen is over. Overkomt hem een ongeluk op de weg die jullie gaan, dan brengen jullie mijn grijze haar in verdriet naar Sjeool.»",""],"genesis-43-1":["Голод в земле был тяжёлым.","De honger in het land was zwaar.",""],"genesis-43-2":["Когда они доели зерно, которое привезли из Египта, отец сказал им: «Вернитесь, купите нам немного еды».","Toen zij het graan opgegeten hadden dat zij uit Egypte hadden meegebracht, zei hun vader tegen hen: «Keer terug, koop een beetje voedsel voor ons.»",""],"genesis-43-3":["Йегуда сказал ему: «Тот человек строго предупредил нас: „вы не увидите моего лица, если ваш брат не будет с вами“.","Jehoeda zei tegen hem: «Die man heeft ons nadrukkelijk gewaarschuwd: „jullie zullen mijn gezicht niet zien als jullie broer niet bij jullie is“.",""],"genesis-43-4":["Если ты пошлёшь нашего брата с нами, мы спустимся и купим тебе еду.","Als je onze broer met ons meestuurt, dalen wij af en kopen wij voedsel voor je.",""],"genesis-43-5":["А если не пошлёшь, мы не спустимся, потому что тот человек сказал нам: „вы не увидите моего лица, если ваш брат не будет с вами“».","Maar als je hem niet meestuurt, dalen wij niet af, want de man heeft tegen ons gezegd: „jullie zullen mijn gezicht niet zien, tenzij jullie broer bij jullie is.“»",""],"genesis-43-6":["Исраэль сказал: «Зачем вы сделали мне зло, рассказав тому человеку, есть ли у вас ещё брат?»","Israël zei: «Waarom hebben jullie mij dit kwaad gedaan, de man te vertellen of jullie nog een broer hebben?»","JPS: whether ye had yet a brother; фр.: que vous avez encore un frère. По-еврейски הַעוֹד לָכֶם אָח — вопрос: есть ли у вас ещё брат."],"genesis-43-7":["Они сказали: «Этот человек настойчиво расспрашивал нас о нас самих и о нашей родне: „ваш отец ещё жив? есть ли у вас брат?“ Мы и ответили ему по этим словам. Разве могли мы знать, что он скажет: „сведите вашего брата вниз“?»","Zij zeiden: «Die man heeft ons dringend ondervraagd over onszelf en over onze familie: „leeft jullie vader nog? hebben jullie een broer?“ Wij hebben hem geantwoord naar die woorden. Konden wij weten dat hij zou zeggen: „breng jullie broer naar beneden“?»",""],"genesis-43-8":["Йегуда сказал Исраэлю, своему отцу: «Отпусти юношу со мной. Мы встанем и пойдём и будем жить, а не умрём — и мы, и ты, и наши малыши.","Jehoeda zei tegen Israël, zijn vader: «Stuur de jongen met mij mee. Wij zullen opstaan en gaan, en wij zullen leven en niet sterven, wij en jij en onze kleinen.",""],"genesis-43-9":["Я поручусь за него. С моей руки ты его потребуешь. Если я не приведу его к тебе и не поставлю его перед тобой, я буду виноват перед тобой все дни.","Ik sta borg voor hem. Uit mijn hand zul je hem opeisen. Als ik hem niet bij je breng en hem voor je neerzet, blijf ik alle dagen schuldig tegenover je.",""],"genesis-43-10":["Ведь если бы мы не медлили, мы бы уже дважды вернулись».","Want als wij niet hadden getalmd, waren wij nu al twee keer terug geweest.»",""],"numbers-7-54":["В восьмой день — князь сыновей Менаше, Гамлиэль, сын Педацура.","Op de achtste dag: de vorst van de zonen van Menasje, Gamliël, zoon van Pedatsoer.",""],"numbers-7-55":["Его приношение: одно серебряное блюдо, вес его сто тридцать, одна серебряная чаша в семьдесят шекелей по шекелю святилища. Оба наполнены тонкой мукой, смешанной с маслом, для мучного приношения.","Zijn offergave: één zilveren schotel, haar gewicht honderddertig, één zilveren schaal van zeventig sjekel, naar de sjekel van het heiligdom. Beide vol fijne bloem, gemengd met olie, voor een meeloffer.","У блюда в еврейском нет слова «шекель»: שְׁלֹשִׁים וּמֵאָה מִשְׁקָלָהּ. Шекель назван только у чаши. JPS добавляет shekels и к блюду."],"numbers-7-56":["один ковш, десять, из золота, полный благовоний;","één lepel, tien, van goud, vol wierook;","В стихе нет слова «шекель»: עֲשָׂרָה זָהָב. JPS и фр. добавляют sicles."],"numbers-7-57":["один молодой бык, один баран, один годовалый ягнёнок — для всесожжения;","één jonge stier, één ram, één eenjarig lam, voor een brandoffer;",""],"numbers-7-58":["один козёл — для жертвы за грех;","één geitenbok voor een zondoffer;",""],"numbers-7-59":["а для мирной жертвы — два вола, пять баранов, пять козлов, пять годовалых ягнят. Это приношение Гамлиэля, сына Педацура.","en voor het vredesoffer: twee ossen, vijf rammen, vijf bokken, vijf eenjarige lammeren. Dit is de offergave van Gamliël, zoon van Pedatsoer.","JPS: peace-offerings; фр.: sacrifice de rémunération. По-еврейски זֶבַח הַשְּׁלָמִים — мирная жертва."],"i-kings-7-40":["Хирам сделал умывальники, лопаты и чаши. Хирам закончил всю работу, которую делал для царя Шломо в доме Господа:","Chiram maakte de wasbekkens, de scheppen en de schalen. Chiram voltooide al het werk dat hij voor koning Sjlomo in het huis van de Eeuwige deed:","JPS: pots; фр.: cendriers. По-еврейски הַכִּיֹּרוֹת — умывальники, не горшки."],"i-kings-7-41":["два столба и две чаши наверший, что наверху столбов, и две сетки, чтобы покрыть две чаши наверший наверху столбов;","twee zuilen, en de twee schalen van de kapitelen boven op de zuilen, en de twee vlechtwerken om de twee schalen van de kapitelen boven op de zuilen te bedekken;",""],"i-kings-7-42":["и четыреста гранатовых яблок на две сетки, по два ряда гранатовых яблок на одну сетку, чтобы покрыть две чаши наверший, что на столбах;","en de vierhonderd granaatappels voor de twee vlechtwerken, twee rijen granaatappels voor het ene vlechtwerk, om de twee schalen van de kapitelen op de zuilen te bedekken;",""],"i-kings-7-43":["и десять подставок, и десять умывальников на подставках;","en de tien onderstellen, en de tien wasbekkens op de onderstellen;",""],"i-kings-7-44":["и одно море, и двенадцать быков под морем;","en de ene zee, en de twaalf ossen onder de zee;",""],"i-kings-7-45":["и горшки, и лопаты, и чаши. Все эти сосуды, которые Хирам сделал для царя Шломо в доме Господа, — из полированной бронзы.","en de potten, de scheppen en de schalen. Al deze voorwerpen die Chiram voor koning Sjlomo in het huis van de Eeuwige maakte, waren van gepolijst brons.","JPS: pots, brass; фр.: cendriers, cuivre. По-еврейски הַסִּירוֹת — горшки, נְחֹשֶׁת — бронза."],"i-kings-7-46":["В долине Ярдена царь отлил их в глинистой толще земли, между Суккот и Царетаном.","In de vlakte van de Jarden goot de koning ze in de dikke kleigrond, tussen Sukkot en Tsaretan.",""],"i-kings-7-47":["Шломо оставил все сосуды. Из-за чрезвычайного множества вес бронзы не был выяснен.","Sjlomo liet alle voorwerpen staan. Vanwege de zeer, zeer grote hoeveelheid werd het gewicht van het brons niet nagegaan.","JPS: brass; фр.: cuivre. По-еврейски נְחֹשֶׁת — бронза."],"i-kings-7-48":["Шломо сделал все сосуды, что в доме Господа: золотой жертвенник и стол, на котором хлеб присутствия, — из золота.","Sjlomo maakte alle voorwerpen die in het huis van de Eeuwige waren: het gouden altaar en de tafel waarop het brood van de aanwezigheid lag, van goud.","JPS: all the vessels; фр.: le reste des objets. По-еврейски כָּל־הַכֵּלִים — все сосуды."],"i-kings-7-49":["и светильники, пять справа и пять слева, перед внутренним святилищем, из чистого золота, и цветок, и лампады, и щипцы — из золота;","en de lampenstandaards, vijf rechts en vijf links, vóór het binnenste heiligdom, van zuiver goud, en de bloem, de lampen en de tangen, van goud;","JPS: flowers, tongs; фр.: fleurons, mouchettes. По-еврейски הַפֶּרַח — цветок, מֶלְקַחַיִם — щипцы."],"i-kings-7-50":["и кубки, и щипцы для нагара, и чаши, и ковши, и жаровни — из чистого золота, и петли для дверей внутреннего дома — Святая святых — и для дверей дома — Хейхала — из золота.","en de bekers, de snuiters, de schalen, de lepels en de vuurpannen, van zuiver goud, en de hengsels voor de deuren van het binnenste huis — het heilige der heiligen — en voor de deuren van het huis — de Hechal — van goud.","JPS: snuffers, fire-pans; фр.: couteaux, encensoirs. По-еврейски מְזַמְּרוֹת — щипцы для нагара, מַחְתּוֹת — жаровни."],"genesis-45-28":["Исраэль сказал: «Довольно. Йосеф, мой сын, ещё жив. Я пойду и увижу его, прежде чем умру».","Israël zei: «Het is genoeg. Josef, mijn zoon, leeft nog. Ik ga hem zien voordat ik sterf.»",""],"genesis-46-1":["Исраэль отправился со всем, что у него было, пришёл в Беэр-Шеву и принёс жертвы Богу своего отца Ицхака.","Israël ging op reis met alles wat hij had, kwam in Beër-Sjeva en bracht offers aan de God van zijn vader Jitschak.",""],"genesis-46-2":["Бог сказал Исраэлю в ночных видениях. Он сказал: «Яаков, Яаков». Тот сказал: «Вот я».","God sprak tot Israël in de visioenen van de nacht en zei: «Jaäkov, Jaäkov.» Hij antwoordde: «Hier ben ik.»",""],"genesis-46-3":["Он сказал: «Я — Бог, Бог твоего отца. Не бойся сойти в Египет, потому что там Я сделаю тебя великим народом.","Hij zei: «Ik ben God, de God van je vader. Wees niet bang om naar Egypte af te dalen, want daar zal Ik je tot een groot volk maken.","JPS: fear not; фр.: n'hésite point. По-еврейски אַל־תִּירָא — не бойся."],"genesis-46-4":["Я сам сойду с тобой в Египет, и Я же непременно выведу тебя обратно. Йосеф положит свою руку тебе на глаза».","Ik zelf zal met je naar Egypte afdalen, en Ik zal je ook zeker weer omhoog brengen. Josef zal zijn hand op je ogen leggen.»",""],"genesis-46-5":["Яаков поднялся из Беэр-Шевы. Сыновья Исраэля повезли Яакова, своего отца, своих маленьких детей и своих жён на повозках, которые фараон послал, чтобы везти его.","Jaäkov stond op uit Beër-Sjeva. De zonen van Israël brachten Jaäkov, hun vader, hun kleine kinderen en hun vrouwen weg op de wagens die de farao had gestuurd om hem te vervoeren.",""],"genesis-46-6":["Они взяли свой скот и своё имущество, которое приобрели в земле Кнаан, и пришли в Египет, Яаков и всё его потомство с ним.","Zij namen hun vee en hun have, die zij in het land Kenaän hadden verworven, en kwamen in Egypte, Jaäkov en heel zijn nageslacht met hem.",""],"genesis-46-7":["Своих сыновей и сыновей своих сыновей, своих дочерей и дочерей своих сыновей — всё своё потомство он привёл с собой в Египет.","Zijn zonen en de zonen van zijn zonen, zijn dochters en de dochters van zijn zonen, heel zijn nageslacht bracht hij met zich mee naar Egypte.",""],"genesis-46-8":["Вот имена сыновей Исраэля, пришедших в Египет. Яаков и его сыновья. Первенец Яакова — Реувен.","Dit zijn de namen van de zonen van Israël die naar Egypte kwamen. Jaäkov en zijn zonen. De eerstgeborene van Jaäkov: Reüven.",""],"genesis-46-9":["Сыновья Реувена: Ханох, Паллу, Хецрон и Карми.","De zonen van Reüven: Chanoch, Palloe, Chetsron en Karmi.",""],"genesis-46-10":["Сыновья Шимона: Йемуэль, Ямин, Охад, Яхин, Цохар и Шауль, сын кнаанеянки.","De zonen van Sjimon: Jemoeëel, Jamin, Ohad, Jachin, Tsochar en Sjaoel, de zoon van de Kenaänitische vrouw.",""],"genesis-46-11":["Сыновья Леви: Гершон, Кехат и Мерари.","De zonen van Levi: Gersjon, Kehat en Merari.",""],"genesis-46-12":["Сыновья Йегуды: Эр, Онан, Шела, Перец и Зерах. Эр и Онан умерли в земле Кнаан. Сыновьями Переца были Хецрон и Хамуль.","De zonen van Jehoeda: Er, Onan, Sjela, Perets en Zerach. Er en Onan stierven in het land Kenaän. De zonen van Perets waren Chetsron en Chamul.",""],"genesis-46-13":["Сыновья Иссахара: Тола, Пува, Йов и Шимрон.","De zonen van Jissachar: Tola, Poewa, Jov en Sjimron.",""],"genesis-46-14":["Сыновья Зевулуна: Серед, Элон и Яхлеэль.","De zonen van Zevuloen: Sered, Elon en Jachleëel.",""],"genesis-46-15":["Это сыновья Леи, которых она родила Яакову в Паддан-Араме, и Дина, его дочь. Всех душ его сыновей и дочерей — тридцать три.","Dit zijn de zonen van Lea, die zij aan Jaäkov baarde in Paddan-Aram, en Dina, zijn dochter. Alle zielen van zijn zonen en zijn dochters: drieëndertig.","JPS: Paddan-aram; фр.: territoire araméen. По-еврейски בְּפַדַּן אֲרָם — в Паддан-Араме."],"genesis-46-16":["Сыновья Гада: Цифйон, Хагги, Шуни, Эцбон, Эри, Ароди и Арели.","De zonen van Gad: Tsifjon, Chaggi, Sjoeni, Etsbon, Eri, Arodi en Areli.",""],"genesis-46-17":["Сыновья Ашера: Йимна, Йишва, Йишви, Берия и Серах, их сестра. Сыновья Берии: Хевер и Малкиэль.","De zonen van Asjer: Jimna, Jisjwa, Jisjwi, Beria en Serach, hun zuster. De zonen van Beria: Chever en Malkiëel.",""],"genesis-46-18":["Это сыновья Зилпы, которую Лаван дал Лее, своей дочери. Она родила их Яакову, шестнадцать душ.","Dit zijn de zonen van Zilpa, die Lavan aan Lea, zijn dochter, gaf. Zij baarde hen aan Jaäkov: zestien zielen.",""],"genesis-46-19":["Сыновья Рахели, жены Яакова: Йосеф и Биньямин.","De zonen van Rachel, de vrouw van Jaäkov: Josef en Binjamin.",""],"genesis-46-20":["У Йосефа в земле Египта родились дети, которых родила ему Аснат, дочь Поти-Фера, священника Она: Менаше и Эфраим.","Bij Josef werden in het land Egypte kinderen geboren, die Asnat, de dochter van Poti-Fera, priester van On, hem baarde: Menasje en Efrajim.",""],"genesis-46-21":["Сыновья Биньямина: Бела, Бехер, Ашбель, Гера, Нааман, Эхи, Рош, Муппим, Хуппим и Ард.","De zonen van Binjamin: Bela, Becher, Asjbel, Gera, Naäman, Echi, Rosj, Moeppim, Choeppim en Ard.",""],"genesis-46-22":["Это сыновья Рахели, которые родились у Яакова. Всех душ — четырнадцать.","Dit zijn de zonen van Rachel die bij Jaäkov geboren werden. Alle zielen: veertien.",""],"genesis-46-23":["Сыновья Дана: Хушим.","De zonen van Dan: Choesjim.",""],"genesis-46-24":["Сыновья Нафтали: Яхцеэль, Гуни, Йецер и Шиллем.","De zonen van Naftali: Jachtseël, Goeni, Jetser en Sjillem.",""],"genesis-46-25":["Это сыновья Билхи, которую Лаван дал Рахели, своей дочери. Она родила их Яакову. Всех душ — семь.","Dit zijn de zonen van Bilha, die Lavan aan Rachel, zijn dochter, gaf. Zij baarde hen aan Jaäkov. Alle zielen: zeven.",""],"genesis-46-26":["Всех душ, пришедших с Яаковом в Египет, вышедших из его бедра, не считая жён сыновей Яакова, — шестьдесят шесть.","Alle zielen die met Jaäkov naar Egypte kwamen, voortgekomen uit zijn dij, afgezien van de vrouwen van de zonen van Jaäkov: zesenzestig.","JPS: out of his loins; фр.: issues de lui. По-еврейски יֹצְאֵי יְרֵכוֹ — вышедшие из его бедра."],"genesis-46-27":["Сыновья Йосефа, родившиеся у него в Египте, — две души. Всех душ дома Яакова, пришедших в Египет, — семьдесят.","De zonen van Josef die hem in Egypte geboren werden: twee zielen. Alle zielen van het huis van Jaäkov die naar Egypte kwamen: zeventig.",""],"genesis-46-28":["Йегуду он послал перед собой к Йосефу, чтобы тот указал ему путь в Гошен. Они пришли в землю Гошен.","Jehoeda stuurde hij voor zich uit naar Josef, om hem de weg te wijzen naar Gosjen. Zij kwamen in het land Gosjen.","JPS: to show the way; фр.: préparât l'entrée. По-еврейски לְהוֹרֹת — указать путь."],"genesis-46-29":["Йосеф запряг свою колесницу и выехал навстречу Исраэлю, своему отцу, в Гошен. Он показался ему, упал ему на шею и ещё долго плакал у него на шее.","Josef spande zijn strijdwagen in en reed zijn vader Israël tegemoet, naar Gosjen. Hij liet zich aan hem zien, viel hem om de hals en huilde nog lang aan zijn hals.","JPS: presented himself; фр.: à sa vue. По-еврейски וַיֵּרָא אֵלָיו — он показался ему."],"genesis-46-30":["Исраэль сказал Йосефу: «Теперь я могу умереть, после того как увидел твоё лицо, ведь ты ещё жив».","Israël zei tegen Josef: «Nu kan ik sterven, nu ik je gezicht heb gezien, want je leeft nog.»",""],"genesis-46-31":["Йосеф сказал своим братьям и дому своего отца: «Я поднимусь, расскажу фараону и скажу ему: „Мои братья и дом моего отца, которые были в земле Кнаан, пришли ко мне.","Josef zei tegen zijn broers en tegen het huis van zijn vader: «Ik ga naar boven, ik vertel het de farao en ik zal tegen hem zeggen: „Mijn broers en het huis van mijn vader, die in het land Kenaän waren, zijn bij mij gekomen.",""],"genesis-46-32":["Эти люди — пастухи овец, потому что они были скотниками. Своих овец, свой крупный скот и всё, что у них есть, они привели“.","Die mannen zijn schaapherders, want zij waren veehouders. Hun schapen, hun runderen en alles wat van hen is, hebben zij meegebracht.“",""],"genesis-46-33":["Когда фараон позовёт вас и скажет: „Чем вы занимаетесь?“,","Wanneer de farao jullie laat roepen en zegt: „Wat is jullie werk?“,",""],"genesis-46-34":["вы скажете: „Твои рабы были скотниками с нашей юности и доныне, и мы, и наши отцы“. Чтобы вы жили в земле Гошен, потому что для Египта всякий пастух овец — мерзость».","dan zeggen jullie: „Jouw dienaren zijn veehouders geweest van onze jeugd af tot nu, wij en onze vaderen.“ Zo kunnen jullie in het land Gosjen wonen, want elke schaapherder is een gruwel voor Egypte.»",""],"ii-samuel-18-24":["Давид сидел между двумя воротами. Дозорный поднялся на крышу ворот, к стене, поднял глаза, посмотрел, и вот — человек бежит один.","David zat tussen de twee poorten. De wachter ging naar het dak van de poort, naar de muur, sloeg zijn ogen op, keek, en zie: een man kwam alleen aanrennen.",""],"ii-samuel-18-25":["Дозорный крикнул и сообщил царю. Царь сказал: «Если он один, во рту у него весть». Тот всё бежал и приближался.","De wachter riep en meldde het de koning. De koning zei: «Als hij alleen is, is er een bericht in zijn mond.» Hij kwam al rennend dichterbij.","JPS: tidings; фр.: bonne nouvelle. По-еврейски בְּשׂוֹרָה — весть; слово «добрая» стоит только в 18:27."],"ii-samuel-18-26":["Дозорный увидел: бежит другой человек. Дозорный крикнул привратнику: «Вот человек бежит один». Царь сказал: «И этот несёт весть».","De wachter zag een andere man rennen. De wachter riep naar de poortwachter: «Zie, een man rent alleen.» De koning zei: «Ook deze brengt bericht.»","JPS: tidings; фр.: bonne nouvelle. По-еврейски מְבַשֵּׂר — тот, кто несёт весть."],"ii-samuel-18-27":["Дозорный сказал: «Я вижу: бег первого — как бег Ахимааца, сына Цадока». Царь сказал: «Это хороший человек, и он придёт с доброй вестью».","De wachter zei: «Ik zie dat de loop van de eerste is als de loop van Achimaäts, de zoon van Tsadok.» De koning zei: «Dit is een goed man, en hij komt met een goede boodschap.»","JPS: I think; фр.: j'observe. По-еврейски אֲנִי רֹאֶה — я вижу."],"ii-samuel-18-28":["Ахимаац крикнул и сказал царю: «Благополучно». Он поклонился царю лицом до земли и сказал: «Благословен Господь, твой Бог, который отдал людей, поднявших руку на господина моего, царя».","Achimaäts riep en zei tegen de koning: «Het is goed.» Hij boog zich voor de koning, met het gezicht naar de aarde, en zei: «Gezegend is de Eeuwige, jouw God, die de mannen heeft overgegeven die hun hand hebben opgeheven tegen mijn heer de koning.»",""],"ii-samuel-18-29":["Царь сказал: «Благополучно ли с юношей, с Авшаломом?» Ахимаац сказал: «Я видел большое смятение, когда Йоав посылал слугу царя и твоего слугу, но я не знал, что это».","De koning zei: «Is het goed met de jongeman, met Avsjalom?» Achimaäts zei: «Ik zag een grote verwarring toen Joav de dienaar van de koning en jouw dienaar stuurde, maar ik wist niet wat het was.»",""],"ii-samuel-18-30":["Царь сказал: «Отойди, стань здесь». Тот отошёл и встал.","De koning zei: «Ga opzij en blijf hier staan.» Hij ging opzij en bleef staan.",""],"ii-samuel-18-31":["Вот пришёл кушит. Кушит сказал: «Пусть господин мой, царь, примет весть: сегодня Господь дал тебе суд из руки всех, кто восстал на тебя».","Daar kwam de Koesjiet. De Koesjiet zei: «Laat mijn heer de koning het bericht ontvangen: vandaag heeft de Eeuwige je recht verschaft uit de hand van allen die tegen je zijn opgestaan.»","JPS: avenged; фр.: a fait justice. По-еврейски שְׁפָטְךָ מִיַּד — дал тебе суд из руки."],"ii-samuel-18-32":["Царь сказал кушиту: «Благополучно ли с юношей, с Авшаломом?» Кушит сказал: «Пусть будут, как этот юноша, враги господина моего, царя, и все, кто восстал на тебя, чтобы сделать зло».","De koning zei tegen de Koesjiet: «Is het goed met de jongeman, met Avsjalom?» De Koesjiet zei: «Laten de vijanden van mijn heer de koning worden als die jongeman, en allen die tegen je zijn opgestaan om kwaad te doen.»",""],"ii-samuel-19-1":["Царь затрясся, поднялся в комнату над воротами и заплакал. На ходу он говорил так: «Сын мой Авшалом, сын мой, сын мой Авшалом! Если бы умер я вместо тебя, Авшалом, сын мой, сын мой!»","De koning beefde, ging naar de kamer boven de poort en huilde. Terwijl hij liep, zei hij: «Mijn zoon Avsjalom, mijn zoon, mijn zoon Avsjalom! Was ik maar gestorven in jouw plaats, Avsjalom, mijn zoon, mijn zoon!»",""],"ii-samuel-19-2":["Йоаву сообщили: «Вот царь плачет и скорбит об Авшаломе».","Aan Joav werd verteld: «Zie, de koning huilt en treurt om Avsjalom.»",""],"ii-samuel-19-3":["Избавление в тот день стало скорбью для всего народа, потому что народ услышал в тот день: «Царь горюет о своём сыне».","De redding werd op die dag tot rouw voor heel het volk, want het volk hoorde op die dag zeggen: «De koning treurt om zijn zoon.»",""],"ii-samuel-19-4":["Народ в тот день пробирался в город украдкой, как пробираются пристыженные, когда бегут с битвы.","Het volk sloop die dag de stad binnen, zoals beschaamde mensen wegsluipen wanneer zij uit de strijd vluchten.",""],"ii-samuel-19-5":["Царь закрыл лицо и закричал громким голосом: «Сын мой Авшалом! Авшалом, сын мой, сын мой!»","De koning bedekte zijn gezicht en schreeuwde met luide stem: «Mijn zoon Avsjalom! Avsjalom, mijn zoon, mijn zoon!»",""],"ii-samuel-19-6":["Йоав вошёл к царю в дом и сказал: «Сегодня ты покрыл стыдом лица всех твоих слуг, которые сегодня спасли твою жизнь, жизнь твоих сыновей и твоих дочерей, жизнь твоих жён и жизнь твоих наложниц,","Joav kwam bij de koning het huis binnen en zei: «Vandaag heb je de gezichten van al je dienaren beschaamd, die vandaag je leven hebben gered, het leven van je zonen en je dochters, het leven van je vrouwen en het leven van je bijvrouwen,",""],"ii-samuel-19-7":["тем, что любишь тех, кто тебя ненавидит, и ненавидишь тех, кто тебя любит. Сегодня ты объявил, что нет у тебя начальников и слуг. Сегодня я понял: если бы Авшалом был жив, а все мы сегодня мёртвы, тогда это было бы прямо в твоих глазах.","doordat je liefhebt wie jou haten, en haat wie jou liefhebben. Vandaag heb je verklaard dat je geen bevelhebbers en geen dienaren hebt. Vandaag zie ik: als Avsjalom had geleefd en wij allen vandaag dood waren, dan was dat recht in jouw ogen.","JPS: princes; фр.: officiers. По-еврейски שָׂרִים — начальники."],"ii-samuel-19-8":["Теперь встань, выйди и скажи по сердцу твоим слугам. Клянусь Господом: если ты не выйдешь, ни один человек не останется с тобой эту ночь. И это будет для тебя хуже всего зла, которое приходило на тебя от юности твоей доныне».","Sta nu op, ga naar buiten en spreek tot het hart van je dienaren. Ik zweer bij de Eeuwige: als jij niet naar buiten gaat, blijft er deze nacht geen mens bij je. Dat zal erger voor je zijn dan al het kwaad dat je is overkomen van je jeugd af tot nu.»",""],"ii-samuel-19-9":["Царь встал и сел в воротах. Всему народу сказали: «Вот царь сидит в воротах». Весь народ пришёл к царю, а Исраэль бежал, каждый к своим шатрам.","De koning stond op en ging in de poort zitten. Aan heel het volk werd gezegd: «Zie, de koning zit in de poort.» Heel het volk kwam voor de koning, en Israël vluchtte, ieder naar zijn tenten.",""],"genesis-49-1":["Яаков позвал своих сыновей и сказал: «Соберитесь, и я скажу вам, что случится с вами в конце дней.","Jaäkov riep zijn zonen en zei: «Kom bijeen, ik zal jullie zeggen wat jullie zal overkomen aan het einde der dagen.","JPS: end of days; фр.: la suite des jours. По-еврейски בְּאַחֲרִית הַיָּמִים — в конце дней."],"genesis-49-2":["Сойдитесь и слушайте, сыновья Яакова, слушайте Исраэля, вашего отца.","Schaar u samen en hoor, zonen van Jaäkov, hoor naar Israël, jullie vader.",""],"genesis-49-3":["Реувен, ты мой первенец, моя сила и первый плод моей крепости, превосходство достоинства и превосходство мощи.","Reüven, jij bent mijn eerstgeborene, mijn kracht en de eersteling van mijn sterkte, voorrang in waardigheid en voorrang in macht.","JPS: my might; фр.: mon orgueil. По-еврейски כֹּחִי — моя сила."],"genesis-49-4":["Неустойчив, как вода, — не тебе превосходство, потому что ты взошёл на ложе своего отца. Тогда ты осквернил моё ложе. Он взошёл.","Onstabiel als water — de voorrang is niet voor jou, want je bent op het bed van je vader geklommen. Toen heb je mijn ligplaats ontwijd. Hij klom erop.","JPS: have not the excellency, и в конце «он взошёл»; фр.: tu as perdu ta noblesse, без третьего лица. По-еврейски אַל־תּוֹתַר и עָלָה."],"genesis-49-5":["Шимон и Леви — братья. Их мечи — орудия насилия.","Sjimon en Levi zijn broers. Hun zwaarden zijn werktuigen van geweld.","מְכֵרֹתֵיהֶם тёмное: JPS kinship, фр. armes, по огласовке ближе к «их мечи»."],"genesis-49-6":["В их совет не входи, душа моя, к их собранию не примыкай, слава моя, потому что в гневе своём они убили человека и по своей воле подрезали жилы быку.","Kom niet in hun raad, mijn ziel, voeg je niet bij hun samenkomst, mijn eer, want in hun woede hebben zij een man gedood en naar eigen wil een stier de pezen doorgesneden.","JPS: houghed oxen и 3-е лицо; фр.: frappé des taureaux, обращение к душе. По-еврейски עִקְּרוּ־שׁוֹר — подрезали жилы быку, אַל־תָּבֹא — «не входи»."],"genesis-49-7":["Проклят их гнев, потому что он силён, и их ярость, потому что она жестока. Я разделю их в Яакове и рассею их в Исраэле.","Vervloekt is hun woede, want die is hevig, en hun grimmigheid, want die is hard. Ik zal hen verdelen in Jaäkov en hen verstrooien in Israël.",""],"genesis-49-8":["Йегуда, тебя будут славить твои братья. Твоя рука — на затылке твоих врагов. Сыновья твоего отца поклонятся тебе.","Jehoeda, jou zullen je broers prijzen. Je hand is op de nek van je vijanden. De zonen van je vader zullen zich voor je buigen.",""],"genesis-49-9":["Львёнок — Йегуда. От добычи, сын мой, ты поднялся. Он припал, он лёг, как лев и как львица. Кто поднимет его?","Een leeuwenwelp is Jehoeda. Van de prooi, mijn zoon, ben je opgestegen. Hij kromde zich, hij lag neer als een leeuw en als een leeuwin. Wie zal hem doen opstaan?","JPS: lioness; фр.: léopard. По-еврейски לָבִיא — львица."],"genesis-49-10":["Не отойдёт посох от Йегуды и жезл правителя из промежутка между его ног, пока не придёт Шило, и ему — покорность народов.","De staf zal niet wijken van Jehoeda, noch de heersersstaf van tussen zijn voeten, totdat Sjilo komt, en hem behoort de gehoorzaamheid van de volken.","שִׁילֹה неясно: JPS добавляет men и меняет синтаксис, фр. Pacifique — мессианский пересказ, по-еврейски עַד כִּי־יָבֹא שִׁילֹה — пока не придёт Шило."],"genesis-49-11":["Он привязывает к лозе своего ослёнка и к отборной лозе сына своей ослицы. В вине он стирает свою одежду, в крови винограда — своё одеяние.","Hij bindt aan de wijnstok zijn ezeljong en aan de edele rank het jong van zijn ezelin. In wijn wast hij zijn kleed, in druivenbloed zijn gewaad.",""],"genesis-49-12":["Тёмно-красные глаза от вина и белые зубы от молока.","Donkerrode ogen van wijn, en witte tanden van melk.","JPS: red with wine; фр.: pétillants. По-еврейски חַכְלִילִי — тёмно-красные, покрасневшие."],"genesis-49-13":["Зевулун будет жить у берега морей. Он — берег для кораблей, и его край у Цидона.","Zevuloen zal wonen aan de oever van de zeeën. Hij is een oever voor schepen, en zijn flank ligt bij Tsidon.","JPS: his flank; фр.: sa plage. По-еврейски יַרְכָתוֹ — его бок, край."],"genesis-49-14":["Иссахар — костистый осёл, он лежит между загонами.","Jissachar is een bonkige ezel, hij ligt tussen de schaapskooien.","JPS: large-boned ass, sheep-folds; фр.: âne musculeux, collines. По-еврейски חֲמֹר גָּרֶם — костистый осёл, הַמִּשְׁפְּתָיִם — загоны."],"genesis-49-15":["Он увидел, что покой хорош и что земля приятна, подставил плечо, чтобы нести, и стал рабом барщины.","Hij zag dat de rust goed was en het land aangenaam. Hij boog zijn schouder om te dragen en werd een knecht voor herendienst.","JPS: the land, servant under task-work; фр.: pâturage, tributaire. По-еврейски הָאָרֶץ — земля, לְמַס־עֹבֵד — раб барщины."],"genesis-49-16":["Дан будет судить свой народ, как одно из колен Исраэля.","Dan zal zijn volk richten, als een van de stammen van Israël.","JPS: as one of the tribes; фр.: sous lui se grouperont les tribus. По-еврейски כְּאַחַד שִׁבְטֵי יִשְׂרָאֵל — как одно из колен."],"genesis-49-17":["Дан будет змеем на дороге, рогатой змеёй на тропе, он жалит коня в пятки, и всадник падает назад.","Dan zal een slang op de weg zijn, een hoornslang op het pad, die de hielen van het paard bijt, zodat zijn ruiter achterover valt.","JPS: horned snake, heels; фр.: aspic, le pied. По-еврейски שְׁפִיפֹן — рогатая змея, עִקְּבֵי — пятки."],"genesis-49-18":["Твоего спасения жду я, Господь.","Op Uw redding wacht ik, Eeuwige.","JPS: salvation; фр.: assistance. По-еврейски יְשׁוּעָתְךָ — Твоё спасение."],"genesis-49-19":["Гад: отряд будет набегать на него, а он набежит им в пяту.","Gad: een bende zal hem overvallen, en hij valt aan op de hiel.","JPS сохраняет heel; фр. без пятки. По-еврейски עָקֵב — пята."],"genesis-49-20":["У Ашера тучен его хлеб, и он даст лакомства царя.","Van Asjer is zijn brood vet, en hij geeft lekkernijen van een koning.","JPS: his bread shall be fat; фр.: production abondante. По-еврейски שְׁמֵנָה לַחְמוֹ — тучен его хлеб."],"genesis-49-21":["Нафтали — лань, пущенная на волю. Он даёт прекрасные слова.","Naftali is een hinde die losgelaten is. Hij geeft schone woorden.",""],"genesis-49-22":["Плодоносный сын — Йосеф, плодоносный сын у источника. Дочери шагнули на стену.","Een vruchtbare zoon is Josef, een vruchtbare zoon bij een bron. Dochters schreden over de muur.","JPS: fruitful vine, branches; фр.: rameau fertile. По-еврейски בֵּן פֹּרָת — плодоносный сын, בָּנוֹת — дочери."],"genesis-49-23":["Его огорчили, стреляли в него и возненавидели его владельцы стрел.","Zij verbitterden hem, zij schoten op hem en haatten hem, de meesters van de pijlen.",""],"genesis-49-24":["Но его лук остался твёрд, и мышцы его рук стали гибки — от рук Могучего Яакова, оттуда Пастырь, Камень Исраэля,","Maar zijn boog bleef vast, en de spieren van zijn armen werden lenig, door de handen van de Machtige van Jaäkov, vandaar de Herder, de Steen van Israël,","וַיָּפֹזּוּ спорно: JPS supple, фр. fermes, а конец фр. пересказывает как «готовил жизнь скале»; по-еврейски Пастырь и Камень Исраэля."],"genesis-49-25":["от Бога твоего отца, и Он поможет тебе, и от Шаддая, и Он благословит тебя благословениями неба сверху, благословениями бездны, что залегла внизу, благословениями грудей и утробы.","van de God van je vader, en Hij zal je helpen, en van Sjaddai, en Hij zal je zegenen met zegeningen van de hemel boven, zegeningen van de diepte die beneden neerligt, zegeningen van borsten en schoot.","JPS: the Almighty; фр.: le Tout-Puissant. В стихе имя שַׁדַּי, не перевод «Всемогущий»."],"genesis-49-26":["Благословения твоего отца сильнее благословений моих родителей, до края вечных холмов. Они будут на голове Йосефа и на темени отделённого среди его братьев.","De zegeningen van je vader zijn sterker dan de zegeningen van mijn ouders, tot de grens van de eeuwige heuvels. Zij zullen op het hoofd van Josef zijn en op de schedel van de afgezonderde onder zijn broers.","JPS: prince; фр.: l'Élu. По-еврейски נְזִיר אֶחָיו — отделённый среди братьев."],"genesis-49-27":["Биньямин — волк, он рвёт. Утром он ест добычу, а к вечеру делит награбленное».","Binjamin is een wolf die verscheurt. In de morgen eet hij de prooi, en tegen de avond verdeelt hij de buit.»",""],"genesis-49-28":["Все эти — двенадцать колен Исраэля, и вот что сказал им их отец. Он благословил их, каждого по его благословению он благословил.","Dit alles zijn de twaalf stammen van Israël, en dit is wat hun vader tot hen sprak. Hij zegende hen, ieder naar zijn eigen zegen zegende hij hen.",""],"genesis-49-29":["Он дал им наказ и сказал им: «Меня забирают к моему народу. Похороните меня с моими отцами в пещере, которая на поле Эфрона-хетта,","Hij gebood hun en zei tegen hen: «Ik word verzameld bij mijn volk. Begraaf mij bij mijn vaderen in de grot die op het veld van Efron de Chitti ligt,",""],"genesis-49-30":["в пещере, которая на поле Махпела, что против Мамре, в земле Кнаан. Это поле Авраам купил у Эфрона-хетта во владение для погребения,","in de grot die op het veld Machpela ligt, tegenover Mamre, in het land Kenaän. Dat veld kocht Abraham van Efron de Chitti als eigen grafgrond,",""],"genesis-49-31":["там похоронили Авраама и Сару, его жену, там похоронили Ицхака и Ривку, его жену, и там я похоронил Леу.","daar begroeven zij Abraham en Sara, zijn vrouw, daar begroeven zij Jitschak en Rivka, zijn vrouw, en daar begroef ik Lea.",""],"genesis-49-32":["Купля поля и пещеры, которая на нём, — у сыновей Хета».","De koop van het veld en de grot die daarin is, van de zonen van Chet.»",""],"genesis-49-33":["Яаков закончил давать наказ своим сыновьям, подобрал ноги на постель, испустил дыхание и был взят к своим народам.","Jaäkov was klaar met zijn zonen te gebieden. Hij trok zijn voeten op het bed, blies de adem uit en werd verzameld bij zijn volken.",""],"genesis-50-22":["Йосеф жил в Египте, он и дом его отца. Йосеф прожил сто десять лет.","Josef woonde in Egypte, hij en het huis van zijn vader. Josef leefde honderdtien jaar.",""],"genesis-50-23":["Йосеф видел у Эфраима сыновей третьего поколения. Также сыновья Махира, сына Менаше, родились на коленях Йосефа.","Josef zag van Efrajim zonen van het derde geslacht. Ook de zonen van Machir, de zoon van Menasje, werden op de knieën van Josef geboren.",""],"genesis-50-24":["Йосеф сказал своим братьям: «Я умираю. Бог непременно вспомнит о вас и выведет вас из этой земли в землю, о которой Он клялся Аврааму, Ицхаку и Яакову».","Josef zei tegen zijn broers: «Ik sterf. God zal zeker aan jullie denken en jullie uit dit land brengen naar het land dat Hij onder ede heeft beloofd aan Abraham, aan Jitschak en aan Jaäkov.»","JPS: remember; фр.: visitera. По-еврейски פָּקֹד יִפְקֹד — непременно вспомнит, обратит внимание."],"genesis-50-25":["Йосеф взял клятву с сыновей Исраэля и сказал: «Бог непременно вспомнит о вас, и вы вынесете мои кости отсюда».","Josef nam een eed af van de zonen van Israël en zei: «God zal zeker aan jullie denken, en dan brengen jullie mijn beenderen hiervandaan.»","JPS: remember; фр.: visitera. По-еврейски פָּקֹד יִפְקֹד — непременно вспомнит, обратит внимание."],"genesis-50-26":["Йосеф умер ста десяти лет. Его набальзамировали и положили в гроб в Египте.","Josef stierf, honderdtien jaar oud. Men balsemde hem en legde hem in een kist in Egypte.",""],"isaiah-38-9":["Запись Хизкиягу, царя Йегуды, когда он болел и выжил от своей болезни.","Het geschrift van Chizkiahoe, koning van Jehoeda, toen hij ziek was en van zijn ziekte in leven bleef.","JPS: writing; фр.: cantique. По-еврейски מִכְתָּב — запись."],"isaiah-38-10":["Я сказал: «В половине моих дней я войду во врата Шеола. Я лишён остатка моих лет».","Ik zei: «In de helft van mijn dagen zal ik de poorten van Sjeool binnengaan. Ik ben beroofd van de rest van mijn jaren.»","JPS: noontide of my days; фр.: ruine de mes jours. По-еврейски בִּדְמִי יָמַי — в половине моих дней."],"isaiah-38-11":["Я сказал: «Не увижу я Господа, Господа, в земле живых. Не взгляну больше на человека среди жителей преходящего».","Ik zei: «Ik zal de Eeuwige, de Eeuwige, niet zien in het land van de levenden. Ik zal geen mens meer aanschouwen bij de bewoners van het vergankelijke.»","В стихе дважды краткое יָהּ, не полное יהוה. JPS: the LORD; фр.: Dieu, mon Dieu. חָדֶל: JPS world, фр. néant — преходящее."],"isaiah-38-12":["Моё жилище снято и унесено от меня, как шатёр пастуха. Я скатал, как ткач, свою жизнь. От свисающих нитей Он отрежет меня. От дня до ночи Ты покончишь со мной.","Mijn woning is afgebroken en van mij weggedragen, als een tent van een herder. Ik heb als een wever mijn leven opgerold. Van de losse draden snijdt Hij mij af. Van dag tot nacht maakt U een einde aan mij.",""],"isaiah-38-13":["Я держался до утра. Как лев, так Он дробит все мои кости. От дня до ночи Ты покончишь со мной.","Ik hield mij tot de morgen. Als een leeuw, zo verbrijzelt Hij al mijn beenderen. Van dag tot nacht maakt U een einde aan mij.","JPS относит «как лев» к говорящему; фр. — к тому, кто ломает кости. По-еврейски כָּאֲרִי כֵּן יְשַׁבֵּר — как лев, так он дробит."],"isaiah-38-14":["Как ласточка, как журавль, так я щебечу, стону, как голубь. Глаза мои истомились, глядя ввысь. Владыка, мне тесно, будь мне порукой.","Als een zwaluw, als een kraanvogel, zo kwetter ik, ik kreun als een duif. Mijn ogen zijn moe van het opzien. Heer, het is mij te nauw, wees mijn borg.","Обращение אֲדֹנָי, не יהוה: Владыка / Heer. JPS: swallow or a crane; фр.: только hirondelle. По-еврейски סוּס и עָגוּר — ласточка и журавль."],"isaiah-38-15":["Что мне сказать? Он сказал мне, и Он сделал это. Все мои годы я буду ходить тихо из-за горечи моей души.","Wat zal ik zeggen? Hij heeft tot mij gesproken, en Hij heeft het gedaan. Al mijn jaren zal ik langzaam gaan om de bitterheid van mijn ziel.","JPS: go softly; фр.: avec humilité. По-еврейски אֶדַּדֶּה — пойду медленно, без «смирения»."],"isaiah-38-16":["Владыка, ими живут, и во всём, что в них, — жизнь моего духа. Укрепи меня и оживи меня.","Heer, daardoor leven zij, en in alles daarin is het leven van mijn geest. Maak mij sterk en laat mij leven.","Обращение אֲדֹנָי, не יהוה: Владыка / Heer. Стих тёмный: JPS — просьба укрепить и оживить, фр. делает из этого долг живущих и прошедшее «ты вернул силы»."],"isaiah-38-17":["Вот, ради цельности горько было мне, горько. А Ты в любви удержал мою душу от ямы гибели, потому что бросил за Свою спину все мои грехи.","Zie, om heelheid was het mij bitter, bitter. Maar U hebt in liefde mijn ziel van de kuil van het verderf afgehouden, want U hebt al mijn zonden achter Uw rug geworpen.","JPS: for my peace I had bitterness; фр.: горечь сменилась миром. По-еврейски לְשָׁלוֹם מַר־לִי מָר — ради цельности горько было."],"isaiah-38-18":["Ведь не Шеол славит Тебя, не смерть хвалит Тебя. Сходящие в яму не надеются на Твою истину.","Want Sjeool looft U niet, de dood prijst U niet. Wie in de kuil afdalen, hopen niet op Uw waarheid.",""],"isaiah-38-19":["Живой, живой — он славит Тебя, как я сегодня. Отец детям возвещает Твою истину.","De levende, de levende, hij looft U, zoals ik vandaag. De vader maakt aan de kinderen Uw waarheid bekend.",""],"isaiah-38-20":["Господь — чтобы спасти меня. Мои песни мы будем играть на струнах все дни нашей жизни у дома Господа.","De Eeuwige is er om mij te redden. Mijn snarenspel zullen wij spelen, al de dagen van ons leven, bij het huis van de Eeuwige.","JPS: the LORD is ready to save me; фр.: je te dois mon salut. По-еврейски יְהֹוָה לְהוֹשִׁיעֵנִי — Господь, чтобы спасти меня."]} as const;

const BOOK_SLUG: Record<string, string> = {
  Genesis: 'genesis',
  Numbers: 'numbers',
  Joshua: 'joshua',
  I_Samuel: 'i-samuel',
  II_Samuel: 'ii-samuel',
  I_Kings: 'i-kings',
  Isaiah: 'isaiah',
  Proverbs: 'proverbs',
  Zechariah: 'zechariah',
};

/** The draft line for this Sefaria range and verse, or null when this span was not prepared. */
export function draftLine(sefariaRef: string, chapter: number, verse: number): DraftLine | null {
  const book = BOOK_SLUG[sefariaRef.split('.')[0] ?? ''];
  if (!book) return null;
  const row = LINES[`${book}-${chapter}-${verse}`];
  if (!row) return null;
  return { ru: row[0], nl: row[1], note: row[2] };
}

export const DRAFT_VERSE_COUNT = Object.keys(LINES).length;
